    def rewrite_body(
        lines: Iterable[str], replacements: dict[str, str]
    ) -> tuple[str, ...]:
        rewritten = []
        for line in lines:
            for before, after in replacements.items():
                line = line.replace(before, after)
            rewritten.append(line)
        return tuple(rewritten)

