TITLE_XGETDEVICES_ADDRESS = 0x0028D282
TITLE_XINPUT_OPEN_ADDRESS = 0x0028CF40
TITLE_XINPUT_GET_CAPABILITIES_ADDRESS = 0x0028CFA2
TITLE_XINPUT_GET_STATE_ADDRESS = 0x0028D180
