FILE_WRITE_DATA = 0x00000002
GENERIC_WRITE = 0x40000000
FILE_SUPERSEDE = 0
FILE_OPEN = 1
FILE_CREATE = 2
FILE_OPEN_IF = 3
FILE_OVERWRITE = 4
FILE_OVERWRITE_IF = 5
FILE_DIRECTORY_FILE = 0x00000001
MEM_COMMIT = 0x00001000


class RuntimeAbiBridgeError(RuntimeError):
    """Raised when a recovered guest call cannot be adapted to a shim handler."""


class BootProbeStop(RuntimeError):
    """Internal sentinel used to stop cleanly at unrecovered code handoffs."""

    def __init__(
        self,
        *,
        target: int,
        stack_args: tuple[int, ...],
        state: CpuState,
        trace: ExecutionTrace,
    ) -> None:
        super().__init__(f"stopped at unrecovered internal call 0x{target:08X}")
        self.target = target
        self.stack_args = stack_args
        self.state = state
        self.trace = trace


class RenderWatchpointStop(RuntimeError):
    """Internal sentinel used to stop after a requested render-write count."""

    def __init__(self, stream: dict[str, Any]) -> None:
        super().__init__("render write watchpoint limit reached")
        self.stream = stream


class TitleSpinDelayFastPath:
    """Fast-path the observed title spin-delay loop without spending step budget."""

    def __init__(
        self,
        *,
        address: int = TITLE_SPIN_DELAY_ADDRESS,
        iterations: int = TITLE_SPIN_DELAY_ITERATIONS,
        tsc_advance: int = TITLE_SPIN_DELAY_TSC_ADVANCE,
    ) -> None:
        self.address = address
        self.iterations = iterations
        self.tsc_advance = tsc_advance
        self.invocation_count = 0

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.address: self.call_handler}

    def call_handler(
        self,
        cpu: CpuState,
        _memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        self.invocation_count += 1
        cpu.set_register("eax", 0)
        cpu.timestamp_counter = (
            cpu.timestamp_counter + self.tsc_advance
        ) & 0xFFFFFFFFFFFFFFFF
        cpu.flags.zf = True
        cpu.flags.sf = False
        cpu.flags.pf = True
        cpu.flags.af = False
        cpu.flags.of = False
        trace.add(
            target,
            "title_spin_delay_fast_path",
            iterations=self.iterations,
            invocation_count=self.invocation_count,
            timestamp_counter=cpu.timestamp_counter,
            timestamp_counter_hex=f"0x{cpu.timestamp_counter:016X}",
        )

    def summary(self) -> dict[str, Any]:
        return {
            "address": self.address,
            "address_hex": _hex32(self.address),
            "iterations": self.iterations,
            "timestamp_counter_advance_per_call": self.tsc_advance,
            "invocation_count": self.invocation_count,
        }


class TitleXInputFastPath:
    """Bind the title's XAPILIB 5344 input calls to the runtime input shim."""

    def __init__(self, input_shim: Any) -> None:
        self.input = input_shim
        self.get_devices_count = 0
        self.open_count = 0
        self.capabilities_count = 0
        self.get_state_count = 0
        self.successful_get_state_count = 0
        self.observed_button_mask = 0
        self.a_pressed_poll_count = 0
        self._last_states: dict[int, ControllerState] = {}
        self._packets = [0, 0, 0, 0]

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {
            TITLE_XGETDEVICES_ADDRESS: self.get_devices_handler,
            TITLE_XINPUT_OPEN_ADDRESS: self.open_handler,
            TITLE_XINPUT_GET_CAPABILITIES_ADDRESS: self.capabilities_handler,
            TITLE_XINPUT_GET_STATE_ADDRESS: self.get_state_handler,
        }

    @staticmethod
    def _handle_for_port(port: int) -> int:
        return TITLE_XINPUT_HANDLE_BASE + port

    @staticmethod
    def _port_from_handle(handle: int) -> int | None:
        port = handle - TITLE_XINPUT_HANDLE_BASE
        return port if 0 <= port < 4 else None

    def get_devices_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        states = self.input.poll_all()
        mask = sum(1 << port for port, state in states.items() if state.connected)
        cpu.set_register("eax", mask)
        _prepare_stdcall_return(cpu, memory, 4)
        self.get_devices_count += 1
        trace.add(target, "title_xgetdevices_fast_path", connected_mask=mask)

    def open_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        _device_type, port, _slot, _polling = _read_stack_arguments(
            memory, cpu.get_register("esp"), 4
        )
        state = self.input.poll_controller(port) if port < 4 else ControllerState()
        handle = self._handle_for_port(port) if state.connected else 0
        cpu.set_register("eax", handle)
        _prepare_stdcall_return(cpu, memory, 16)
        self.open_count += 1
        trace.add(
            target,
            "title_xinput_open_fast_path",
            port=port,
            connected=state.connected,
            handle=handle,
            handle_hex=_hex32(handle),
        )

    def capabilities_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        handle, capabilities_address = _read_stack_arguments(
            memory, cpu.get_register("esp"), 2
        )
        port = self._port_from_handle(handle)
        connected = port is not None and self.input.poll_controller(port).connected
        if connected and capabilities_address:
            # The reached title only consumes the standard gamepad capability
            # type/subtype and zeroed optional feedback fields.
            memory.write(capabilities_address, bytes((1, 1)) + bytes(18))
        status = 0 if connected else TITLE_XINPUT_ERROR_DEVICE_NOT_CONNECTED
        cpu.set_register("eax", status)
        _prepare_stdcall_return(cpu, memory, 8)
        self.capabilities_count += 1
        trace.add(
            target,
            "title_xinput_get_capabilities_fast_path",
            port=port,
            status=status,
        )

    @staticmethod
    def _xbox_gamepad_payload(state: ControllerState) -> bytes:
        digital_buttons = state.buttons & 0x00FF
        analog = bytes(
            (
                0xFF if state.buttons & 0x1000 else 0,
                0xFF if state.buttons & 0x2000 else 0,
                0xFF if state.buttons & 0x4000 else 0,
                0xFF if state.buttons & 0x8000 else 0,
                0xFF if state.buttons & 0x0100 else 0,
                0xFF if state.buttons & 0x0200 else 0,
                state.left_trigger,
                state.right_trigger,
            )
        )
        return struct.pack(
            "<H8Bhhhh",
            digital_buttons,
            *analog,
            state.thumb_lx,
            state.thumb_ly,
            state.thumb_rx,
            state.thumb_ry,
        )

    def get_state_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        handle, state_address = _read_stack_arguments(
            memory, cpu.get_register("esp"), 2
        )
        port = self._port_from_handle(handle)
        state = self.input.poll_controller(port) if port is not None else ControllerState()
        status = 0 if state.connected else TITLE_XINPUT_ERROR_DEVICE_NOT_CONNECTED
        if status == 0 and state_address:
            self.observed_button_mask |= state.buttons
            if state.buttons & 0x1000:
                self.a_pressed_poll_count += 1
            if self._last_states.get(port) != state:
                self._packets[port] = _u32(self._packets[port] + 1)
                self._last_states[port] = state
            memory.write_u32(state_address, self._packets[port])
            memory.write(state_address + 4, self._xbox_gamepad_payload(state))
            self.successful_get_state_count += 1
        cpu.set_register("eax", status)
        _prepare_stdcall_return(cpu, memory, 8)
        self.get_state_count += 1
        trace.add(
            target,
            "title_xinput_get_state_fast_path",
            port=port,
            status=status,
            state_address=state_address,
            state_address_hex=_hex32(state_address),
            buttons=state.buttons,
            packet=self._packets[port] if port is not None else 0,
        )

    def summary(self, memory: SparseMemory | None = None) -> dict[str, Any]:
        port_snapshots = []
        if memory is not None:
            for port in range(4):
                a_address = (
                    TITLE_INPUT_PORT_BASE_ADDRESS
                    + port * TITLE_INPUT_PORT_STRIDE
                    + TITLE_INPUT_A_VALUE_OFFSET
                )
                a_bits = memory.read_u32(a_address)
                port_snapshots.append(
                    {
                        "port": port,
                        "a_value_address_hex": _hex32(a_address),
                        "a_value_bits_hex": _hex32(a_bits),
                        "a_value": struct.unpack("<f", struct.pack("<I", a_bits))[0],
                    }
                )
        return {
            "xgetdevices_address_hex": _hex32(TITLE_XGETDEVICES_ADDRESS),
            "xinput_open_address_hex": _hex32(TITLE_XINPUT_OPEN_ADDRESS),
            "xinput_get_state_address_hex": _hex32(TITLE_XINPUT_GET_STATE_ADDRESS),
            "consumer_address_hex": _hex32(TITLE_INPUT_CONSUMER_ADDRESS),
            "get_devices_count": self.get_devices_count,
            "open_count": self.open_count,
            "capabilities_count": self.capabilities_count,
            "get_state_count": self.get_state_count,
            "successful_get_state_count": self.successful_get_state_count,
            "observed_button_mask_hex": _hex32(self.observed_button_mask),
            "a_pressed_poll_count": self.a_pressed_poll_count,
            "packets": list(self._packets),
            "guest_port_snapshots": port_snapshots,
        }


class TitleGuestHeapFastPath:
    """Model the observed title heap trampolines with unique guest allocations."""

    def __init__(
        self,
        *,
        allocation_address: int = TITLE_HEAP_ALLOC_TRAMPOLINE_ADDRESS,
        free_address: int = TITLE_HEAP_FREE_TRAMPOLINE_ADDRESS,
        base_address: int = TITLE_HEAP_FAST_PATH_BASE_ADDRESS,
        alignment: int = TITLE_HEAP_FAST_PATH_ALIGNMENT,
        min_object_size: int = TITLE_HEAP_FAST_PATH_MIN_OBJECT_SIZE,
        max_descriptor_size: int = TITLE_HEAP_FAST_PATH_MAX_DESCRIPTOR_SIZE,
    ) -> None:
        self.allocation_address = allocation_address
        self.free_address = free_address
        self.base_address = base_address
        self.alignment = alignment
        self.min_object_size = min_object_size
        self.max_descriptor_size = max_descriptor_size
        self._next_address = base_address
        self.allocation_count = 0
        self.free_count = 0
        self.bytes_allocated = 0
        self.allocations: list[dict[str, int | str]] = []
        self.freed_addresses: list[int] = []

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {
            self.allocation_address: self.allocate_handler,
            self.free_address: self.free_handler,
        }

    def allocate_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        return_address = memory.read_u32(esp)
        descriptor_address = memory.read_u32(esp + 4)
        raw_requested_size = (
            memory.read_u32(descriptor_address) if descriptor_address else 0
        )
        requested_size = (
            raw_requested_size
            if 0 < raw_requested_size <= self.max_descriptor_size
            else 0
        )
        normalized_size = (
            requested_size if requested_size > 0 else max(self.min_object_size, 1)
        )
        allocated_size = max(
            self.alignment,
            _align_up_u32(normalized_size, self.alignment),
        )
        address = _align_up_u32(self._next_address, self.alignment)
        self._next_address = _align_up_u32(address + allocated_size, self.alignment)
        self.allocation_count += 1
        self.bytes_allocated += allocated_size
        allocation = {
            "address": address,
            "address_hex": _hex32(address),
            "return_address": return_address,
            "return_address_hex": _hex32(return_address),
            "descriptor_address": descriptor_address,
            "descriptor_address_hex": _hex32(descriptor_address),
            "requested_size": requested_size,
            "raw_requested_size": raw_requested_size,
            "allocated_size": allocated_size,
        }
        self.allocations.append(allocation)
        cpu.set_register("eax", address)
        trace.add(
            target,
            "title_heap_fast_path_allocate",
            invocation_count=self.allocation_count,
            allocation_address=address,
            allocation_address_hex=_hex32(address),
            return_address=return_address,
            return_address_hex=_hex32(return_address),
            descriptor_address=descriptor_address,
            descriptor_address_hex=_hex32(descriptor_address),
            requested_size=requested_size,
            raw_requested_size=raw_requested_size,
            allocated_size=allocated_size,
        )

    def free_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        address = memory.read_u32(esp + 8)
        self.free_count += 1
        self.freed_addresses.append(address)
        cpu.set_register("eax", address)
        trace.add(
            target,
            "title_heap_fast_path_free",
            invocation_count=self.free_count,
            allocation_address=address,
            allocation_address_hex=_hex32(address),
        )

    def summary(self) -> dict[str, Any]:
        return {
            "allocation_address": self.allocation_address,
            "allocation_address_hex": _hex32(self.allocation_address),
            "free_address": self.free_address,
            "free_address_hex": _hex32(self.free_address),
            "base_address": self.base_address,
            "base_address_hex": _hex32(self.base_address),
            "next_address": self._next_address,
            "next_address_hex": _hex32(self._next_address),
            "alignment": self.alignment,
            "min_object_size": self.min_object_size,
            "max_descriptor_size": self.max_descriptor_size,
            "allocation_count": self.allocation_count,
            "free_count": self.free_count,
            "bytes_allocated": self.bytes_allocated,
            "recent_allocations": self.allocations[-16:],
            "recent_freed_addresses": [
                _hex32(address) for address in self.freed_addresses[-16:]
            ],
        }


class TitleAllocationListCountFastPath:
    """Fast-count the observed allocation owner list without guest list-walk cost."""

    def __init__(
        self,
        *,
        count_address: int = TITLE_ALLOCATION_LIST_COUNT_ADDRESS,
        sentinel_address: int = TITLE_ALLOCATION_LIST_SENTINEL_ADDRESS,
        owner_back_offset: int = TITLE_ALLOCATION_LIST_OWNER_BACK_OFFSET,
        max_scan_nodes: int = TITLE_ALLOCATION_LIST_MAX_SCAN_NODES,
    ) -> None:
        self.count_address = count_address
        self.sentinel_address = sentinel_address
        self.owner_back_offset = owner_back_offset
        self.max_scan_nodes = max_scan_nodes
        self.invocation_count = 0
        self.total_nodes_scanned = 0
        self.cycle_count = 0
        self.max_node_count = 0
        self.last_summary: dict[str, Any] | None = None

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.count_address: self.call_handler}

    def call_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        owner_address = memory.read_u32(_u32(cpu.get_register("esp") + 4))
        node = memory.read_u32(self.sentinel_address)
        visited: set[int] = set()
        visited_order: list[int] = []
        match_count = 0
        terminated_at = "max_scan_nodes"
        while len(visited_order) < self.max_scan_nodes:
            if node == self.sentinel_address:
                terminated_at = "sentinel"
                break
            if node == 0:
                terminated_at = "null"
                break
            if node in visited:
                terminated_at = "cycle"
                self.cycle_count += 1
                break
            visited.add(node)
            visited_order.append(node)
            node_owner = memory.read_u32(_u32(node - self.owner_back_offset))
            if node_owner == owner_address:
                match_count += 1
            node = memory.read_u32(node)

        self.invocation_count += 1
        self.total_nodes_scanned += len(visited_order)
        self.max_node_count = max(self.max_node_count, len(visited_order))
        self.last_summary = {
            "owner_address": owner_address,
            "owner_address_hex": _hex32(owner_address),
            "match_count": match_count,
            "node_count": len(visited_order),
            "terminated_at": terminated_at,
            "last_node_hex": _hex32(node),
            "sampled_nodes_hex": [_hex32(address) for address in visited_order[:16]],
        }
        cpu.set_register("eax", match_count)
        trace.add(
            target,
            "title_allocation_list_count_fast_path",
            invocation_count=self.invocation_count,
            owner_address=owner_address,
            owner_address_hex=_hex32(owner_address),
            match_count=match_count,
            node_count=len(visited_order),
            terminated_at=terminated_at,
            last_node=node,
            last_node_hex=_hex32(node),
            sampled_nodes_hex=[_hex32(address) for address in visited_order[:16]],
        )

    def summary(self) -> dict[str, Any]:
        return {
            "count_address": self.count_address,
            "count_address_hex": _hex32(self.count_address),
            "sentinel_address": self.sentinel_address,
            "sentinel_address_hex": _hex32(self.sentinel_address),
            "owner_back_offset": self.owner_back_offset,
            "owner_back_offset_hex": _hex32(self.owner_back_offset),
            "max_scan_nodes": self.max_scan_nodes,
            "invocation_count": self.invocation_count,
            "total_nodes_scanned": self.total_nodes_scanned,
            "max_node_count": self.max_node_count,
            "cycle_count": self.cycle_count,
            "last_summary": self.last_summary,
        }


class TitleGlobalListRegistrationFastPath:
    """Model the observed title intrusive-list registration edge.

    The matching cleanup routine must execute as guest code. It not only resets
    the intrusive list: it synchronizes every dirty frame and invokes callbacks
    for attached objects such as cameras.
    """

    def __init__(
        self,
        *,
        register_address: int = TITLE_GLOBAL_LIST_REGISTER_ADDRESS,
        head_address: int = TITLE_GLOBAL_LIST_HEAD_ADDRESS,
        tail_address: int = TITLE_GLOBAL_LIST_TAIL_ADDRESS,
        owner_offset: int = TITLE_GLOBAL_LIST_OWNER_OFFSET,
        node_offset: int = TITLE_GLOBAL_LIST_NODE_OFFSET,
    ) -> None:
        self.register_address = register_address
        self.cleanup_address = TITLE_GLOBAL_LIST_CLEANUP_ADDRESS
        self.head_address = head_address
        self.tail_address = tail_address
        self.owner_offset = owner_offset
        self.node_offset = node_offset
        self.invocation_count = 0
        self.lazy_seed_count = 0
        self.insert_count = 0
        self.skip_count = 0
        self.registrations: list[dict[str, int | str | bool]] = []

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.register_address: self.register_handler}

    def register_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        object_address = memory.read_u32(esp + 4)
        owner_address = memory.read_u32(_u32(object_address + self.owner_offset))
        flags = self._read_u8(memory, _u32(owner_address + 3)) if owner_address else 0
        seeded = self._seed_list_if_empty(memory)
        inserted = False
        node_address = _u32(owner_address + self.node_offset) if owner_address else 0
        if owner_address and not flags & TITLE_GLOBAL_LIST_ACTIVE_FLAG:
            previous_head = memory.read_u32(self.head_address)
            memory.write_u32(node_address, previous_head)
            memory.write_u32(_u32(node_address + 4), self.head_address)
            memory.write_u32(_u32(previous_head + 4), node_address)
            memory.write_u32(self.head_address, node_address)
            self._write_u8(
                memory,
                _u32(owner_address + 3),
                flags | TITLE_GLOBAL_LIST_ACTIVE_FLAG,
            )
            self.insert_count += 1
            inserted = True
        elif owner_address:
            self.skip_count += 1

        object_flags = (
            self._read_u8(memory, _u32(object_address + 3)) if object_address else 0
        )
        if object_address:
            self._write_u8(
                memory,
                _u32(object_address + 3),
                object_flags | TITLE_GLOBAL_LIST_OWNER_FLAG,
            )
        cpu.set_register("eax", object_address)
        self.invocation_count += 1
        registration = {
            "target": target,
            "target_hex": _hex32(target),
            "object_address": object_address,
            "object_address_hex": _hex32(object_address),
            "owner_address": owner_address,
            "owner_address_hex": _hex32(owner_address),
            "node_address": node_address,
            "node_address_hex": _hex32(node_address),
            "seeded": seeded,
            "inserted": inserted,
        }
        self.registrations.append(registration)
        trace.add(
            target,
            "title_global_list_register",
            invocation_count=self.invocation_count,
            object_address=object_address,
            object_address_hex=_hex32(object_address),
            owner_address=owner_address,
            owner_address_hex=_hex32(owner_address),
            node_address=node_address,
            node_address_hex=_hex32(node_address),
            seeded=seeded,
            inserted=inserted,
        )

    def _seed_list_if_empty(self, memory: SparseMemory) -> bool:
        if memory.read_u32(self.head_address) != 0:
            return False
        memory.write_u32(self.head_address, self.head_address)
        memory.write_u32(self.tail_address, self.head_address)
        self.lazy_seed_count += 1
        return True

    @staticmethod
    def _read_u8(memory: SparseMemory, address: int) -> int:
        return memory.read(address, 1)[0]

    @staticmethod
    def _write_u8(memory: SparseMemory, address: int, value: int) -> None:
        memory.write(address, bytes([value & 0xFF]))

    def summary(self) -> dict[str, Any]:
        return {
            "register_address": self.register_address,
            "register_address_hex": _hex32(self.register_address),
            "cleanup_address": self.cleanup_address,
            "cleanup_address_hex": _hex32(self.cleanup_address),
            "head_address": self.head_address,
            "head_address_hex": _hex32(self.head_address),
            "tail_address": self.tail_address,
            "tail_address_hex": _hex32(self.tail_address),
            "owner_offset": self.owner_offset,
            "node_offset": self.node_offset,
            "invocation_count": self.invocation_count,
            "lazy_seed_count": self.lazy_seed_count,
            "insert_count": self.insert_count,
            "skip_count": self.skip_count,
            "cleanup_fast_path_enabled": False,
            "recent_registrations": self.registrations[-16:],
        }


class TitleStaticDriveArrayFastPath:
    """Seed the observed static drive descriptor array before virtual dispatch."""

    def __init__(
        self,
        *,
        setup_address: int = TITLE_STATIC_DRIVE_ARRAY_SETUP_ADDRESS,
        element_size: int = TITLE_STATIC_DRIVE_ARRAY_ELEMENT_SIZE,
        max_elements: int = TITLE_STATIC_DRIVE_ARRAY_MAX_ELEMENTS,
    ) -> None:
        self.setup_address = setup_address
        self.element_size = element_size
        self.max_elements = max_elements
        self.invocation_count = 0
        self.seeded_element_count = 0
        self.invocations: list[dict[str, Any]] = []

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.setup_address: self.setup_handler}

    def setup_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        return_address = memory.read_u32(esp)
        count = memory.read_u32(_u32(esp + 4))
        element_base = memory.read_u32(_u32(esp + 8))
        path_address = memory.read_u32(_u32(esp + 12))
        descriptor_address = memory.read_u32(_u32(esp + 16))
        object_address = cpu.get_register("ecx")
        bounded_count = max(0, min(count, self.max_elements))

        memory.write_u32(_u32(object_address + 0x04), 1)
        memory.write_u32(_u32(object_address + 0x08), 0)
        memory.write_u32(_u32(object_address + 0x0C), count)
        memory.write_u32(_u32(object_address + 0x10), element_base)

        registry_index = memory.read_u32(TITLE_STATIC_DRIVE_ARRAY_REGISTRY_COUNT_ADDRESS)
        registered = False
        descriptor_tag = 0
        if descriptor_address:
            descriptor_tag = memory.read_u32(descriptor_address)
        if registry_index < 2:
            memory.write_u32(
                _u32(
                    TITLE_STATIC_DRIVE_ARRAY_REGISTRY_OBJECTS_ADDRESS
                    + registry_index * 4
                ),
                object_address,
            )
            memory.write_u32(
                _u32(
                    TITLE_STATIC_DRIVE_ARRAY_REGISTRY_DESCRIPTORS_ADDRESS
                    + registry_index * 5
                ),
                descriptor_tag,
            )
            memory.write_u32(
                TITLE_STATIC_DRIVE_ARRAY_REGISTRY_COUNT_ADDRESS,
                _u32(registry_index + 1),
            )
            registered = True

        for index in range(bounded_count):
            element_address = _u32(element_base + index * self.element_size)
            memory.write_u32(element_address, descriptor_address)
            memory.write_u32(_u32(element_address + 0x20), 0)

        self.invocation_count += 1
        self.seeded_element_count += bounded_count
        invocation = {
            "target": target,
            "target_hex": _hex32(target),
            "return_address": return_address,
            "return_address_hex": _hex32(return_address),
            "object_address": object_address,
            "object_address_hex": _hex32(object_address),
            "element_base": element_base,
            "element_base_hex": _hex32(element_base),
            "element_size": self.element_size,
            "requested_count": count,
            "seeded_count": bounded_count,
            "descriptor_address": descriptor_address,
            "descriptor_address_hex": _hex32(descriptor_address),
            "descriptor_tag_hex": _hex32(descriptor_tag),
            "path_address": path_address,
            "path_address_hex": _hex32(path_address),
            "registry_index": registry_index,
            "registered": registered,
        }
        self.invocations.append(invocation)
        cpu.set_register("eax", 1)
        _prepare_stdcall_return(
            cpu,
            memory,
            TITLE_STATIC_DRIVE_ARRAY_SETUP_STACK_CLEANUP,
        )
        trace.add(
            target,
            "title_static_drive_array_fast_path",
            invocation_count=self.invocation_count,
            **invocation,
        )

    def summary(self) -> dict[str, Any]:
        return {
            "setup_address_hex": _hex32(self.setup_address),
            "element_size": self.element_size,
            "max_elements": self.max_elements,
            "invocation_count": self.invocation_count,
            "seeded_element_count": self.seeded_element_count,
            "recent_invocations": self.invocations[-8:],
        }


class TitleFrontendAssetInitFastPath:
    """Seed the frontend global dictionary resources past the dirty-disc panel."""

    def __init__(
        self,
        *,
        init_address: int = TITLE_FRONTEND_ASSET_INIT_ADDRESS,
        manager_address: int = TITLE_FRONTEND_SYNTHETIC_ASSET_MANAGER_ADDRESS,
        boot_resource_handle: int = TITLE_FRONTEND_SYNTHETIC_BOOT_RESOURCE_HANDLE_ADDRESS,
        global_dic_handle: int = TITLE_FRONTEND_SYNTHETIC_GLOBAL_DIC_HANDLE_ADDRESS,
        global_dic_node: int = TITLE_FRONTEND_SYNTHETIC_GLOBAL_DIC_NODE_ADDRESS,
        global_dic_list: int = TITLE_FRONTEND_SYNTHETIC_GLOBAL_DIC_LIST_ADDRESS,
        glassb_handle: int = TITLE_FRONTEND_SYNTHETIC_GLASSB_HANDLE_ADDRESS,
        glass_handle: int = TITLE_FRONTEND_SYNTHETIC_GLASS_HANDLE_ADDRESS,
    ) -> None:
        self.init_address = init_address
        self.manager_address = manager_address
        self.boot_resource_handle = boot_resource_handle
        self.global_dic_handle = global_dic_handle
        self.global_dic_node = global_dic_node
        self.global_dic_list = global_dic_list
        self.glassb_handle = glassb_handle
        self.glass_handle = glass_handle
        self.invocation_count = 0
        self.method_invocation_count = 0
        self.last_object_address: int | None = None

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        # 0xE8440/0xE8450 are shared RenderWare tail-call trampolines, not
        # frontend-asset methods. Intercepting them also swallowed camera
        # BeginUpdate/EndUpdate callbacks, leaving RwEngineInstance.curCamera
        # null and causing the UI clipper to suppress every fullscreen batch.
        # The synthetic manager already points both slots at this private HLE
        # target, so native code can execute the real trampolines safely.
        return {
            TITLE_FRONTEND_SYNTHETIC_ASSET_METHOD_TARGET_ADDRESS: (
                self.method_handler
            ),
        }

    def init_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        object_address = cpu.get_register("ecx")
        self._seed_object_fields(memory, object_address)
        self._seed_global_dictionary_list(memory)

        cpu.set_register("eax", 1)
        _prepare_stdcall_return(cpu, memory, 0)
        self.invocation_count += 1
        self.last_object_address = object_address
        trace.add(
            target,
            "title_frontend_asset_init_fast_path",
            invocation_count=self.invocation_count,
            object_address=object_address,
            object_address_hex=_hex32(object_address),
            manager_address_hex=_hex32(self.manager_address),
            global_resource_list_address_hex=_hex32(
                TITLE_FRONTEND_GLOBAL_RESOURCE_LIST_ADDRESS
            ),
            global_dic_node_hex=_hex32(self.global_dic_node),
            resource_path="Frontend/global.dic",
            lookup_key_hint="impact2",
        )

    def _seed_object_fields(self, memory: SparseMemory, object_address: int) -> None:
        memory.write_u32(_u32(object_address + 0x6B950), self.manager_address)
        memory.write_u32(_u32(object_address + 0x6B978), self.boot_resource_handle)
        memory.write_u32(_u32(object_address + 0x6B97C), self.global_dic_handle)
        memory.write_u32(_u32(object_address + 0x6B980), 0)
        memory.write_u32(_u32(object_address + 0x6B984), self.glassb_handle)
        memory.write_u32(_u32(object_address + 0x6B988), self.glass_handle)
        memory.write_u32(_u32(self.manager_address + 0x60), 0)
        memory.write_u32(_u32(self.manager_address + 0x64), 0)
        memory.write_u32(
            _u32(self.manager_address + 0x18),
            TITLE_FRONTEND_SYNTHETIC_ASSET_METHOD_TARGET_ADDRESS,
        )
        memory.write_u32(
            _u32(self.manager_address + 0x1C),
            TITLE_FRONTEND_SYNTHETIC_ASSET_METHOD_TARGET_ADDRESS,
        )

    def method_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        manager_address = memory.read_u32(_u32(esp + 4))
        dispatch_offset = 0x18
        method_target = memory.read_u32(_u32(manager_address + dispatch_offset))
        self.method_invocation_count += 1
        cpu.set_register("eax", 1)
        trace.add(
            target,
            "title_frontend_asset_method_fast_path",
            invocation_count=self.method_invocation_count,
            manager_address_hex=_hex32(manager_address),
            dispatch_offset=dispatch_offset,
            method_target_hex=_hex32(method_target),
        )

    def _seed_global_dictionary_list(self, memory: SparseMemory) -> None:
        list_base = self.global_dic_list
        sentinel = _u32(list_base + 8)
        node = self.global_dic_node
        link = _u32(node + 8)
        memory.write_u32(TITLE_FRONTEND_GLOBAL_RESOURCE_LIST_ADDRESS, list_base)
        memory.write_u32(list_base, 0)
        memory.write_u32(_u32(list_base + 4), 0)
        memory.write_u32(sentinel, link)
        memory.write_u32(_u32(sentinel + 4), link)
        memory.write_u32(link, sentinel)
        memory.write_u32(_u32(link + 4), sentinel)
        memory.write(_u32(node + 0x10), b"impact2\x00")

    def summary(self) -> dict[str, Any]:
        return {
            "init_address": self.init_address,
            "init_address_hex": _hex32(self.init_address),
            "invocation_count": self.invocation_count,
            "method_invocation_count": self.method_invocation_count,
            "last_object_address_hex": _hex32(self.last_object_address or 0)
            if self.last_object_address is not None
            else None,
            "manager_address_hex": _hex32(self.manager_address),
            "method_trampoline_address_hex": _hex32(
                TITLE_FRONTEND_ASSET_METHOD_TRAMPOLINE_ADDRESS
            ),
            "second_method_trampoline_address_hex": _hex32(
                TITLE_FRONTEND_ASSET_SECOND_METHOD_TRAMPOLINE_ADDRESS
            ),
            "method_target_address_hex": _hex32(
                TITLE_FRONTEND_SYNTHETIC_ASSET_METHOD_TARGET_ADDRESS
            ),
            "boot_resource_handle_hex": _hex32(self.boot_resource_handle),
            "global_dic_handle_hex": _hex32(self.global_dic_handle),
            "global_dic_node_hex": _hex32(self.global_dic_node),
            "global_dic_list_hex": _hex32(self.global_dic_list),
            "glassb_handle_hex": _hex32(self.glassb_handle),
            "glass_handle_hex": _hex32(self.glass_handle),
            "resource_path": "Frontend/global.dic",
            "lookup_key_hint": "impact2",
        }


class TitleAssetStreamOpenFastPath:
    """Open observed title asset streams against the configured disc root."""

    def __init__(
        self,
        runtime: XboxRuntimeShims,
        *,
        open_address: int = TITLE_ASSET_STREAM_OPEN_ADDRESS,
        object_address: int = TITLE_ASSET_STREAM_SYNTHETIC_OBJECT_ADDRESS,
        vtable_address: int = TITLE_ASSET_STREAM_SYNTHETIC_VTABLE_ADDRESS,
        close_target: int = TITLE_ASSET_STREAM_SYNTHETIC_CLOSE_TARGET_ADDRESS,
        status_target: int = TITLE_ASSET_STREAM_SYNTHETIC_STATUS_TARGET_ADDRESS,
        read_target: int = TITLE_ASSET_STREAM_SYNTHETIC_READ_TARGET_ADDRESS,
        seek_target: int = TITLE_ASSET_STREAM_SYNTHETIC_SEEK_TARGET_ADDRESS,
    ) -> None:
        self.runtime = runtime
        self.open_address = open_address
        self.object_address = object_address
        self.vtable_address = vtable_address
        self.close_target = close_target
        self.status_target = status_target
        self.read_target = read_target
        self.seek_target = seek_target
        self.invocations: list[dict[str, Any]] = []
        self.close_count = 0
        self.reuse_count = 0
        self.status_poll_count = 0
        self.read_count = 0
        self.bytes_read = 0
        self.ready_transition_count = 0
        self.short_read_count = 0
        self.eof_read_count = 0
        self.terminal_read_count = 0
        self.seek_count = 0
        self.recent_reads: list[dict[str, Any]] = []
        self.track_descriptor_publication_count = 0
        self.track_descriptor_table_count = 0
        self.track_descriptor_table_repair_count = 0
        self.track_descriptor_entry_count = 0
        self.track_descriptor_validation_failure_count = 0
        self.track_prelinked_image_publication_count = 0
        self.track_prelinked_image_repair_count = 0
        self.track_prelinked_image_bytes = 0
        self.track_scene_record_table_count = 0
        self.track_scene_record_table_repair_count = 0
        self.track_scene_record_entry_count = 0
        self.recent_track_descriptor_publications: list[dict[str, Any]] = []
        self._states: dict[int, dict[str, Any]] = {}
        self._next_native_payload_address = (
            TITLE_ASSET_STREAM_NATIVE_PAYLOAD_BASE_ADDRESS
        )

    def _publish_ready(
        self,
        memory: SparseMemory,
        object_address: int,
        state: dict[str, Any],
    ) -> None:
        if int(state.get("status", 2)) != 1:
            self.ready_transition_count += 1
        state["status"] = 1
        memory.write_u32(_u32(object_address + 0x2C), 1)

    @staticmethod
    def _is_track_pss_path(title_path: str) -> bool:
        marker = "trackpss/"
        marker_offset = title_path.find(marker)
        if marker_offset < 0:
            return False
        parts = title_path[marker_offset:].split("/")
        return (
            len(parts) == 3
            and parts[0] == "trackpss"
            and parts[1] in {"forward", "reverse"}
            and parts[2].endswith(".pss")
        )

    def _track_descriptor_validation_failure(
        self,
        state: dict[str, Any],
        target: int,
        trace: ExecutionTrace,
        reason: str,
    ) -> None:
        self.track_descriptor_validation_failure_count += 1
        state["track_descriptor_validation_error"] = reason
        trace.add(
            target,
            "title_track_descriptor_publication_rejected",
            title_path=state.get("title_path"),
            reason=reason,
        )

    def _publish_track_descriptor_tables(
        self,
        memory: SparseMemory,
        state: dict[str, Any],
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        title_path = str(state.get("title_path", ""))
        if not self._is_track_pss_path(title_path):
            return
        if bool(state.get("track_descriptor_publication_attempted", False)):
            return
        state["track_descriptor_publication_attempted"] = True

        payload = state.get("payload", b"")
        if not isinstance(payload, bytes) or len(payload) < TITLE_TRACK_PSS_HEADER_SIZE:
            self._track_descriptor_validation_failure(
                state,
                target,
                trace,
                "track PSS payload is smaller than its descriptor header",
            )
            return

        image_anchor = struct.unpack_from(
            "<I",
            payload,
            TITLE_TRACK_PSS_IMAGE_ANCHOR_POINTER_OFFSET,
        )[0]
        if image_anchor < TITLE_TRACK_PSS_IMAGE_ANCHOR_OFFSET:
            self._track_descriptor_validation_failure(
                state,
                target,
                trace,
                "track PSS image anchor cannot identify a guest image base",
            )
            return
        image_base = image_anchor - TITLE_TRACK_PSS_IMAGE_ANCHOR_OFFSET
        if image_base + len(payload) > 0x100000000:
            self._track_descriptor_validation_failure(
                state,
                target,
                trace,
                "track PSS prelinked image exceeds guest address space",
            )
            return
        descriptor_count = struct.unpack_from(
            "<I",
            payload,
            TITLE_TRACK_PSS_DESCRIPTOR_COUNT_OFFSET,
        )[0]
        if not 0 < descriptor_count <= TITLE_TRACK_PSS_MAX_DESCRIPTOR_COUNT:
            self._track_descriptor_validation_failure(
                state,
                target,
                trace,
                f"track PSS descriptor count {descriptor_count} is invalid",
            )
            return

        table_size = descriptor_count * TITLE_TRACK_PSS_DESCRIPTOR_SIZE
        validated_tables: list[tuple[int, int, bytes]] = []
        for pointer_offset in TITLE_TRACK_PSS_DESCRIPTOR_POINTER_OFFSETS:
            table_address = struct.unpack_from("<I", payload, pointer_offset)[0]
            if table_address < image_base:
                self._track_descriptor_validation_failure(
                    state,
                    target,
                    trace,
                    "track PSS descriptor pointer precedes its guest image base",
                )
                return
            table_offset = table_address - image_base
            if (
                table_address + table_size > 0x100000000
                or table_offset + table_size > len(payload)
            ):
                self._track_descriptor_validation_failure(
                    state,
                    target,
                    trace,
                    "track PSS descriptor table falls outside its payload",
                )
                return
            table_payload = payload[table_offset : table_offset + table_size]
            previous_end = 0
            for descriptor_index in range(descriptor_count):
                stream_offset, stream_length = struct.unpack_from(
                    "<II",
                    table_payload,
                    descriptor_index * TITLE_TRACK_PSS_DESCRIPTOR_SIZE,
                )
                stream_end = stream_offset + stream_length
                if (
                    stream_length == 0
                    or stream_length > TITLE_TRACK_STREAM_CHUNK_SIZE
                    or stream_end > 0x100000000
                    or (descriptor_index > 0 and stream_offset < previous_end)
                ):
                    self._track_descriptor_validation_failure(
                        state,
                        target,
                        trace,
                        (
                            "track PSS descriptor "
                            f"{descriptor_index} has an invalid offset or length"
                        ),
                    )
                    return
                previous_end = stream_end
            validated_tables.append((table_address, table_offset, table_payload))

        validated_scene_tables: list[tuple[str, int, int, int, bytes]] = []
        for name, count_offset, pointer_offset in TITLE_SCENE_RECORD_TABLE_SPECS:
            record_count = struct.unpack_from("<I", payload, count_offset)[0]
            record_address = struct.unpack_from("<I", payload, pointer_offset)[0]
            if record_count > TITLE_SCENE_RECORD_MAX_COUNT:
                self._track_descriptor_validation_failure(
                    state,
                    target,
                    trace,
                    f"track PSS {name} scene-record count {record_count} is invalid",
                )
                return
            if record_count == 0:
                continue
            if record_address < image_base:
                self._track_descriptor_validation_failure(
                    state,
                    target,
                    trace,
                    f"track PSS {name} scene-record table precedes its image",
                )
                return
            record_offset = record_address - image_base
            record_size = record_count * TITLE_SCENE_RECORD_SIZE
            if record_offset + record_size > len(payload):
                self._track_descriptor_validation_failure(
                    state,
                    target,
                    trace,
                    f"track PSS {name} scene-record table falls outside its payload",
                )
                return
            validated_scene_tables.append(
                (
                    name,
                    record_count,
                    record_address,
                    record_offset,
                    payload[record_offset : record_offset + record_size],
                )
            )

        repaired_table_count = 0
        tables = []
        for table_address, table_offset, table_payload in validated_tables:
            repaired = memory.read(table_address, table_size) != table_payload
            if repaired:
                repaired_table_count += 1
            tables.append(
                {
                    "guest_address_hex": _hex32(table_address),
                    "payload_offset_hex": _hex32(table_offset),
                    "byte_count": table_size,
                    "repaired": repaired,
                }
            )

        repaired_scene_table_count = 0
        scene_record_tables = []
        for (
            name,
            record_count,
            record_address,
            record_offset,
            record_payload,
        ) in validated_scene_tables:
            repaired = memory.read(record_address, len(record_payload)) != record_payload
            repaired_scene_table_count += int(repaired)
            scene_record_tables.append(
                {
                    "name": name,
                    "record_count": record_count,
                    "guest_address_hex": _hex32(record_address),
                    "payload_offset_hex": _hex32(record_offset),
                    "byte_count": len(record_payload),
                    "repaired": repaired,
                }
            )

        prelinked_image_repaired = memory.read(image_base, len(payload)) != payload
        if prelinked_image_repaired:
            memory.write(image_base, payload)

        publication = {
            "title_path": title_path,
            "image_base_hex": _hex32(image_base),
            "image_byte_count": len(payload),
            "prelinked_image_repaired": prelinked_image_repaired,
            "descriptor_count": descriptor_count,
            "table_count": len(validated_tables),
            "repaired_table_count": repaired_table_count,
            "tables": tables,
            "scene_record_count": sum(
                record_count
                for _, record_count, _, _, _ in validated_scene_tables
            ),
            "scene_record_table_count": len(validated_scene_tables),
            "repaired_scene_record_table_count": repaired_scene_table_count,
            "scene_record_tables": scene_record_tables,
        }
        state["track_descriptor_tables_published"] = True
        state["track_prelinked_image_published"] = True
        state["track_descriptor_publication"] = publication
        self.track_descriptor_publication_count += 1
        self.track_descriptor_table_count += len(validated_tables)
        self.track_descriptor_table_repair_count += repaired_table_count
        self.track_descriptor_entry_count += descriptor_count * len(validated_tables)
        self.track_prelinked_image_publication_count += 1
        self.track_prelinked_image_repair_count += int(prelinked_image_repaired)
        self.track_prelinked_image_bytes += len(payload) * int(prelinked_image_repaired)
        self.track_scene_record_table_count += len(validated_scene_tables)
        self.track_scene_record_table_repair_count += repaired_scene_table_count
        self.track_scene_record_entry_count += sum(
            record_count for _, record_count, _, _, _ in validated_scene_tables
        )
        self.recent_track_descriptor_publications.append(publication)
        del self.recent_track_descriptor_publications[:-16]
        trace.add(
            target,
            "title_track_descriptor_publication",
            title_path=title_path,
            image_base_hex=_hex32(image_base),
            descriptor_count=descriptor_count,
            table_count=len(validated_tables),
            repaired_table_count=repaired_table_count,
            prelinked_image_repaired=prelinked_image_repaired,
            scene_record_table_count=len(validated_scene_tables),
            repaired_scene_record_table_count=repaired_scene_table_count,
        )

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {
            self.open_address: self.open_handler,
            self.close_target: self.close_handler,
            self.status_target: self.status_handler,
            self.read_target: self.read_handler,
            self.seek_target: self.seek_handler,
        }

    def open_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        title_path_address = memory.read_u32(_u32(esp + 4))
        flags = memory.read_u32(_u32(esp + 8))
        title_path_bytes = _read_guest_c_string(memory, title_path_address, max_bytes=260)
        title_path = title_path_bytes.decode("cp1252", errors="replace")
        guest_path = title_path.replace("/", "\\")
        if not any(guest_path.casefold().startswith(prefix.casefold()) for prefix in ("d:\\", "\\device\\")):
            guest_path = "D:\\" + guest_path.lstrip("\\")
        opened = self.runtime.filesystem.open_file(guest_path, "rb")
        status = int(opened.get("status", XboxStatus.NO_SUCH_FILE))
        size = 0
        result_address = 0
        payload = b""
        if status == XboxStatus.SUCCESS and not bool(opened.get("is_directory", False)):
            handle = opened.get("handle")
            if isinstance(handle, int):
                information = self.runtime.filesystem.query_file_handle_information(handle)
                size = int(information.get("size", 0))
                read_result = self.runtime.filesystem.read_file(handle, size, offset=0)
                read_payload = read_result.get("data", b"")
                payload = bytes(read_payload) if isinstance(read_payload, bytes) else b""
                self.runtime.nt_close(handle)
            reusable = sorted(
                (
                    (address, state)
                    for address, state in self._states.items()
                    if not bool(state.get("active", True))
                ),
                key=lambda item: (
                    int(item[1].get("payload_capacity", 0)) < len(payload),
                    int(item[1].get("payload_capacity", 0)),
                    item[0],
                ),
            )
            previous_state = reusable[0][1] if reusable else None
            result_address = (
                reusable[0][0]
                if reusable
                else _u32(
                    self.object_address
                    + len(self._states) * TITLE_ASSET_STREAM_SYNTHETIC_OBJECT_STRIDE
                )
            )
            payload_capacity = (
                int(previous_state.get("payload_capacity", 0))
                if previous_state is not None
                else 0
            )
            native_payload_address = (
                int(previous_state.get("native_payload_address", 0))
                if previous_state is not None
                else 0
            )
            if native_payload_address == 0 or payload_capacity < len(payload):
                native_payload_address = _align_up_u32(
                    self._next_native_payload_address, 0x1000
                )
                payload_capacity = max(len(payload), 1)
                self._next_native_payload_address = _align_up_u32(
                    native_payload_address + payload_capacity, 0x1000
                )
            if previous_state is not None:
                self.reuse_count += 1
            self._states[result_address] = {
                "payload": payload,
                "payload_capacity": payload_capacity,
                "native_payload_address": native_payload_address,
                "active": True,
                "position": 0,
                "title_path": title_path.replace("\\", "/").casefold(),
                "status": 2,
                "read_count": 0,
                "requested_bytes": 0,
                "bytes_read": 0,
                "short_read_count": 0,
                "eof_read_count": 0,
                "terminal_read_count": 0,
                "terminal": not payload,
                "track_descriptor_publication_attempted": False,
                "track_descriptor_tables_published": False,
            }
            if payload:
                memory.write(native_payload_address, payload)
            memory.write_u32(result_address, self.vtable_address)
            memory.write_u32(_u32(result_address + 0x10), size)
            memory.write_u32(_u32(result_address + 0x14), 0)
            memory.write_u32(_u32(result_address + 0x18), 0)
            memory.write_u32(_u32(result_address + 0x1C), 0)
            memory.write_u32(_u32(result_address + 0x2C), 2)
            memory.write_u32(_u32(result_address + 0x30), native_payload_address)
            memory.write_u32(_u32(result_address + 0x34), len(payload))
            memory.write_u32(_u32(result_address + 0x38), 0)
            memory.write_u32(_u32(self.vtable_address + 4), self.close_target)
            memory.write_u32(_u32(self.vtable_address + 8), self.read_target)
            memory.write_u32(_u32(self.vtable_address + 0x10), self.seek_target)
            memory.write_u32(_u32(self.vtable_address + 0x1C), self.status_target)
        cpu.set_register("eax", result_address)
        _prepare_stdcall_return(cpu, memory, 8)
        invocation = {
            "invocation_count": len(self.invocations) + 1,
            "title_path": title_path,
            "guest_path": guest_path,
            "flags_hex": _hex32(flags),
            "status": status,
            "status_hex": _hex32(status),
            "size": size,
            "result_address_hex": _hex32(result_address),
        }
        self.invocations.append(invocation)
        trace.add(target, "title_asset_stream_open_fast_path", **invocation)

    def payload_for_title(self, title_path: str) -> bytes | None:
        normalized = title_path.replace("\\", "/").casefold()
        for state in reversed(list(self._states.values())):
            if state.get("title_path") == normalized:
                return bytes(state.get("payload", b""))
        return None

    def close_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        object_address = cpu.get_register("ecx")
        state = self._states.get(object_address)
        if state is not None and bool(state.get("active", True)):
            state["active"] = False
            state["status"] = 0
            memory.write_u32(_u32(object_address + 0x2C), 0)
            self.close_count += 1
        cpu.set_register("eax", 1)
        _prepare_stdcall_return(cpu, memory, 0)
        trace.add(
            target,
            "title_asset_stream_close_fast_path",
            close_count=self.close_count,
            object_address_hex=_hex32(object_address),
        )

    def read_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        destination = memory.read_u32(_u32(esp + 4))
        requested = memory.read_u32(_u32(esp + 8))
        object_address = cpu.get_register("ecx")
        state = self._states.get(object_address)
        if state is not None and not bool(state.get("active", True)):
            state = None
        if state is None:
            payload = b""
            position_before = 0
        else:
            payload = state["payload"]
            position_before = int(state["position"])
        chunk = payload[position_before : position_before + requested]
        if destination and chunk:
            memory.write(destination, chunk)
        if state is not None:
            # Track PSS assets contain absolute guest pointers into a prelinked
            # image. The synchronous HLE retains the file bytes, but the caller
            # reads them into a separate heap allocation. Publish the validated
            # image at its linked base so scene records, geometry, and the later
            # PSW/P2W descriptor tables all remain source-exact.
            self._publish_track_descriptor_tables(memory, state, target, trace)
        position = position_before + len(chunk)
        short_read = len(chunk) < requested
        eof_read = requested > 0 and not chunk and position_before >= len(payload)
        terminal = position >= len(payload)
        if state is not None:
            was_terminal = bool(state.get("terminal", False))
            state["position"] = position
            state["read_count"] = int(state.get("read_count", 0)) + 1
            state["requested_bytes"] = int(state.get("requested_bytes", 0)) + requested
            state["bytes_read"] = int(state.get("bytes_read", 0)) + len(chunk)
            state["short_read_count"] = int(state.get("short_read_count", 0)) + int(
                short_read
            )
            state["eof_read_count"] = int(state.get("eof_read_count", 0)) + int(
                eof_read
            )
            state["terminal_read_count"] = int(
                state.get("terminal_read_count", 0)
            ) + int(terminal)
            state["terminal"] = terminal
            if terminal and not was_terminal:
                state["terminal_transition_read_count"] = int(
                    state.get("read_count", 0)
                )
        memory.write_u32(_u32(object_address + 0x18), position & 0xFFFFFFFF)
        memory.write_u32(_u32(object_address + 0x1C), position >> 32)
        if state is not None:
            # The recovered provider publishes 2 while an open is pending and
            # 1 once the synchronous read boundary is ready. Returning 1 from
            # status without updating this guest-visible field left the title's
            # second level loader observing a permanently pending stream.
            self._publish_ready(memory, object_address, state)
        self.read_count += 1
        self.bytes_read += len(chunk)
        self.short_read_count += int(short_read)
        self.eof_read_count += int(eof_read)
        self.terminal_read_count += int(terminal)
        cpu.set_register("eax", len(chunk))
        _prepare_stdcall_return(cpu, memory, 8)
        read = {
            "read_count": self.read_count,
            "destination_hex": _hex32(destination),
            "requested": requested,
            "bytes_read": len(chunk),
            "object_address_hex": _hex32(object_address),
            "position_before": position_before,
            "next_position": position,
            "short_read": short_read,
            "eof_read": eof_read,
            "terminal": terminal,
        }
        self.recent_reads.append(read)
        del self.recent_reads[:-32]
        trace.add(target, "title_asset_stream_read_fast_path", **read)

    def status_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        object_address = cpu.get_register("ecx")
        object_mode = memory.read_u32(_u32(object_address + 0x2C))
        # The title's stream scheduler treats 2 as pending and 3 as failed.
        # A validated synchronous host read is immediately ready (1), and the
        # real provider exposes that transition both as the return value and in
        # its guest-visible mode field.
        state = self._states.get(object_address)
        active = state is not None and bool(state.get("active", True))
        status = 1 if active else 0
        if active:
            self._publish_ready(memory, object_address, state)
        self.status_poll_count += 1
        cpu.set_register("eax", status)
        _prepare_stdcall_return(cpu, memory, 0)
        trace.add(
            target,
            "title_asset_stream_status_fast_path",
            object_address_hex=_hex32(object_address),
            status=status,
            status_hex=_hex32(status),
            object_mode=object_mode,
            object_mode_hex=_hex32(object_mode),
        )

    def seek_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        offset_low = memory.read_u32(_u32(esp + 4))
        offset_high = memory.read_u32(_u32(esp + 8))
        origin = memory.read_u32(_u32(esp + 0xC))
        object_address = cpu.get_register("ecx")
        state = self._states.get(object_address)
        if state is not None and not bool(state.get("active", True)):
            state = None
        payload = state["payload"] if state is not None else b""
        position = int(state["position"]) if state is not None else 0
        signed_offset = (offset_high << 32) | offset_low
        if signed_offset & (1 << 63):
            signed_offset -= 1 << 64
        base = 0 if origin == 0 else position if origin == 1 else len(payload)
        position = max(0, min(len(payload), base + signed_offset))
        if state is not None:
            state["position"] = position
            state["terminal"] = position >= len(payload)
            self._publish_ready(memory, object_address, state)
        memory.write_u32(_u32(object_address + 0x18), position & 0xFFFFFFFF)
        memory.write_u32(_u32(object_address + 0x1C), position >> 32)
        self.seek_count += 1
        cpu.set_register("eax", position)
        _prepare_stdcall_return(cpu, memory, 12)
        trace.add(
            target,
            "title_asset_stream_seek_fast_path",
            seek_count=self.seek_count,
            signed_offset=signed_offset,
            origin=origin,
            object_address_hex=_hex32(object_address),
            position=position,
        )

    def summary(self) -> dict[str, Any]:
        stream_states = []
        for object_address, state in sorted(self._states.items()):
            payload = state.get("payload", b"")
            size = len(payload) if isinstance(payload, bytes) else 0
            position = int(state.get("position", 0))
            stream_states.append(
                {
                    "object_address_hex": _hex32(object_address),
                    "title_path": state.get("title_path"),
                    "active": bool(state.get("active", True)),
                    "payload_capacity": int(state.get("payload_capacity", size)),
                    "status": int(state.get("status", 2)),
                    "position": position,
                    "size": size,
                    "complete": position >= size,
                    "terminal": bool(state.get("terminal", False)),
                    "read_count": int(state.get("read_count", 0)),
                    "requested_bytes": int(state.get("requested_bytes", 0)),
                    "bytes_read": int(state.get("bytes_read", 0)),
                    "short_read_count": int(state.get("short_read_count", 0)),
                    "eof_read_count": int(state.get("eof_read_count", 0)),
                    "terminal_read_count": int(
                        state.get("terminal_read_count", 0)
                    ),
                    "terminal_transition_read_count": state.get(
                        "terminal_transition_read_count"
                    ),
                    "track_descriptor_publication_attempted": bool(
                        state.get("track_descriptor_publication_attempted", False)
                    ),
                    "track_descriptor_tables_published": bool(
                        state.get("track_descriptor_tables_published", False)
                    ),
                    "track_prelinked_image_published": bool(
                        state.get("track_prelinked_image_published", False)
                    ),
                    "track_descriptor_validation_error": state.get(
                        "track_descriptor_validation_error"
                    ),
                    "track_descriptor_publication": state.get(
                        "track_descriptor_publication"
                    ),
                }
            )
        return {
            "open_address_hex": _hex32(self.open_address),
            "invocation_count": len(self.invocations),
            "successful_open_count": sum(
                1 for invocation in self.invocations if invocation["status"] == XboxStatus.SUCCESS
            ),
            "close_count": self.close_count,
            "reuse_count": self.reuse_count,
            "status_poll_count": self.status_poll_count,
            "read_count": self.read_count,
            "bytes_read": self.bytes_read,
            "ready_transition_count": self.ready_transition_count,
            "short_read_count": self.short_read_count,
            "eof_read_count": self.eof_read_count,
            "terminal_read_count": self.terminal_read_count,
            "seek_count": self.seek_count,
            "track_descriptor_publication_count": self.track_descriptor_publication_count,
            "track_descriptor_table_count": self.track_descriptor_table_count,
            "track_descriptor_table_repair_count": self.track_descriptor_table_repair_count,
            "track_descriptor_entry_count": self.track_descriptor_entry_count,
            "track_descriptor_validation_failure_count": self.track_descriptor_validation_failure_count,
            "track_prelinked_image_publication_count": self.track_prelinked_image_publication_count,
            "track_prelinked_image_repair_count": self.track_prelinked_image_repair_count,
            "track_prelinked_image_bytes": self.track_prelinked_image_bytes,
            "track_scene_record_table_count": self.track_scene_record_table_count,
            "track_scene_record_table_repair_count": self.track_scene_record_table_repair_count,
            "track_scene_record_entry_count": self.track_scene_record_entry_count,
            "active_stream_count": sum(
                bool(state.get("active", True)) for state in self._states.values()
            ),
            "stream_states": stream_states,
            "recent_reads": self.recent_reads,
            "recent_track_descriptor_publications": self.recent_track_descriptor_publications,
            "recent_invocations": self.invocations[-16:],
        }


class TitleFrontendSpecialAudioFastPath:
    """Create the diagnostic frontend sound-bank handle without playing it."""

    def __init__(
        self,
        runtime: XboxRuntimeShims,
        asset_streams: TitleAssetStreamOpenFastPath,
        output: SdlPcmOutput | None = None,
        *,
        create_address: int = TITLE_FRONTEND_SPECIAL_AUDIO_CREATE_ADDRESS,
        handle_address: int = TITLE_FRONTEND_SYNTHETIC_AUDIO_HANDLE_ADDRESS,
    ) -> None:
        self.create_address = create_address
        self.handle_address = handle_address
        self.runtime = runtime
        self.asset_streams = asset_streams
        self.output = output
        self.invocations: list[dict[str, Any]] = []
        self.audio_handles: dict[int, int] = {}
        self.decode_error_count = 0
        self.submitted_clip_count = 0

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.create_address: self.create_handler}

    def create_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        sample_index = memory.read_u32(_u32(esp + 4))
        frontend_audio_object = cpu.get_register("ecx")
        memory.write_u32(self.handle_address, 1)
        list_sentinel = _u32(self.handle_address + 0x0C)
        memory.write_u32(_u32(self.handle_address + 0x10), list_sentinel)
        cpu.set_register("eax", self.handle_address)
        _prepare_stdcall_return(cpu, memory, 4)
        invocation = {
            "invocation_count": len(self.invocations) + 1,
            "frontend_audio_object_hex": _hex32(frontend_audio_object),
            "sample_index": sample_index,
            "handle_address_hex": _hex32(self.handle_address),
            "list_sentinel_hex": _hex32(list_sentinel),
            "decoded_clip_count": 0,
            "playback_started": False,
            "playback_suppressed": True,
        }
        self.invocations.append(invocation)
        trace.add(target, "title_frontend_special_audio_fast_path", **invocation)

    def summary(self) -> dict[str, Any]:
        return {
            "create_address_hex": _hex32(self.create_address),
            "invocation_count": len(self.invocations),
            "handle_address_hex": _hex32(self.handle_address),
            "list_sentinel_hex": _hex32(_u32(self.handle_address + 0x0C)),
            "submitted_clip_count": self.submitted_clip_count,
            "decode_error_count": self.decode_error_count,
            "recent_invocations": self.invocations[-8:],
        }


class TitleMusicModeFastPath:
    """Model diagnostic music-mode state without synthesizing playback."""

    def __init__(
        self,
        runtime: XboxRuntimeShims,
        output: SdlPcmOutput | None,
        *,
        set_mode_address: int = TITLE_MUSIC_MODE_SET_ADDRESS,
        cache_dir: Path | None = None,
    ) -> None:
        self.runtime = runtime
        self.output = output
        self.set_mode_address = set_mode_address
        self.cache_dir = cache_dir
        self.invocations: list[dict[str, Any]] = []
        self.decode_error_count = 0
        self.decoded_track_count = 0
        self.submitted_track_count = 0
        self.cache_hit_count = 0
        self.cache_miss_count = 0
        self._menu_clip = None

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.set_mode_address: self.set_mode_handler}

    def set_mode_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        object_holder_address = cpu.get_register("ecx")
        object_address = (
            memory.read_u32(object_holder_address) if object_holder_address else 0
        )
        if object_address == 0 and object_holder_address:
            object_address = TITLE_MUSIC_SYNTHETIC_MANAGER_ADDRESS
            memory.write_u32(object_holder_address, object_address)
        mode = memory.read_u32(_u32(esp + 4))
        previous_mode = memory.read_u32(_u32(object_address + 0x38)) if object_address else 0
        if object_address:
            memory.write_u32(_u32(object_address + 0x38), mode)

        cpu.set_register("eax", 1)
        _prepare_stdcall_return(cpu, memory, 4)
        invocation = {
            "invocation_count": len(self.invocations) + 1,
            "object_holder_address_hex": _hex32(object_holder_address),
            "object_address_hex": _hex32(object_address),
            "previous_mode": previous_mode,
            "mode": mode,
            "decoded_bytes": 0,
            "playback_started": False,
            "playback_suppressed": True,
        }
        self.invocations.append(invocation)
        trace.add(target, "title_music_mode_fast_path", **invocation)

    def summary(self) -> dict[str, Any]:
        return {
            "set_mode_address_hex": _hex32(self.set_mode_address),
            "invocation_count": len(self.invocations),
            "menu_mode": TITLE_MUSIC_MENU_MODE,
            "decode_error_count": self.decode_error_count,
            "decoded_track_count": self.decoded_track_count,
            "submitted_track_count": self.submitted_track_count,
            "cache_hit_count": self.cache_hit_count,
            "cache_miss_count": self.cache_miss_count,
            "recent_invocations": self.invocations[-8:],
        }


class TitleFrontendCrtInitializerAudit:
    """Audit the frontend objects that should be initialized by CRT routine 0x1392B0."""

    def __init__(self) -> None:
        self.initializer_execution_count = 0
        self.observation_count = 0
        self.null_object_count = 0
        self.null_vtable_count = 0
        self.observations: list[dict[str, Any]] = []

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {}

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if cpu.eip == TITLE_FRONTEND_CRT_VTABLE_INITIALIZER_ADDRESS:
            self.initializer_execution_count += 1
            initializer_table_target = memory.read_u32(
                TITLE_FRONTEND_CRT_VTABLE_INITIALIZER_TABLE_ENTRY_ADDRESS
            )
            trace.add(
                TITLE_FRONTEND_CRT_VTABLE_INITIALIZER_ADDRESS,
                "title_frontend_crt_initializer_execution",
                steps=steps,
                execution_count=self.initializer_execution_count,
                initializer_table_entry_address_hex=_hex32(
                    TITLE_FRONTEND_CRT_VTABLE_INITIALIZER_TABLE_ENTRY_ADDRESS
                ),
                initializer_table_target_hex=_hex32(initializer_table_target),
                initializer_table_entry_matches=initializer_table_target
                == TITLE_FRONTEND_CRT_VTABLE_INITIALIZER_ADDRESS,
            )
            return
        if cpu.eip != TITLE_FRONTEND_DYNAMIC_OBJECT_RESET_USE_ADDRESS:
            return
        self.observation_count += 1
        owner_address = cpu.get_register("esi")
        object_address = memory.read_u32(
            owner_address + TITLE_FRONTEND_DYNAMIC_OBJECT_POINTER_OFFSET
        )
        vtable_address = memory.read_u32(object_address) if object_address else 0
        method0_target = memory.read_u32(vtable_address) if vtable_address else 0
        initializer_table_target = memory.read_u32(
            TITLE_FRONTEND_CRT_VTABLE_INITIALIZER_TABLE_ENTRY_ADDRESS
        )
        if object_address == 0:
            self.null_object_count += 1
        if object_address != 0 and vtable_address == 0:
            self.null_vtable_count += 1
        observation = {
            "steps": steps,
            "owner_address_hex": _hex32(owner_address),
            "object_address_hex": _hex32(object_address),
            "vtable_address_hex": _hex32(vtable_address),
            "method0_target_hex": _hex32(method0_target),
            "initializer_table_target_hex": _hex32(initializer_table_target),
            "initializer_table_entry_matches": initializer_table_target
            == TITLE_FRONTEND_CRT_VTABLE_INITIALIZER_ADDRESS,
        }
        self.observations.append(observation)
        trace.add(
            TITLE_FRONTEND_DYNAMIC_OBJECT_RESET_USE_ADDRESS,
            "title_frontend_crt_initializer_audit",
            observation_count=self.observation_count,
            null_object_count=self.null_object_count,
            null_vtable_count=self.null_vtable_count,
            **observation,
        )

    def summary(self) -> dict[str, Any]:
        return {
            "use_address_hex": _hex32(TITLE_FRONTEND_DYNAMIC_OBJECT_RESET_USE_ADDRESS),
            "initializer_address_hex": _hex32(
                TITLE_FRONTEND_CRT_VTABLE_INITIALIZER_ADDRESS
            ),
            "initializer_table_entry_address_hex": _hex32(
                TITLE_FRONTEND_CRT_VTABLE_INITIALIZER_TABLE_ENTRY_ADDRESS
            ),
            "crt_constructor_table_start_address_hex": _hex32(
                TITLE_CRT_CONSTRUCTOR_TABLE_START_ADDRESS
            ),
            "crt_constructor_table_end_address_hex": _hex32(
                TITLE_CRT_CONSTRUCTOR_TABLE_END_ADDRESS
            ),
            "initializer_execution_count": self.initializer_execution_count,
            "observation_count": self.observation_count,
            "null_object_count": self.null_object_count,
            "null_vtable_count": self.null_vtable_count,
            "recent_observations": self.observations[-12:],
        }


class TitleFrontendObjectConstructorFastPath:
    """Legacy synthetic child model retained only for focused diagnostics."""

    def __init__(
        self,
        *,
        constructor_address: int = TITLE_FRONTEND_OBJECT_CONSTRUCTOR_ADDRESS,
        child_object_base: int = TITLE_FRONTEND_SYNTHETIC_CHILD_OBJECT_BASE_ADDRESS,
        child_state_base: int = TITLE_FRONTEND_SYNTHETIC_CHILD_STATE_BASE_ADDRESS,
        child_descriptor_base: int = (
            TITLE_FRONTEND_SYNTHETIC_CHILD_DESCRIPTOR_BASE_ADDRESS
        ),
        method_table_address: int = TITLE_FRONTEND_SYNTHETIC_CHILD_METHOD_TABLE_ADDRESS,
        method_target_address: int = (
            TITLE_FRONTEND_SYNTHETIC_CHILD_METHOD_TARGET_ADDRESS
        ),
        child_stride: int = TITLE_FRONTEND_SYNTHETIC_CHILD_STRIDE,
    ) -> None:
        self.constructor_address = constructor_address
        self.child_object_base = child_object_base
        self.child_state_base = child_state_base
        self.child_descriptor_base = child_descriptor_base
        self.method_table_address = method_table_address
        self.method_target_address = method_target_address
        self.child_stride = child_stride
        self.invocation_count = 0
        self.method_invocation_count = 0
        self.invocations: list[dict[str, Any]] = []
        self.method_invocations: list[dict[str, Any]] = []

    def call_handlers(
        self,
        *,
        include_constructor_bypass: bool = False,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        handlers = {self.method_target_address: self.method_handler}
        if include_constructor_bypass:
            handlers[self.constructor_address] = self.constructor_handler
        return handlers

    def constructor_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        owner_address = cpu.get_register("ecx")
        slot = self.invocation_count
        child_object = self.child_object_base + slot * self.child_stride
        child_state = self.child_state_base + slot * self.child_stride
        child_descriptor = self.child_descriptor_base + slot * self.child_stride
        self._seed_child(memory, owner_address, child_object, child_state, child_descriptor)

        self.invocation_count += 1
        invocation = {
            "owner_address": owner_address,
            "owner_address_hex": _hex32(owner_address),
            "child_object_hex": _hex32(child_object),
            "child_state_hex": _hex32(child_state),
            "child_descriptor_hex": _hex32(child_descriptor),
            "method_table_hex": _hex32(self.method_table_address),
            "method_target_hex": _hex32(self.method_target_address),
            "dispatch_indices": list(TITLE_FRONTEND_SYNTHETIC_CHILD_DISPATCH_INDICES),
        }
        self.invocations.append(invocation)
        cpu.set_register("eax", 1)
        _prepare_stdcall_return(cpu, memory, 0)
        trace.add(
            target,
            "title_frontend_object_constructor_fast_path",
            invocation_count=self.invocation_count,
            **invocation,
        )

    def method_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        dispatch_index = (
            _u32(cpu.get_register("eax") - self.method_table_address) // 8
        )
        payload_address = memory.read_u32(esp + 12)
        output_object_address = None
        if (
            dispatch_index
            in TITLE_FRONTEND_SYNTHETIC_CHILD_OUT_POINTER_DISPATCH_INDICES
            and payload_address
        ):
            output_object_address = self.child_object_base
            memory.write_u32(payload_address, output_object_address)
        invocation = {
            "context_hex": _hex32(memory.read_u32(esp + 4)),
            "dispatch_index": dispatch_index,
            "selector": memory.read_u32(esp + 8),
            "selector_hex": _hex32(memory.read_u32(esp + 8)),
            "payload_hex": _hex32(payload_address),
            "output_object_hex": (
                _hex32(output_object_address)
                if output_object_address is not None
                else None
            ),
        }
        self.method_invocation_count += 1
        self.method_invocations.append(invocation)
        cpu.set_register("eax", 1)
        _prepare_stdcall_return(cpu, memory, 0)
        trace.add(
            target,
            "title_frontend_child_method_fast_path",
            invocation_count=self.method_invocation_count,
            **invocation,
        )

    def _seed_child(
        self,
        memory: SparseMemory,
        owner_address: int,
        child_object: int,
        child_state: int,
        child_descriptor: int,
    ) -> None:
        memory.write_u32(_u32(owner_address + 0x58), child_object)
        memory.write_u32(_u32(owner_address + 0x5C), child_state)
        memory.write_u32(child_object, owner_address)
        memory.write_u32(_u32(child_object + 4), child_descriptor)
        memory.write_u32(child_descriptor, child_object)
        memory.write_u32(_u32(child_descriptor + 4), self.method_table_address)
        memory.write_u32(_u32(child_descriptor + 8), self.method_table_address)
        for dispatch_index in TITLE_FRONTEND_SYNTHETIC_CHILD_DISPATCH_INDICES:
            method_entry = self.method_table_address + dispatch_index * 8
            memory.write_u32(method_entry, self.method_target_address)
            memory.write(_u32(method_entry + 4), b"\x00\x00")
        memory.write_u32(_u32(child_state + 0x64), 0)
        memory.write_u32(_u32(child_state + 0x68), 0)
        memory.write_u32(_u32(child_state + 0x70), 0)

    def summary(self) -> dict[str, Any]:
        return {
            "constructor_address": self.constructor_address,
            "constructor_address_hex": _hex32(self.constructor_address),
            "constructor_bypass_enabled": False,
            "invocation_count": self.invocation_count,
            "method_invocation_count": self.method_invocation_count,
            "child_object_base_hex": _hex32(self.child_object_base),
            "child_state_base_hex": _hex32(self.child_state_base),
            "child_descriptor_base_hex": _hex32(self.child_descriptor_base),
            "method_table_hex": _hex32(self.method_table_address),
            "method_target_hex": _hex32(self.method_target_address),
            "dispatch_index": TITLE_FRONTEND_SYNTHETIC_CHILD_DISPATCH_INDEX,
            "dispatch_indices": list(TITLE_FRONTEND_SYNTHETIC_CHILD_DISPATCH_INDICES),
            "recent_invocations": self.invocations[-8:],
            "recent_method_invocations": self.method_invocations[-8:],
        }


class TitleFixedWidthCompareFastPath:
    """Legacy synthetic compare retained only for focused diagnostics."""

    def __init__(
        self,
        *,
        compare_address: int = TITLE_FIXED_WIDTH_COMPARE_ADDRESS,
        compare_size: int = TITLE_FIXED_WIDTH_COMPARE_BYTES,
        sample_limit: int = 16,
    ) -> None:
        self.compare_address = compare_address
        self.compare_size = compare_size
        self.sample_limit = sample_limit
        self.invocation_count = 0
        self.equal_count = 0
        self.less_count = 0
        self.greater_count = 0
        self.null_argument_count = 0
        self.sampled_invocations: list[dict[str, Any]] = []

    def call_handlers(
        self,
        *,
        include_compare_bypass: bool = False,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        if not include_compare_bypass:
            return {}
        return {self.compare_address: self.compare_handler}

    def compare_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        left_address = memory.read_u32(_u32(esp + 4))
        right_address = memory.read_u32(_u32(esp + 8))
        left = memory.read(left_address, self.compare_size)
        right = memory.read(right_address, self.compare_size)
        mismatch_index: int | None = None
        result = 0
        for index, (left_byte, right_byte) in enumerate(zip(left, right, strict=True)):
            if left_byte == right_byte:
                continue
            mismatch_index = index
            result = 0xFFFFFFFF if left_byte < right_byte else 1
            break

        self.invocation_count += 1
        if left_address == 0 or right_address == 0:
            self.null_argument_count += 1
        if result == 0:
            self.equal_count += 1
        elif result == 0xFFFFFFFF:
            self.less_count += 1
        else:
            self.greater_count += 1
        cpu.set_register("eax", result)
        sample = {
            "invocation_count": self.invocation_count,
            "left_address_hex": _hex32(left_address),
            "right_address_hex": _hex32(right_address),
            "result_hex": _hex32(result),
            "mismatch_index": mismatch_index,
            "left_sample_hex": left[: self.compare_size].hex().upper(),
            "right_sample_hex": right[: self.compare_size].hex().upper(),
        }
        if len(self.sampled_invocations) < self.sample_limit:
            self.sampled_invocations.append(sample)
        trace.add(
            target,
            "title_fixed_width_compare_fast_path",
            compare_size=self.compare_size,
            null_argument=left_address == 0 or right_address == 0,
            **sample,
        )

    def summary(self) -> dict[str, Any]:
        return {
            "compare_address": self.compare_address,
            "compare_address_hex": _hex32(self.compare_address),
            "compare_size": self.compare_size,
            "compare_bypass_enabled": False,
            "invocation_count": self.invocation_count,
            "equal_count": self.equal_count,
            "less_count": self.less_count,
            "greater_count": self.greater_count,
            "null_argument_count": self.null_argument_count,
            "sampled_invocations": self.sampled_invocations,
        }


class TitleFrontendCompareSearchSentinelRepair:
    """Repair missing child-list sentinels before the recovered tree search."""

    def __init__(self, *, sample_limit: int = 16) -> None:
        self.sample_limit = sample_limit
        self.invocation_count = 0
        self.null_root_count = 0
        self.repair_count = 0
        self.synthetic_root_seed_count = 0
        self.repaired_next_count = 0
        self.repaired_previous_count = 0
        self.samples: list[dict[str, Any]] = []
        self.call_site_counts: Counter[int] = Counter()
        self.signature_counts: Counter[tuple[int, int, int, int, int, int]] = Counter()

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if cpu.eip != TITLE_FRONTEND_COMPARE_SEARCH_ADDRESS:
            return

        self.invocation_count += 1
        esp = cpu.get_register("esp")
        return_address = memory.read_u32(esp)
        supplied_root = memory.read_u32(_u32(esp + 4))
        root = supplied_root or memory.read_u32(
            TITLE_FRONTEND_COMPARE_SEARCH_GLOBAL_ROOT_ADDRESS
        )
        out_pointer = memory.read_u32(_u32(esp + 8))
        comparator = memory.read_u32(_u32(esp + 0x0C))
        key = memory.read_u32(_u32(esp + 0x10))
        mode = memory.read_u32(_u32(esp + 0x14))
        self.call_site_counts[return_address] += 1
        signature = (return_address, supplied_root, root, out_pointer, key, mode)
        self.signature_counts[signature] += 1
        if supplied_root == 0 and root == 0:
            root = TITLE_FRONTEND_COMPARE_SEARCH_SYNTHETIC_ROOT_ADDRESS
            sentinel = _u32(root + TITLE_FRONTEND_COMPARE_SEARCH_CHILD_LIST_OFFSET)
            memory.write_u32(TITLE_FRONTEND_COMPARE_SEARCH_GLOBAL_ROOT_ADDRESS, root)
            memory.write_u32(root, TITLE_FRONTEND_COMPARE_SEARCH_SYNTHETIC_KEY_ADDRESS)
            memory.write(
                TITLE_FRONTEND_COMPARE_SEARCH_SYNTHETIC_KEY_ADDRESS,
                bytes(TITLE_FIXED_WIDTH_COMPARE_BYTES),
            )
            memory.write_u32(sentinel, sentinel)
            memory.write_u32(_u32(sentinel + 4), sentinel)
            self.synthetic_root_seed_count += 1
            trace.add(
                TITLE_FRONTEND_COMPARE_SEARCH_ADDRESS,
                "title_frontend_compare_search_root_seed",
                steps=steps,
                return_address_hex=_hex32(return_address),
                root_hex=_hex32(root),
                sentinel_hex=_hex32(sentinel),
                key_storage_hex=_hex32(
                    TITLE_FRONTEND_COMPARE_SEARCH_SYNTHETIC_KEY_ADDRESS
                ),
            )
        valid_root = 0x00010000 <= root < 0x80000000
        if not valid_root:
            self.null_root_count += 1
            sample = {
                "steps": steps,
                "return_address_hex": _hex32(return_address),
                "supplied_root_hex": _hex32(supplied_root),
                "root_hex": _hex32(root),
                "valid_root": False,
                "out_pointer_hex": _hex32(out_pointer),
                "comparator_hex": _hex32(comparator),
                "key_hex": _hex32(key),
                "mode_hex": _hex32(mode),
                "repair": False,
            }
            if (
                len(self.samples) < self.sample_limit
                and self.signature_counts[signature] == 1
            ):
                self.samples.append(sample)
            return

        sentinel = _u32(root + TITLE_FRONTEND_COMPARE_SEARCH_CHILD_LIST_OFFSET)
        next_link = memory.read_u32(sentinel)
        previous_link = memory.read_u32(_u32(sentinel + 4))
        repaired_next = next_link == 0
        repaired_previous = previous_link == 0
        if repaired_next:
            memory.write_u32(sentinel, sentinel)
            self.repaired_next_count += 1
        if repaired_previous:
            memory.write_u32(_u32(sentinel + 4), sentinel)
            self.repaired_previous_count += 1
        repaired = repaired_next or repaired_previous
        if repaired:
            self.repair_count += 1

        sample = {
            "steps": steps,
            "return_address_hex": _hex32(return_address),
            "supplied_root_hex": _hex32(supplied_root),
            "root_hex": _hex32(root),
            "valid_root": True,
            "out_pointer_hex": _hex32(out_pointer),
            "comparator_hex": _hex32(comparator),
            "key_hex": _hex32(key),
            "mode_hex": _hex32(mode),
            "sentinel_hex": _hex32(sentinel),
            "next_link_before_hex": _hex32(next_link),
            "previous_link_before_hex": _hex32(previous_link),
            "repair": repaired,
        }
        if (
            len(self.samples) < self.sample_limit
            and self.signature_counts[signature] == 1
        ):
            self.samples.append(sample)
        if repaired:
            trace.add(
                TITLE_FRONTEND_COMPARE_SEARCH_ADDRESS,
                "title_frontend_compare_search_sentinel_repair",
                **sample,
            )

    def summary(self) -> dict[str, Any]:
        return {
            "search_address_hex": _hex32(TITLE_FRONTEND_COMPARE_SEARCH_ADDRESS),
            "global_root_address_hex": _hex32(
                TITLE_FRONTEND_COMPARE_SEARCH_GLOBAL_ROOT_ADDRESS
            ),
            "child_list_offset": TITLE_FRONTEND_COMPARE_SEARCH_CHILD_LIST_OFFSET,
            "invocation_count": self.invocation_count,
            "null_root_count": self.null_root_count,
            "repair_count": self.repair_count,
            "synthetic_root_seed_count": self.synthetic_root_seed_count,
            "repaired_next_count": self.repaired_next_count,
            "repaired_previous_count": self.repaired_previous_count,
            "call_site_counts": {
                _hex32(address): count
                for address, count in sorted(self.call_site_counts.items())
            },
            "unique_signature_count": len(self.signature_counts),
            "samples": self.samples,
        }


class TitleSubsystemInitializerAudit:
    """Read-only audit of the title's ordered subsystem initializer table."""

    observer_addresses = {
        TITLE_SUBSYSTEM_STARTUP_ADDRESS,
        TITLE_SUBSYSTEM_INITIALIZER_DRIVER_ADDRESS,
        TITLE_SUBSYSTEM_INITIALIZER_TABLE_ADDRESS,
        TITLE_SUBSYSTEM_INITIALIZER_CALL_ADDRESS,
        TITLE_SUBSYSTEM_INITIALIZER_RESULT_ADDRESS,
        TITLE_FRONTEND_REGISTRY_INITIALIZER_ADDRESS,
        TITLE_FRONTEND_REGISTRY_ROOT_PUBLISH_ADDRESS,
    }

    def __init__(self, *, sample_limit: int = 64) -> None:
        self.sample_limit = sample_limit
        self.attempt_count = 0
        self.result_count = 0
        self.stage_counts: Counter[int] = Counter()
        self.registry_root_candidates: list[dict[str, Any]] = []
        self._pending: list[dict[str, Any]] = []
        self.records: list[dict[str, Any]] = []

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        _trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if cpu.eip in {
            TITLE_SUBSYSTEM_STARTUP_ADDRESS,
            TITLE_SUBSYSTEM_INITIALIZER_DRIVER_ADDRESS,
            TITLE_SUBSYSTEM_INITIALIZER_TABLE_ADDRESS,
            TITLE_FRONTEND_REGISTRY_INITIALIZER_ADDRESS,
            TITLE_FRONTEND_REGISTRY_ROOT_PUBLISH_ADDRESS,
        }:
            self.stage_counts[cpu.eip] += 1
            if cpu.eip == TITLE_FRONTEND_REGISTRY_ROOT_PUBLISH_ADDRESS:
                self.registry_root_candidates.append(
                    {
                        "steps": steps,
                        "root_candidate_hex": _hex32(cpu.get_register("eax")),
                    }
                )
            return
        if cpu.eip == TITLE_SUBSYSTEM_INITIALIZER_CALL_ADDRESS:
            table_entry = cpu.get_register("edi")
            record = {
                "index": cpu.get_register("esi"),
                "table_entry_hex": _hex32(table_entry),
                "initializer_hex": _hex32(memory.read_u32(table_entry)),
                "call_steps": steps,
                "result": None,
            }
            self.attempt_count += 1
            self._pending.append(record)
            if len(self.records) < self.sample_limit:
                self.records.append(record)
            return
        if cpu.eip != TITLE_SUBSYSTEM_INITIALIZER_RESULT_ADDRESS:
            return
        self.result_count += 1
        if not self._pending:
            return
        record = self._pending.pop()
        record["result"] = cpu.get_register("eax")
        record["result_hex"] = _hex32(cpu.get_register("eax"))
        record["result_steps"] = steps

    def summary(self) -> dict[str, Any]:
        return {
            "call_address_hex": _hex32(TITLE_SUBSYSTEM_INITIALIZER_CALL_ADDRESS),
            "result_address_hex": _hex32(
                TITLE_SUBSYSTEM_INITIALIZER_RESULT_ADDRESS
            ),
            "attempt_count": self.attempt_count,
            "result_count": self.result_count,
            "stage_counts": {
                _hex32(address): self.stage_counts[address]
                for address in sorted(self.observer_addresses)
            },
            "registry_root_candidates": self.registry_root_candidates,
            "failed_initializers": [
                record for record in self.records if record.get("result") == 0
            ],
            "records": self.records,
        }


class TitleFrontendRegistryAudit:
    """Read-only audit of frontend class attachment and GUID lookup results."""

    observer_addresses = {
        TITLE_FRONTEND_REGISTRY_LOOKUP_ADDRESS,
        TITLE_FRONTEND_REGISTRY_LOOKUP_RESULT_ADDRESS,
        TITLE_FRONTEND_REGISTRY_ATTACH_ADDRESS,
        TITLE_FRONTEND_REGISTRY_ATTACH_RESULT_ADDRESS,
        TITLE_FRONTEND_REGISTRY_ATTACH_FAILURE_ADDRESS,
        TITLE_FRONTEND_REGISTRY_ATTACH_SUCCESS_ADDRESS,
        TITLE_FRONTEND_REGISTRY_TARGET_CLASS_INIT_ADDRESS,
        TITLE_FRONTEND_SUBSYSTEM_SHUTDOWN_ADDRESS,
        TITLE_FRONTEND_CONSTRUCTOR_RESULT_ADDRESS,
        TITLE_FRONTEND_CONSTRUCTOR_FRONTEND_OBJECT_RESULT_ADDRESS,
        TITLE_FRONTEND_CONSTRUCTOR_DESCRIPTOR_RESULT_ADDRESS,
        TITLE_FRONTEND_CONSTRUCTOR_FRONTEND_STATE_RESULT_ADDRESS,
        TITLE_FRONTEND_CONSTRUCTOR_RESOURCE_OBJECT_RESULT_ADDRESS,
        TITLE_FRONTEND_CONSTRUCTOR_RESOURCE_FAILURE_ADDRESS,
        TITLE_FRONTEND_CONSTRUCTOR_SUBSYSTEM_FAILURE_ADDRESS,
        TITLE_FRONTEND_OBJECT_CREATE_FACTORY_RESULT_ADDRESS,
        TITLE_FRONTEND_OBJECT_CREATE_INTERFACE_RESULT_ADDRESS,
        TITLE_FRONTEND_OBJECT_CREATE_FAILURE_ADDRESS,
        TITLE_FRONTEND_OBJECT_CREATE_SUCCESS_ADDRESS,
        TITLE_FRONTEND_DESCRIPTOR_ALLOCATE_ADDRESS,
        TITLE_FRONTEND_DEFAULT_FACTORY_ADDRESS,
        TITLE_FRONTEND_FACTORY_RESULT_ADDRESS,
        TITLE_FRONTEND_OBJECT_INITIALIZER_RESULT_ADDRESS,
        TITLE_FRONTEND_OBJECT_INITIALIZER_FAILURE_ADDRESS,
        TITLE_FRONTEND_OBJECT_INITIALIZER_SUCCESS_ADDRESS,
        TITLE_FRONTEND_OBJECT_AUDIO_CREATE_RESULT_ADDRESS,
        TITLE_FRONTEND_OBJECT_AUDIO_STATE_ALLOC_RESULT_ADDRESS,
        TITLE_FRONTEND_OBJECT_AUDIO_INIT_RESULT_ADDRESS,
        TITLE_DSOUND_INIT_DEVICE_RESULT_ADDRESS,
        TITLE_DSOUND_INIT_CAPABILITY_RESULT_ADDRESS,
        TITLE_DSOUND_INIT_MIXBIN_CREATE_RESULT_ADDRESS,
        TITLE_DSOUND_INIT_MIXBIN_CONFIGURE_RESULT_ADDRESS,
        TITLE_DSOUND_INIT_MIXBIN_FINALIZE_RESULT_ADDRESS,
        TITLE_DSOUND_INIT_EXIT_ADDRESS,
        TITLE_DSOUND_DEVICE_CORE_RESULT_ADDRESS,
        TITLE_DSOUND_DEVICE_COMMAND_RESULT_ADDRESS,
        TITLE_DSOUND_DEVICE_EVENT_RESULT_ADDRESS,
        TITLE_DSOUND_DEVICE_VOICE_RESULT_ADDRESS,
        TITLE_DSOUND_CORE_MEMORY_RESULT_ADDRESS,
        TITLE_DSOUND_CORE_HARDWARE_RESULT_ADDRESS,
        TITLE_DSOUND_HARDWARE_VOICE0_CREATE_RESULT_ADDRESS,
        TITLE_DSOUND_HARDWARE_VOICE0_CONFIG_RESULT_ADDRESS,
        TITLE_DSOUND_HARDWARE_VOICE0_START_RESULT_ADDRESS,
        TITLE_DSOUND_HARDWARE_VOICE1_CONFIG_RESULT_ADDRESS,
        TITLE_DSOUND_HARDWARE_VOICE1_START_RESULT_ADDRESS,
    }

    def __init__(self, *, sample_limit: int = 64) -> None:
        self.sample_limit = sample_limit
        self.stage_counts: Counter[int] = Counter()
        self.lookup_count = 0
        self.attach_count = 0
        self.lookup_records: list[dict[str, Any]] = []
        self.attach_records: list[dict[str, Any]] = []
        self.constructor_checkpoints: list[dict[str, Any]] = []
        self.object_create_checkpoints: list[dict[str, Any]] = []
        self.descriptor_allocations: list[dict[str, Any]] = []
        self.dsound_init_checkpoints: list[dict[str, Any]] = []
        self.constructor_results: list[dict[str, Any]] = []
        self._pending_lookups: list[dict[str, Any]] = []
        self._pending_attaches: list[dict[str, Any]] = []

    @staticmethod
    def _key_fields(memory: SparseMemory, object_address: int) -> dict[str, Any]:
        key_address = memory.read_u32(object_address) if object_address else 0
        key_sample = (
            memory.read(key_address, TITLE_FIXED_WIDTH_COMPARE_BYTES)
            if 0x00010000 <= key_address < 0x80000000
            else bytes()
        )
        return {
            "key_address_hex": _hex32(key_address),
            "key_sample_hex": key_sample.hex().upper(),
        }

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        _trace: ExecutionTrace,
        steps: int,
    ) -> None:
        address = cpu.eip
        if address not in self.observer_addresses:
            return
        self.stage_counts[address] += 1
        esp = cpu.get_register("esp")
        if address in {
            TITLE_DSOUND_INIT_DEVICE_RESULT_ADDRESS,
            TITLE_DSOUND_INIT_CAPABILITY_RESULT_ADDRESS,
            TITLE_DSOUND_INIT_MIXBIN_CREATE_RESULT_ADDRESS,
            TITLE_DSOUND_INIT_MIXBIN_CONFIGURE_RESULT_ADDRESS,
            TITLE_DSOUND_INIT_MIXBIN_FINALIZE_RESULT_ADDRESS,
            TITLE_DSOUND_INIT_EXIT_ADDRESS,
            TITLE_DSOUND_DEVICE_CORE_RESULT_ADDRESS,
            TITLE_DSOUND_DEVICE_COMMAND_RESULT_ADDRESS,
            TITLE_DSOUND_DEVICE_EVENT_RESULT_ADDRESS,
            TITLE_DSOUND_DEVICE_VOICE_RESULT_ADDRESS,
            TITLE_DSOUND_CORE_MEMORY_RESULT_ADDRESS,
            TITLE_DSOUND_CORE_HARDWARE_RESULT_ADDRESS,
            TITLE_DSOUND_HARDWARE_VOICE0_CREATE_RESULT_ADDRESS,
            TITLE_DSOUND_HARDWARE_VOICE0_CONFIG_RESULT_ADDRESS,
            TITLE_DSOUND_HARDWARE_VOICE0_START_RESULT_ADDRESS,
            TITLE_DSOUND_HARDWARE_VOICE1_CONFIG_RESULT_ADDRESS,
            TITLE_DSOUND_HARDWARE_VOICE1_START_RESULT_ADDRESS,
        }:
            ebp = cpu.get_register("ebp")
            self.dsound_init_checkpoints.append(
                {
                    "steps": steps,
                    "address_hex": _hex32(address),
                    "eax_hex": _hex32(cpu.get_register("eax")),
                    "mixbin_index": memory.read_u32(_u32(ebp + 8)),
                }
            )
            return
        if address in {
            TITLE_FRONTEND_DESCRIPTOR_ALLOCATE_ADDRESS,
            TITLE_FRONTEND_DEFAULT_FACTORY_ADDRESS,
        }:
            descriptor = memory.read_u32(_u32(esp + 4))
            self.descriptor_allocations.append(
                {
                    "steps": steps,
                    "address_hex": _hex32(address),
                    "descriptor_hex": _hex32(descriptor),
                    "flags_hex": _hex32(memory.read_u32(_u32(descriptor + 0x40))),
                    "element_size": int.from_bytes(
                        memory.read(_u32(descriptor + 0x44), 2), "little"
                    ),
                    "element_count": int.from_bytes(
                        memory.read(_u32(descriptor + 0x46), 2), "little"
                    ),
                    "allocation_hex": _hex32(
                        memory.read_u32(_u32(descriptor + 0x48))
                    ),
                }
            )
            return
        if address in {
            TITLE_FRONTEND_OBJECT_CREATE_FACTORY_RESULT_ADDRESS,
            TITLE_FRONTEND_OBJECT_CREATE_INTERFACE_RESULT_ADDRESS,
            TITLE_FRONTEND_OBJECT_CREATE_FAILURE_ADDRESS,
            TITLE_FRONTEND_OBJECT_CREATE_SUCCESS_ADDRESS,
        }:
            temporary = cpu.get_register("esi")
            self.object_create_checkpoints.append(
                {
                    "steps": steps,
                    "address_hex": _hex32(address),
                    "eax_hex": _hex32(cpu.get_register("eax")),
                    "ecx_hex": _hex32(cpu.get_register("ecx")),
                    "esi_hex": _hex32(temporary),
                    "temporary_object_hex": _hex32(
                        memory.read_u32(temporary) if temporary else 0
                    ),
                    "temporary_interface_hex": _hex32(
                        memory.read_u32(_u32(temporary + 4)) if temporary else 0
                    ),
                }
            )
            return
        if address in {
            TITLE_FRONTEND_FACTORY_RESULT_ADDRESS,
            TITLE_FRONTEND_OBJECT_INITIALIZER_RESULT_ADDRESS,
            TITLE_FRONTEND_OBJECT_INITIALIZER_FAILURE_ADDRESS,
            TITLE_FRONTEND_OBJECT_INITIALIZER_SUCCESS_ADDRESS,
        }:
            constructed = (
                cpu.get_register("eax")
                if address == TITLE_FRONTEND_FACTORY_RESULT_ADDRESS
                else cpu.get_register("esi")
            )
            descriptor = memory.read_u32(constructed) if constructed else 0
            self.object_create_checkpoints.append(
                {
                    "steps": steps,
                    "address_hex": _hex32(address),
                    "eax_hex": _hex32(cpu.get_register("eax")),
                    "constructed_hex": _hex32(constructed),
                    "descriptor_hex": _hex32(descriptor),
                    "initializer_hex": _hex32(
                        memory.read_u32(_u32(descriptor + 0x28))
                        if descriptor
                        else 0
                    ),
                }
            )
            return
        if address in {
            TITLE_FRONTEND_OBJECT_AUDIO_CREATE_RESULT_ADDRESS,
            TITLE_FRONTEND_OBJECT_AUDIO_STATE_ALLOC_RESULT_ADDRESS,
            TITLE_FRONTEND_OBJECT_AUDIO_INIT_RESULT_ADDRESS,
        }:
            self.object_create_checkpoints.append(
                {
                    "steps": steps,
                    "address_hex": _hex32(address),
                    "eax_hex": _hex32(cpu.get_register("eax")),
                    "esi_hex": _hex32(cpu.get_register("esi")),
                    "edi_hex": _hex32(cpu.get_register("edi")),
                }
            )
            return
        if address in {
            TITLE_FRONTEND_CONSTRUCTOR_FRONTEND_OBJECT_RESULT_ADDRESS,
            TITLE_FRONTEND_CONSTRUCTOR_DESCRIPTOR_RESULT_ADDRESS,
            TITLE_FRONTEND_CONSTRUCTOR_FRONTEND_STATE_RESULT_ADDRESS,
            TITLE_FRONTEND_CONSTRUCTOR_RESOURCE_OBJECT_RESULT_ADDRESS,
            TITLE_FRONTEND_CONSTRUCTOR_RESOURCE_FAILURE_ADDRESS,
            TITLE_FRONTEND_CONSTRUCTOR_SUBSYSTEM_FAILURE_ADDRESS,
        }:
            owner = cpu.get_register("esi")
            self.constructor_checkpoints.append(
                {
                    "steps": steps,
                    "address_hex": _hex32(address),
                    "eax_hex": _hex32(cpu.get_register("eax")),
                    "edi_hex": _hex32(cpu.get_register("edi")),
                    "owner_hex": _hex32(owner),
                    "frontend_object_hex": _hex32(
                        memory.read_u32(_u32(owner + 0x58))
                    ),
                    "frontend_state_hex": _hex32(
                        memory.read_u32(_u32(owner + 0x5C))
                    ),
                    "resource_object_hex": _hex32(
                        memory.read_u32(_u32(owner + 0x124))
                    ),
                }
            )
            return
        if address == TITLE_FRONTEND_CONSTRUCTOR_RESULT_ADDRESS:
            owner = cpu.get_register("esi")
            self.constructor_results.append(
                {
                    "steps": steps,
                    "owner_hex": _hex32(owner),
                    "result_hex": _hex32(cpu.get_register("edi")),
                    "frontend_object_hex": _hex32(
                        memory.read_u32(_u32(owner + 0x58))
                    ),
                    "frontend_state_hex": _hex32(
                        memory.read_u32(_u32(owner + 0x5C))
                    ),
                    "resource_object_hex": _hex32(
                        memory.read_u32(_u32(owner + 0x124))
                    ),
                }
            )
            return
        if address == TITLE_FRONTEND_REGISTRY_LOOKUP_ADDRESS:
            key_address = memory.read_u32(_u32(esp + 8))
            record = {
                "steps": steps,
                "supplied_root_hex": _hex32(memory.read_u32(_u32(esp + 4))),
                "global_root_hex": _hex32(
                    memory.read_u32(TITLE_FRONTEND_COMPARE_SEARCH_GLOBAL_ROOT_ADDRESS)
                ),
                "key_address_hex": _hex32(key_address),
                "key_sample_hex": memory.read(
                    key_address, TITLE_FIXED_WIDTH_COMPARE_BYTES
                ).hex().upper(),
                "out_pointer_hex": _hex32(memory.read_u32(_u32(esp + 0x0C))),
                "result": None,
            }
            self.lookup_count += 1
            self._pending_lookups.append(record)
            if len(self.lookup_records) < self.sample_limit:
                self.lookup_records.append(record)
            return
        if address == TITLE_FRONTEND_REGISTRY_LOOKUP_RESULT_ADDRESS:
            if self._pending_lookups:
                record = self._pending_lookups.pop()
                record["result"] = cpu.get_register("eax")
                record["result_hex"] = _hex32(cpu.get_register("eax"))
                record["result_steps"] = steps
            return
        if address == TITLE_FRONTEND_REGISTRY_ATTACH_ADDRESS:
            parent = memory.read_u32(_u32(esp + 4))
            attached = memory.read_u32(_u32(esp + 8))
            record = {
                "steps": steps,
                "parent_hex": _hex32(parent),
                "attached_hex": _hex32(attached),
                "parent_key": self._key_fields(memory, parent),
                "attached_key": self._key_fields(memory, attached),
                "compatibility_result": None,
                "outcome": None,
            }
            self.attach_count += 1
            self._pending_attaches.append(record)
            if len(self.attach_records) < self.sample_limit:
                self.attach_records.append(record)
            return
        if address == TITLE_FRONTEND_REGISTRY_ATTACH_RESULT_ADDRESS:
            if self._pending_attaches:
                record = self._pending_attaches[-1]
                record["compatibility_result"] = cpu.get_register("eax")
                record["compatibility_result_hex"] = _hex32(
                    cpu.get_register("eax")
                )
                record["result_steps"] = steps
            return
        if address in {
            TITLE_FRONTEND_REGISTRY_ATTACH_FAILURE_ADDRESS,
            TITLE_FRONTEND_REGISTRY_ATTACH_SUCCESS_ADDRESS,
        } and self._pending_attaches:
            record = self._pending_attaches.pop()
            record["outcome"] = (
                "success"
                if address == TITLE_FRONTEND_REGISTRY_ATTACH_SUCCESS_ADDRESS
                else "incompatible"
            )
            record["outcome_steps"] = steps

    def summary(self) -> dict[str, Any]:
        return {
            "lookup_count": self.lookup_count,
            "lookup_miss_count": sum(
                record.get("result") == 0 for record in self.lookup_records
            ),
            "attach_count": self.attach_count,
            "incompatible_attach_count": sum(
                record.get("outcome") == "incompatible"
                for record in self.attach_records
            ),
            "target_class_init_count": self.stage_counts[
                TITLE_FRONTEND_REGISTRY_TARGET_CLASS_INIT_ADDRESS
            ],
            "subsystem_shutdown_count": self.stage_counts[
                TITLE_FRONTEND_SUBSYSTEM_SHUTDOWN_ADDRESS
            ],
            "stage_counts": {
                _hex32(address): self.stage_counts[address]
                for address in sorted(self.observer_addresses)
            },
            "lookup_records": self.lookup_records,
            "attach_records": self.attach_records,
            "constructor_checkpoints": self.constructor_checkpoints,
            "object_create_checkpoints": self.object_create_checkpoints,
            "descriptor_allocations": self.descriptor_allocations,
            "dsound_init_checkpoints": self.dsound_init_checkpoints,
            "constructor_results": self.constructor_results,
        }


class TitleFrontendRecordTableCountRepair:
    """Clamp the observed uninitialized frontend record-table count."""

    def __init__(self) -> None:
        self.observation_count = 0
        self.repair_count = 0
        self.last_repair: dict[str, Any] | None = None

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if cpu.eip != TITLE_FRONTEND_RECORD_TABLE_SCAN_ADDRESS:
            return
        self.observation_count += 1
        table_address = cpu.get_register("edi")
        if not table_address:
            return
        count_address = _u32(table_address + 4)
        count = memory.read_u32(count_address)
        if count <= TITLE_FRONTEND_RECORD_TABLE_MAX_COUNT:
            return
        memory.write_u32(count_address, 0)
        self.repair_count += 1
        self.last_repair = {
            "steps": steps,
            "table_address_hex": _hex32(table_address),
            "count_address_hex": _hex32(count_address),
            "count_before_hex": _hex32(count),
            "count_after": 0,
        }
        trace.add(
            TITLE_FRONTEND_RECORD_TABLE_SCAN_ADDRESS,
            "title_frontend_record_table_count_repair",
            **self.last_repair,
        )

    def summary(self) -> dict[str, Any]:
        return {
            "scan_address_hex": _hex32(TITLE_FRONTEND_RECORD_TABLE_SCAN_ADDRESS),
            "observation_count": self.observation_count,
            "repair_count": self.repair_count,
            "last_repair": self.last_repair,
        }


class TitleFrontendPostAudioListRepair:
    """Close a synthetic frontend list node whose next link was left null."""

    def __init__(self) -> None:
        self.observation_count = 0
        self.repair_count = 0
        self.last_repair: dict[str, Any] | None = None

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if cpu.eip != TITLE_FRONTEND_POST_AUDIO_LIST_ADVANCE_ADDRESS:
            return
        self.observation_count += 1
        current_link = cpu.get_register("esi")
        if current_link in {0, TITLE_FRONTEND_POST_AUDIO_LIST_SENTINEL_ADDRESS}:
            return
        next_link = memory.read_u32(current_link)
        if next_link != 0:
            return
        memory.write_u32(current_link, TITLE_FRONTEND_POST_AUDIO_LIST_SENTINEL_ADDRESS)
        self.repair_count += 1
        self.last_repair = {
            "steps": steps,
            "current_link_hex": _hex32(current_link),
            "next_link_before_hex": _hex32(next_link),
            "sentinel_hex": _hex32(TITLE_FRONTEND_POST_AUDIO_LIST_SENTINEL_ADDRESS),
        }
        trace.add(
            TITLE_FRONTEND_POST_AUDIO_LIST_ADVANCE_ADDRESS,
            "title_frontend_post_audio_list_repair",
            repair_count=self.repair_count,
            **self.last_repair,
        )

    def summary(self) -> dict[str, Any]:
        return {
            "advance_address_hex": _hex32(TITLE_FRONTEND_POST_AUDIO_LIST_ADVANCE_ADDRESS),
            "sentinel_address_hex": _hex32(TITLE_FRONTEND_POST_AUDIO_LIST_SENTINEL_ADDRESS),
            "observation_count": self.observation_count,
            "repair_count": self.repair_count,
            "last_repair": self.last_repair,
        }


class TitleFrontendStaticSingletonRepair:
    """Materialize the three title singletons whose CRT constructors were missed."""

    def __init__(self) -> None:
        self.observation_count = 0
        self.repair_count = 0
        self.repairs: list[dict[str, Any]] = []
        self.dynamic_object_transitions: list[dict[str, Any]] = []
        self._last_dynamic_pointer: int | None = None
        self._last_dynamic_vtable: int | None = None

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        dynamic_pointer = memory.read_u32(
            TITLE_FRONTEND_DYNAMIC_OBJECT_OWNER_ADDRESS
            + TITLE_FRONTEND_DYNAMIC_OBJECT_POINTER_OFFSET
        )
        dynamic_vtable = memory.read_u32(dynamic_pointer) if dynamic_pointer else 0
        if (
            dynamic_pointer != self._last_dynamic_pointer
            or dynamic_vtable != self._last_dynamic_vtable
        ):
            if len(self.dynamic_object_transitions) < 16:
                self.dynamic_object_transitions.append(
                    {
                        "steps": steps,
                        "next_instruction_hex": _hex32(cpu.eip),
                        "object_address_hex": _hex32(dynamic_pointer),
                        "vtable_address_hex": _hex32(dynamic_vtable),
                    }
                )
            self._last_dynamic_pointer = dynamic_pointer
            self._last_dynamic_vtable = dynamic_vtable
        if cpu.eip != TITLE_FRONTEND_STATIC_SINGLETON_USE_ADDRESS:
            return
        self.observation_count += 1
        repairs = (
            self._repair_record_singleton(
                memory,
                TITLE_FRONTEND_STATIC_SINGLETON_OBJECT_ADDRESS,
                TITLE_FRONTEND_STATIC_SINGLETON_VTABLE_ADDRESS,
                zero_offsets=(0x10C, 0x110, 0x114, 0x118),
                records_offset=TITLE_FRONTEND_STATIC_SINGLETON_RECORDS_OFFSET,
                record_count=TITLE_FRONTEND_STATIC_SINGLETON_RECORD_COUNT,
            ),
            self._repair_record_singleton(
                memory,
                TITLE_FRONTEND_STATIC_SINGLETON_AUDIO_OBJECT_ADDRESS,
                TITLE_FRONTEND_STATIC_SINGLETON_AUDIO_VTABLE_ADDRESS,
                zero_offsets=(0x40, 0x44, 0x48, 0x4C),
                records_offset=TITLE_FRONTEND_STATIC_SINGLETON_AUDIO_RECORDS_OFFSET,
                record_count=TITLE_FRONTEND_STATIC_SINGLETON_AUDIO_RECORD_COUNT,
            ),
            self._repair_effect_singleton(memory),
        )
        for repair in repairs:
            if repair is None:
                continue
            repair["steps"] = steps
            self.repair_count += 1
            self.repairs.append(repair)
            trace.add(
                TITLE_FRONTEND_STATIC_SINGLETON_USE_ADDRESS,
                "title_frontend_static_singleton_repair",
                repair_count=self.repair_count,
                **repair,
            )

    @staticmethod
    def _repair_record_singleton(
        memory: SparseMemory,
        object_address: int,
        vtable_address: int,
        *,
        zero_offsets: tuple[int, ...],
        records_offset: int,
        record_count: int,
    ) -> dict[str, Any] | None:
        vtable_before = memory.read_u32(object_address)
        if vtable_before != 0:
            return None
        memory.write_u32(object_address, vtable_address)
        for offset in zero_offsets:
            memory.write_u32(_u32(object_address + offset), 0)
        for index in range(record_count):
            record = _u32(
                object_address
                + records_offset
                + index * TITLE_FRONTEND_STATIC_SINGLETON_RECORD_SIZE
            )
            memory.write_u32(record, 1)
            for field_offset in range(4, TITLE_FRONTEND_STATIC_SINGLETON_RECORD_SIZE, 4):
                memory.write_u32(_u32(record + field_offset), 0)
        return {
            "object_address_hex": _hex32(object_address),
            "vtable_before_hex": _hex32(vtable_before),
            "vtable_after_hex": _hex32(vtable_address),
            "record_count": record_count,
        }

    @staticmethod
    def _repair_effect_singleton(memory: SparseMemory) -> dict[str, Any] | None:
        object_address = TITLE_FRONTEND_STATIC_SINGLETON_EFFECT_OBJECT_ADDRESS
        vtable_before = memory.read_u32(object_address)
        if vtable_before != 0:
            return None
        memory.write_u32(object_address, TITLE_FRONTEND_STATIC_SINGLETON_EFFECT_VTABLE_ADDRESS)
        for index in range(0x6A):
            memory.write_u32(_u32(object_address + 0x368 + index * 0x3C), 0x002B6B30)
            memory.write_u32(_u32(object_address + 0x1C40 + index * 0x48), 0x002B6B38)
        memory.write_u32(_u32(object_address + 0x3A10), 0x002B6B3C)
        return {
            "object_address_hex": _hex32(object_address),
            "vtable_before_hex": _hex32(vtable_before),
            "vtable_after_hex": _hex32(
                TITLE_FRONTEND_STATIC_SINGLETON_EFFECT_VTABLE_ADDRESS
            ),
            "record_count": 0x6A * 2 + 1,
        }

    def summary(self) -> dict[str, Any]:
        return {
            "use_address_hex": _hex32(TITLE_FRONTEND_STATIC_SINGLETON_USE_ADDRESS),
            "object_address_hex": _hex32(
                TITLE_FRONTEND_STATIC_SINGLETON_OBJECT_ADDRESS
            ),
            "vtable_address_hex": _hex32(
                TITLE_FRONTEND_STATIC_SINGLETON_VTABLE_ADDRESS
            ),
            "observation_count": self.observation_count,
            "repair_count": self.repair_count,
            "repairs": self.repairs,
            "dynamic_object_transitions": self.dynamic_object_transitions,
        }


class TitleRuntimeObjectTableConstructorRepair:
    """Restore the missed CRT constructors for the runtime object table."""

    def __init__(self) -> None:
        self.observation_count = 0
        self.repair_count = 0
        self.repairs: list[dict[str, Any]] = []

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if cpu.eip != TITLE_RUNTIME_OBJECT_TABLE_USE_ADDRESS:
            return
        self.observation_count += 1
        for object_address, vtable_address, records_offset, record_count in (
            TITLE_RUNTIME_OBJECT_CONSTRUCTOR_SPECS
        ):
            if memory.read_u32(object_address) != 0:
                continue
            memory.write_u32(object_address, vtable_address)
            for index in range(record_count):
                record = _u32(
                    object_address
                    + records_offset
                    + index * TITLE_FRONTEND_STATIC_SINGLETON_RECORD_SIZE
                )
                memory.write_u32(record, 1)
                for offset in range(4, TITLE_FRONTEND_STATIC_SINGLETON_RECORD_SIZE, 4):
                    memory.write_u32(_u32(record + offset), 0)
            if object_address == 0x004EC318:
                memory.write_u32(object_address + 0x5D8, 1)
                memory.write_u32(object_address + 0x5F0, 0xFFFFFFFF)
            elif object_address == 0x004ECF08:
                memory.write_u32(object_address + 0x2AC, 1)
                memory.write_u32(object_address + 0x2C4, 0xFFFFFFFF)
            repair = {
                "steps": steps,
                "object_address_hex": _hex32(object_address),
                "vtable_address_hex": _hex32(vtable_address),
                "records_offset_hex": _hex32(records_offset),
                "record_count": record_count,
            }
            self.repair_count += 1
            self.repairs.append(repair)
            trace.add(
                TITLE_RUNTIME_OBJECT_TABLE_USE_ADDRESS,
                "title_runtime_object_table_constructor_repair",
                repair_count=self.repair_count,
                **repair,
            )

    def summary(self) -> dict[str, Any]:
        return {
            "use_address_hex": _hex32(TITLE_RUNTIME_OBJECT_TABLE_USE_ADDRESS),
            "specification_count": len(TITLE_RUNTIME_OBJECT_CONSTRUCTOR_SPECS),
            "observation_count": self.observation_count,
            "repair_count": self.repair_count,
            "repairs": self.repairs,
        }


class TitleRuntimeCallbackListRepair:
    """Close the runtime callback list when its parsed owner has no valid nodes."""

    def __init__(self) -> None:
        self.observation_count = 0
        self.repair_count = 0
        self.repairs: list[dict[str, Any]] = []

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if cpu.eip not in TITLE_RUNTIME_CALLBACK_DISPATCH_ADDRESSES:
            return
        self.observation_count += 1
        esp = cpu.get_register("esp")
        object_address = memory.read_u32(_u32(esp + 4))
        global_object = memory.read_u32(TITLE_RUNTIME_CALLBACK_GLOBAL_OBJECT_ADDRESS)
        synthesized = object_address == 0
        if synthesized:
            object_address = TITLE_RUNTIME_CALLBACK_SYNTHETIC_OBJECT_ADDRESS
            memory.write_u32(_u32(esp + 4), object_address)
            memory.write_u32(TITLE_RUNTIME_CALLBACK_GLOBAL_OBJECT_ADDRESS, object_address)
            memory.write_u32(
                object_address,
                TITLE_RUNTIME_CALLBACK_SYNTHETIC_VTABLE_ADDRESS,
            )
            memory.write_u32(
                TITLE_RUNTIME_CALLBACK_SYNTHETIC_VTABLE_ADDRESS + 0x2C,
                0,
            )
            memory.write_u32(
                TITLE_RUNTIME_CALLBACK_SYNTHETIC_VTABLE_ADDRESS + 0x30,
                0,
            )
            global_object = object_address
        if object_address != global_object:
            return
        sentinel = _u32(object_address + TITLE_RUNTIME_CALLBACK_LIST_OFFSET)
        next_link = memory.read_u32(sentinel)
        previous_link = memory.read_u32(_u32(sentinel + 4))
        if next_link == sentinel and previous_link == sentinel:
            return
        memory.write_u32(sentinel, sentinel)
        memory.write_u32(_u32(sentinel + 4), sentinel)
        repair = {
            "steps": steps,
            "dispatch_address_hex": _hex32(cpu.eip),
            "object_address_hex": _hex32(object_address),
            "sentinel_address_hex": _hex32(sentinel),
            "next_link_before_hex": _hex32(next_link),
            "previous_link_before_hex": _hex32(previous_link),
            "synthesized_owner": synthesized,
        }
        self.repair_count += 1
        self.repairs.append(repair)
        trace.add(
            cpu.eip,
            "title_runtime_callback_list_repair",
            repair_count=self.repair_count,
            **repair,
        )

    def summary(self) -> dict[str, Any]:
        return {
            "dispatch_addresses_hex": [
                _hex32(address) for address in TITLE_RUNTIME_CALLBACK_DISPATCH_ADDRESSES
            ],
            "global_object_address_hex": _hex32(
                TITLE_RUNTIME_CALLBACK_GLOBAL_OBJECT_ADDRESS
            ),
            "observation_count": self.observation_count,
            "repair_count": self.repair_count,
            "repairs": self.repairs,
        }


class TitleHeapLargeBinIntegrityRepair:
    """Restore the title allocator's circular large-bin list invariant.

    The five observed scans all walk the same intrusive doubly linked list. A
    healthy walk must reach ``heap + 0x180``; a repeated link, a null/unaligned
    link, or a link whose chunk header is not a large-bin size is conclusive
    corruption. Native live runs yield at bounded instruction intervals, so the
    repair can validate the complete list without adding a callback to this hot
    guest loop.
    """

    _RETAINED_REPAIR_LIMIT = 32
    _LINK_SAMPLE_LIMIT = 16

    def __init__(self, *, max_nodes: int = TITLE_HEAP_LARGE_BIN_MAX_NODES) -> None:
        if max_nodes <= 0:
            raise ValueError("title heap large-bin scan limit must be positive")
        self.max_nodes = max_nodes
        self.observation_count = 0
        self.healthy_count = 0
        self.repair_count = 0
        self.reroute_count = 0
        self.invalid_heap_base_count = 0
        self.scan_limit_count = 0
        self.scan_observation_counts: dict[str, int] = {}
        self.repair_counts_by_scan: dict[str, int] = {}
        self.termination_counts: dict[str, int] = {}
        self.repairs: list[dict[str, Any]] = []
        self.last_scan_limit: dict[str, Any] | None = None

    @staticmethod
    def _scan_spec(
        instruction_address: int,
    ) -> tuple[str, int, int, str] | None:
        for spec in TITLE_HEAP_LARGE_BIN_SCAN_SPECS:
            _, loop_entry, loop_end, _ = spec
            if loop_entry <= instruction_address < loop_end:
                return spec
        return None

    def service_native_slice(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> bool:
        spec = self._scan_spec(cpu.eip)
        if spec is None:
            return False
        scan_kind, loop_entry, _, cursor_register = spec
        self.observation_count += 1
        self.scan_observation_counts[scan_kind] = (
            self.scan_observation_counts.get(scan_kind, 0) + 1
        )

        heap_base = cpu.get_register("ebx")
        if heap_base == 0 or (heap_base & 0xF):
            self.invalid_heap_base_count += 1
            return False
        sentinel = _u32(heap_base + TITLE_HEAP_LARGE_BIN_SENTINEL_OFFSET)
        head_before = memory.read_u32(sentinel)
        sentinel_previous_before = memory.read_u32(_u32(sentinel + 4))
        nodes: list[int] = []
        seen: dict[int, int] = {}
        current = head_before
        repeated_link: int | None = None
        repeated_index: int | None = None
        invalid_chunk_size: int | None = None
        termination = "sentinel"

        while current != sentinel:
            if current == 0:
                termination = "null_link"
                break
            if (current & 0xF) != 8:
                termination = "unaligned_link"
                break
            if current in seen:
                termination = "cycle"
                repeated_link = current
                repeated_index = seen[current]
                break
            if len(nodes) >= self.max_nodes:
                termination = "scan_limit"
                break
            chunk_header = _u32(current - 8)
            chunk_size = int.from_bytes(memory.read(chunk_header, 2), "little")
            if not 0x80 <= chunk_size <= 0xFF00:
                termination = "invalid_chunk_size"
                invalid_chunk_size = chunk_size
                break
            seen[current] = len(nodes)
            nodes.append(current)
            current = memory.read_u32(current)

        backlink_mismatches = 0
        if termination == "sentinel":
            expected_previous = sentinel
            for node in nodes:
                if memory.read_u32(_u32(node + 4)) != expected_previous:
                    backlink_mismatches += 1
                expected_previous = node
            if sentinel_previous_before != expected_previous:
                backlink_mismatches += 1
            if backlink_mismatches == 0:
                self.healthy_count += 1
                return False
            termination = "backlink_mismatch"

        if termination == "scan_limit":
            self.scan_limit_count += 1
            self.last_scan_limit = {
                "steps": steps,
                "scan_kind": scan_kind,
                "instruction_address_hex": _hex32(cpu.eip),
                "heap_base_hex": _hex32(heap_base),
                "sentinel_address_hex": _hex32(sentinel),
                "node_count": len(nodes),
                "next_link_hex": _hex32(current),
            }
            return False

        instruction_address = cpu.eip
        changed_links: list[dict[str, Any]] = []
        changed_link_count = 0

        def write_link(address: int, value: int, role: str) -> None:
            nonlocal changed_link_count
            before = memory.read_u32(address)
            if before == value:
                return
            memory.write_u32(address, value)
            changed_link_count += 1
            if len(changed_links) < self._LINK_SAMPLE_LIMIT:
                changed_links.append(
                    {
                        "role": role,
                        "address_hex": _hex32(address),
                        "before_hex": _hex32(before),
                        "after_hex": _hex32(value),
                    }
                )

        first = nodes[0] if nodes else sentinel
        last = nodes[-1] if nodes else sentinel
        write_link(sentinel, first, "sentinel.next")
        write_link(_u32(sentinel + 4), last, "sentinel.previous")
        for index, node in enumerate(nodes):
            next_link = nodes[index + 1] if index + 1 < len(nodes) else sentinel
            previous_link = nodes[index - 1] if index > 0 else sentinel
            write_link(node, next_link, "node.next")
            write_link(_u32(node + 4), previous_link, "node.previous")

        rerouted = termination != "backlink_mismatch"
        if rerouted:
            # Resume at the real loop head with its cursor equal to the
            # sentinel. The guest executes the ordinary compare and exit path;
            # no allocation/free body is synthesized or skipped.
            cpu.set_register(cursor_register, sentinel)
            cpu.eip = loop_entry
            self.reroute_count += 1

        self.repair_count += 1
        self.repair_counts_by_scan[scan_kind] = (
            self.repair_counts_by_scan.get(scan_kind, 0) + 1
        )
        self.termination_counts[termination] = (
            self.termination_counts.get(termination, 0) + 1
        )
        repair = {
            "steps": steps,
            "scan_kind": scan_kind,
            "instruction_address_hex": _hex32(instruction_address),
            "resume_address_hex": _hex32(cpu.eip),
            "cursor_register": cursor_register,
            "heap_base_hex": _hex32(heap_base),
            "sentinel_address_hex": _hex32(sentinel),
            "head_before_hex": _hex32(head_before),
            "sentinel_previous_before_hex": _hex32(sentinel_previous_before),
            "termination": termination,
            "repeated_link_hex": (
                _hex32(repeated_link) if repeated_link is not None else None
            ),
            "repeated_index": repeated_index,
            "invalid_chunk_size": invalid_chunk_size,
            "backlink_mismatch_count": backlink_mismatches,
            "preserved_node_count": len(nodes),
            "preserved_nodes_hex": [
                _hex32(node) for node in nodes[: self._LINK_SAMPLE_LIMIT]
            ],
            "preserved_nodes_truncated": len(nodes) > self._LINK_SAMPLE_LIMIT,
            "changed_link_count": changed_link_count,
            "changed_links": changed_links,
            "rerouted_to_loop_head": rerouted,
        }
        self.repairs.append(repair)
        if len(self.repairs) > self._RETAINED_REPAIR_LIMIT:
            del self.repairs[: len(self.repairs) - self._RETAINED_REPAIR_LIMIT]
        return True

    def summary(self) -> dict[str, Any]:
        return {
            "sentinel_offset_hex": _hex32(TITLE_HEAP_LARGE_BIN_SENTINEL_OFFSET),
            "max_nodes": self.max_nodes,
            "scan_specs": [
                {
                    "scan_kind": scan_kind,
                    "loop_entry_hex": _hex32(loop_entry),
                    "loop_end_hex": _hex32(loop_end),
                    "cursor_register": cursor_register,
                }
                for scan_kind, loop_entry, loop_end, cursor_register in (
                    TITLE_HEAP_LARGE_BIN_SCAN_SPECS
                )
            ],
            "observation_count": self.observation_count,
            "healthy_count": self.healthy_count,
            "repair_count": self.repair_count,
            "reroute_count": self.reroute_count,
            "invalid_heap_base_count": self.invalid_heap_base_count,
            "scan_limit_count": self.scan_limit_count,
            "scan_observation_counts": self.scan_observation_counts,
            "repair_counts_by_scan": self.repair_counts_by_scan,
            "termination_counts": self.termination_counts,
            "retained_repair_count": len(self.repairs),
            "repairs": self.repairs,
            "last_scan_limit": self.last_scan_limit,
        }


class TitleRuntimeCallbackAudit:
    """Summarize frontend callback targets and their Boolean results."""

    _OBSERVER_ADDRESSES = {
        *TITLE_RUNTIME_CALLBACK_CALL_SITES,
        *TITLE_RUNTIME_CALLBACK_RETURN_SITES,
    }

    def __init__(self, *, enabled: bool = True) -> None:
        self.enabled = enabled
        self.observer_addresses = (
            set(self._OBSERVER_ADDRESSES) if enabled else set()
        )
        self._pending: dict[int, list[tuple[str, int, int]]] = {}
        self._targets: dict[tuple[str, int, int], dict[str, Any]] = {}
        self.unmatched_return_count = 0

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        call_spec = TITLE_RUNTIME_CALLBACK_CALL_SITES.get(cpu.eip)
        thread_key = cpu.fs_base
        if call_spec is not None:
            kind, target_register, object_register = call_spec
            target = cpu.get_register(target_register)
            object_address = cpu.get_register(object_register)
            self._pending.setdefault(thread_key, []).append(
                (kind, target, object_address)
            )
            key = (kind, target, object_address)
            item = self._targets.setdefault(
                key,
                {
                    "kind": kind,
                    "target": target,
                    "target_hex": _hex32(target),
                    "object_address": object_address,
                    "object_address_hex": _hex32(object_address),
                    "vtable_address_hex": _hex32(memory.read_u32(object_address)),
                    "call_count": 0,
                    "zero_result_count": 0,
                    "nonzero_result_count": 0,
                    "last_result": None,
                    "last_result_hex": None,
                    "first_steps": steps,
                    "last_steps": steps,
                },
            )
            item["call_count"] += 1
            item["last_steps"] = steps
            return

        return_kind = TITLE_RUNTIME_CALLBACK_RETURN_SITES.get(cpu.eip)
        if return_kind is None:
            return
        pending = self._pending.get(thread_key)
        if not pending:
            self.unmatched_return_count += 1
            return
        pending_index = next(
            (
                index
                for index in range(len(pending) - 1, -1, -1)
                if pending[index][0] == return_kind
            ),
            None,
        )
        if pending_index is None:
            self.unmatched_return_count += 1
            return
        kind, target, object_address = pending.pop(pending_index)
        result = cpu.get_register("eax")
        item = self._targets[(kind, target, object_address)]
        if result == 0:
            item["zero_result_count"] += 1
        else:
            item["nonzero_result_count"] += 1
        item["last_result"] = result
        item["last_result_hex"] = _hex32(result)
        item["last_steps"] = steps

    def summary(self) -> dict[str, Any]:
        targets = sorted(
            self._targets.values(),
            key=lambda item: (-item["call_count"], item["target"], item["kind"]),
        )
        return {
            "enabled": self.enabled,
            "observer_addresses_hex": [
                _hex32(address) for address in sorted(self.observer_addresses)
            ],
            "target_count": len(targets),
            "call_count": sum(item["call_count"] for item in targets),
            "zero_result_count": sum(
                item["zero_result_count"] for item in targets
            ),
            "nonzero_result_count": sum(
                item["nonzero_result_count"] for item in targets
            ),
            "unmatched_return_count": self.unmatched_return_count,
            "pending_call_count": sum(
                len(pending) for pending in self._pending.values()
            ),
            "targets": targets,
        }


class TitleD3DPresentAudit:
    """Record the title D3D Present path down to its flip packet write."""

    observer_addresses = TITLE_D3D_PRESENT_OBSERVER_ADDRESSES

    def __init__(self) -> None:
        self.counts: dict[int, int] = {
            address: 0 for address in self.observer_addresses
        }
        self.last_samples: dict[int, dict[str, Any]] = {}

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if cpu.eip not in self.observer_addresses:
            return
        self.counts[cpu.eip] += 1
        context_address = memory.read_u32(TITLE_D3D_CONTEXT_GLOBAL_ADDRESS)
        sample = {
            "address_hex": _hex32(cpu.eip),
            "steps": steps,
            "eax_hex": _hex32(cpu.get_register("eax")),
            "ebx_hex": _hex32(cpu.get_register("ebx")),
            "esi_hex": _hex32(cpu.get_register("esi")),
            "context_address_hex": _hex32(context_address),
            "context_flags_hex": _hex32(
                memory.read_u32(_u32(context_address + 8))
                if context_address != 0
                else 0
            ),
            "present_flags_hex": _hex32(
                memory.read_u32(_u32(cpu.get_register("esp") + 4))
                if cpu.eip == 0x002224A0
                else cpu.get_register("ebx")
            ),
        }
        self.last_samples[cpu.eip] = sample
        trace.add(
            cpu.eip,
            "title_d3d_present_audit",
            observation_count=self.counts[cpu.eip],
            **sample,
        )

    def summary(self) -> dict[str, Any]:
        observations = [
            {
                "address_hex": _hex32(address),
                "observation_count": self.counts[address],
                "last_sample": self.last_samples.get(address),
            }
            for address in sorted(self.observer_addresses)
        ]
        return {
            "entry_count": self.counts[0x002224A0],
            "immediate_path_count": self.counts[0x00222506],
            "queued_path_count": self.counts[0x00222546],
            "flip_header_write_count": sum(
                self.counts[address]
                for address in (0x00222271, 0x00222290, 0x002223F4)
            ),
            "observations": observations,
        }


class TitleWorldMatrixAudit:
    """Observe RenderWare shader inputs and writes to one selected source matrix."""

    def __init__(
        self,
        *,
        enabled: bool = False,
        build_address: int = TITLE_WORLD_MATRIX_BUILD_ADDRESS,
        sample_limit: int = TITLE_WORLD_MATRIX_SAMPLE_LIMIT,
        render_watchpoint: RenderWriteWatchpoint | None = None,
        write_watch_address: int | None = None,
    ) -> None:
        if write_watch_address is not None and not 0 <= write_watch_address <= 0xFFFFFFC0:
            raise ValueError("world-matrix write watch must fit in the 32-bit address space")
        self.enabled = enabled or write_watch_address is not None
        self.build_address = build_address
        self.sample_limit = max(2, sample_limit)
        self.render_watchpoint = render_watchpoint
        self.write_watch_address = (
            _u32(write_watch_address) if write_watch_address is not None else None
        )
        self.observer_addresses = (
            {
                build_address,
                TITLE_WORLD_DRAW_CALLBACK_ADDRESS,
                TITLE_D3D_INDEXED_DRAW_ADDRESS,
                TITLE_CAMERA_UPDATE_ADDRESS,
                TITLE_CAMERA_TARGET_FRAME_RETURN_ADDRESS,
                TITLE_CAMERA_UPDATE_RETURN_ADDRESS,
                TITLE_GENERIC_CAMERA_UPDATE_ADDRESS,
                TITLE_GENERIC_CAMERA_TARGET_FRAME_RETURN_ADDRESS,
                *TITLE_GENERIC_CAMERA_UPDATE_RETURN_ADDRESSES,
            }
            if self.enabled
            else set()
        )
        if self.write_watch_address is not None:
            self.observer_addresses.update(
                {
                    TITLE_WORLD_MATRIX_ROTATE_ADDRESS,
                    TITLE_WORLD_MATRIX_ROTATION_BUILD_ADDRESS,
                    *TITLE_WORLD_MATRIX_ROTATE_RETURN_ADDRESSES,
                }
            )
        self.memory_callback_addresses = (
            set(range(self.write_watch_address, self.write_watch_address + 0x40, 4))
            if self.write_watch_address is not None
            else set()
        )
        self.invocation_count = 0
        self.singular_matrix_count = 0
        self.nonfinite_matrix_count = 0
        self.caller_counts: Counter[int] = Counter()
        self.source_counts: Counter[tuple[int, int]] = Counter()
        self.singular_source_counts: Counter[tuple[int, int]] = Counter()
        self.first_singular_samples: list[dict[str, Any]] = []
        self.latest_singular_samples: deque[dict[str, Any]] = deque(
            maxlen=self.sample_limit // 2
        )
        self.first_healthy_sample: dict[str, Any] | None = None
        self.latest_healthy_sample: dict[str, Any] | None = None
        self.latest_matrix_sample: dict[str, Any] | None = None
        self.camera_update_count = 0
        self.camera_target_frame_count = 0
        self.camera_update_completion_count = 0
        self.pending_camera_samples: list[dict[str, Any]] = []
        self.first_camera_samples: list[dict[str, Any]] = []
        self.latest_camera_samples: deque[dict[str, Any]] = deque(
            maxlen=self.sample_limit // 2
        )
        self.camera_candidate_tables: dict[str, list[float | None]] | None = None
        self.generic_camera_update_count = 0
        self.generic_camera_target_frame_count = 0
        self.generic_camera_update_completion_count = 0
        self.pending_generic_camera_samples: list[dict[str, Any]] = []
        self.first_generic_camera_samples: list[dict[str, Any]] = []
        self.latest_generic_camera_samples: deque[dict[str, Any]] = deque(
            maxlen=self.sample_limit // 2
        )
        self.world_draw_callback_count = 0
        self.world_draw_callback_zero_index_count = 0
        self.world_draw_callback_caller_counts: Counter[int] = Counter()
        self.world_draw_callback_mode_counts: Counter[int] = Counter()
        self.world_draw_callback_count_values: Counter[int] = Counter()
        self.world_draw_callback_caller_samples: dict[int, dict[str, Any]] = {}
        self.first_world_draw_callback_samples: list[dict[str, Any]] = []
        self.latest_world_draw_callback_samples: deque[dict[str, Any]] = deque(
            maxlen=self.sample_limit // 2
        )
        self.indexed_draw_count = 0
        self.zero_index_draw_count = 0
        self.indexed_draw_caller_counts: Counter[int] = Counter()
        self.zero_index_draw_caller_counts: Counter[int] = Counter()
        self.indexed_draw_count_values: Counter[int] = Counter()
        self.first_indexed_draw_samples: list[dict[str, Any]] = []
        self.latest_indexed_draw_samples: deque[dict[str, Any]] = deque(
            maxlen=self.sample_limit // 2
        )
        self.write_count = 0
        self.write_instruction_counts: Counter[int] = Counter()
        self.singularizing_write_count = 0
        self.restoring_write_count = 0
        self.first_write_samples: list[dict[str, Any]] = []
        self.latest_write_samples: deque[dict[str, Any]] = deque(
            maxlen=self.sample_limit // 2
        )
        self.transition_samples: deque[dict[str, Any]] = deque(
            maxlen=self.sample_limit
        )
        self.rotation_entry_count = 0
        self.rotation_completion_count = 0
        self.rotation_singular_input_count = 0
        self.rotation_singular_output_count = 0
        self.rotation_nonfinite_output_count = 0
        self.rotation_return_counts: Counter[int] = Counter()
        self.rotation_stage_counts: Counter[tuple[int, bool, bool]] = Counter()
        self.rotation_unmatched_completion_count = 0
        self.pending_rotation_calls: dict[int, deque[dict[str, Any]]] = {}
        self.active_rotation_calls: list[dict[str, Any]] = []
        self.first_rotation_samples: list[dict[str, Any]] = []
        self.latest_rotation_samples: deque[dict[str, Any]] = deque(
            maxlen=self.sample_limit // 2
        )

    @staticmethod
    def _determinant(rows: tuple[tuple[float, float, float], ...]) -> float:
        (a, b, c), (d, e, f), (g, h, i) = rows
        return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g)

    @classmethod
    def _describe_matrix(cls, raw: bytes) -> dict[str, Any]:
        dwords = struct.unpack("<16I", raw)
        values = struct.unpack("<16f", raw)
        rows = tuple(
            tuple(values[row * 4 + component] for component in range(3))
            for row in range(4)
        )
        basis = rows[:3]
        basis_finite = all(math.isfinite(value) for row in basis for value in row)
        row_lengths = tuple(
            math.sqrt(sum(value * value for value in row))
            if all(math.isfinite(value) for value in row)
            else math.inf
            for row in basis
        )
        determinant = cls._determinant(basis) if basis_finite else math.nan
        length_product = math.prod(row_lengths)
        normalized_determinant = (
            abs(determinant) / length_product
            if basis_finite and length_product > 1.0e-30
            else 0.0
        )
        reasons: list[str] = []
        if not basis_finite:
            reasons.append("nonfinite_basis")
        if any(length <= 1.0e-8 for length in row_lengths):
            reasons.append("degenerate_basis_axis")
        if basis_finite and normalized_determinant <= 1.0e-5:
            reasons.append("linearly_dependent_basis")
        return {
            "basis_rows": [list(row) for row in basis],
            "position": list(rows[3]),
            "basis_row_lengths": list(row_lengths),
            "basis_determinant": determinant if math.isfinite(determinant) else None,
            "normalized_basis_determinant": normalized_determinant,
            "singular": bool(reasons),
            "reasons": reasons,
            "raw_dwords_hex": [_hex32(value) for value in dwords],
        }

    @staticmethod
    def _describe_fpu(cpu: CpuState) -> dict[str, Any]:
        stack = list(cpu.fpu_stack[:8])
        return {
            "mxcsr_hex": _hex32(cpu.mxcsr),
            "control_word_hex": f"0x{cpu.fpu_control_word & 0xFFFF:04X}",
            "status_word_hex": f"0x{cpu.fpu_status_word & 0xFFFF:04X}",
            "stack_depth": len(cpu.fpu_stack),
            "stack_values": [
                value if math.isfinite(value) else None for value in stack
            ],
            "stack_values_f32_hex": [
                _hex32(struct.unpack("<I", struct.pack("<f", value))[0])
                if math.isfinite(value)
                else None
                for value in stack
            ],
        }

    def _guest_flip_count(self) -> int | None:
        return (
            self.render_watchpoint.flip_count
            if self.render_watchpoint is not None
            else None
        )

    @staticmethod
    def _read_float_vector(
        memory: SparseMemory,
        address: int,
        count: int = 3,
    ) -> list[float | None]:
        values = struct.unpack(f"<{count}f", memory.read(address, count * 4))
        return [value if math.isfinite(value) else None for value in values]

    def _observe_camera_update_entry(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        esp = cpu.get_register("esp")
        sample = {
            "entry_steps": steps,
            "entry_guest_flip_count": self._guest_flip_count(),
            "strategy_address_hex": _hex32(cpu.get_register("ecx")),
            "vehicle_address_hex": _hex32(memory.read_u32(_u32(esp + 4))),
            "manager_address_hex": _hex32(memory.read_u32(_u32(esp + 8))),
            "caller_return_address_hex": _hex32(memory.read_u32(esp)),
        }
        self.camera_update_count += 1
        self.pending_camera_samples.append(sample)
        if self.camera_candidate_tables is None:
            self.camera_candidate_tables = {
                name: self._read_float_vector(
                    memory,
                    address,
                    TITLE_CAMERA_CANDIDATE_COUNT,
                )
                for name, address in (
                    ("x", TITLE_CAMERA_CANDIDATE_X_ADDRESS),
                    ("y", TITLE_CAMERA_CANDIDATE_Y_ADDRESS),
                    ("z", TITLE_CAMERA_CANDIDATE_Z_ADDRESS),
                    ("fov", TITLE_CAMERA_CANDIDATE_FOV_ADDRESS),
                )
            }

    def _observe_camera_target_frame(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        if not self.pending_camera_samples:
            return
        sample = self.pending_camera_samples[-1]
        vehicle_frame_address = cpu.get_register("eax")
        camera_matrix_address = cpu.get_register("esi")
        sample.update(
            {
                "target_frame_steps": steps,
                "target_frame_guest_flip_count": self._guest_flip_count(),
                "vehicle_frame_address_hex": _hex32(vehicle_frame_address),
                "camera_matrix_address_hex": _hex32(camera_matrix_address),
                "vehicle_frame": self._describe_matrix(
                    memory.read(vehicle_frame_address, 0x40)
                ),
                "camera_before": self._describe_matrix(
                    memory.read(camera_matrix_address, 0x40)
                ),
            }
        )
        self.camera_target_frame_count += 1

    def _observe_camera_update_completion(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        if not self.pending_camera_samples:
            return
        sample = self.pending_camera_samples.pop()
        strategy_address = cpu.get_register("esi")
        camera_matrix_hex = sample.get("camera_matrix_address_hex")
        camera_matrix_address = (
            int(camera_matrix_hex, 16) if isinstance(camera_matrix_hex, str) else 0
        )
        sample.update(
            {
                "completion_steps": steps,
                "completion_guest_flip_count": self._guest_flip_count(),
                "camera_mode": memory.read_u32(_u32(strategy_address + 0x58)),
                "camera_position": self._read_float_vector(
                    memory, _u32(strategy_address + 0x5C)
                ),
                "look_vector": self._read_float_vector(
                    memory, _u32(strategy_address + 0x68)
                ),
                "selected_offset": self._read_float_vector(
                    memory, _u32(strategy_address + 0x74)
                ),
                "selected_candidate_index": memory.read_u32(
                    _u32(strategy_address + 0x84)
                ),
                "collision_target": self._read_float_vector(
                    memory, _u32(strategy_address + 0x140)
                ),
                "camera_after": (
                    self._describe_matrix(memory.read(camera_matrix_address, 0x40))
                    if camera_matrix_address
                    else None
                ),
            }
        )
        vehicle_frame = sample.get("vehicle_frame")
        camera_after = sample.get("camera_after")
        if isinstance(vehicle_frame, dict) and isinstance(camera_after, dict):
            vehicle_position = vehicle_frame["position"]
            camera_position = camera_after["position"]
            sample["camera_to_vehicle_distance"] = math.sqrt(
                sum(
                    (float(camera_position[index]) - float(vehicle_position[index])) ** 2
                    for index in range(3)
                )
            )
        self.camera_update_completion_count += 1
        if len(self.first_camera_samples) < self.sample_limit // 2:
            self.first_camera_samples.append(sample)
        self.latest_camera_samples.append(sample)

    def _observe_generic_camera_update_entry(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        esp = cpu.get_register("esp")
        vehicle_address = memory.read_u32(_u32(esp + 4))
        manager_address = memory.read_u32(_u32(esp + 8))
        active_index = memory.read_u32(_u32(manager_address + 0x228))
        active_entry_address = _u32(
            manager_address + 0x170 + active_index * 0xBC
        )
        camera_owner_address = memory.read_u32(manager_address)
        camera_frame_address = memory.read_u32(
            _u32(camera_owner_address + 4)
        )
        camera_matrix_address = _u32(camera_frame_address + 0x10)
        vehicle_index = memory.read_u32(_u32(vehicle_address + 4))
        vehicle_data_address = memory.read_u32(_u32(vehicle_address + 8))
        configuration_addresses = {
            "angle": 0x005312B0,
            "rotation_a": 0x005318F8,
            "rotation_b": 0x005315D8,
            "blend": 0x00531580,
            "pitch_a": 0x00531308,
            "height_a": 0x00530FF0,
            "forward_a": 0x00531258,
            "pitch_b": 0x005317F0,
            "height_b": 0x00531630,
            "forward_b": 0x00530E28,
            "turn_scale": 0x00530D18,
        }
        sample = {
            "entry_steps": steps,
            "entry_guest_flip_count": self._guest_flip_count(),
            "strategy_address_hex": _hex32(cpu.get_register("ecx")),
            "vehicle_address_hex": _hex32(vehicle_address),
            "manager_address_hex": _hex32(manager_address),
            "caller_return_address_hex": _hex32(memory.read_u32(esp)),
            "active_camera_index": active_index,
            "active_camera_entry_address_hex": _hex32(active_entry_address),
            "camera_type": memory.read_u32(active_entry_address),
            "camera_frame_address_hex": _hex32(camera_frame_address),
            "camera_matrix_address_hex": _hex32(camera_matrix_address),
            "camera_before": self._describe_matrix(
                memory.read(camera_matrix_address, 0x40)
            ),
            "vehicle_index": vehicle_index,
            "vehicle_data_address_hex": _hex32(vehicle_data_address),
            "vehicle_local_offset": self._read_float_vector(
                memory, _u32(vehicle_data_address + 0xA0)
            ),
            "vehicle_motion_value": self._read_float_vector(
                memory, _u32(vehicle_data_address + 0x134), 1
            )[0],
            "configuration": {
                name: self._read_float_vector(
                    memory,
                    _u32(address + vehicle_index * 4),
                    1,
                )[0]
                for name, address in configuration_addresses.items()
            },
            "active_camera_entry_dwords_hex": [
                _hex32(memory.read_u32(_u32(active_entry_address + offset)))
                for offset in range(0, 0xBC, 4)
            ],
        }
        self.generic_camera_update_count += 1
        self.pending_generic_camera_samples.append(sample)

    def _observe_generic_camera_target_frame(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        if not self.pending_generic_camera_samples:
            return
        sample = self.pending_generic_camera_samples[-1]
        vehicle_frame_address = cpu.get_register("eax")
        sample.update(
            {
                "target_frame_steps": steps,
                "target_frame_guest_flip_count": self._guest_flip_count(),
                "vehicle_frame_address_hex": _hex32(vehicle_frame_address),
                "vehicle_frame": self._describe_matrix(
                    memory.read(vehicle_frame_address, 0x40)
                ),
            }
        )
        self.generic_camera_target_frame_count += 1

    def _observe_generic_camera_update_completion(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        if not self.pending_generic_camera_samples:
            return
        sample = self.pending_generic_camera_samples.pop()
        camera_matrix_address = int(sample["camera_matrix_address_hex"], 16)
        camera_after = self._describe_matrix(
            memory.read(camera_matrix_address, 0x40)
        )
        sample.update(
            {
                "completion_steps": steps,
                "completion_guest_flip_count": self._guest_flip_count(),
                "dispatch_return_address_hex": _hex32(cpu.eip),
                "camera_after": camera_after,
            }
        )
        vehicle_frame = sample.get("vehicle_frame")
        if isinstance(vehicle_frame, dict):
            vehicle_position = vehicle_frame["position"]
            camera_position = camera_after["position"]
            sample["camera_to_vehicle_distance"] = math.sqrt(
                sum(
                    (float(camera_position[index]) - float(vehicle_position[index])) ** 2
                    for index in range(3)
                )
            )
        self.generic_camera_update_completion_count += 1
        if len(self.first_generic_camera_samples) < self.sample_limit // 2:
            self.first_generic_camera_samples.append(sample)
        self.latest_generic_camera_samples.append(sample)

    def _observe_world_draw_callback(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        esp = cpu.get_register("esp")
        owner_address = cpu.get_register("ecx")
        mesh_entry_address = memory.read_u32(_u32(esp + 4))
        mesh_entry_dwords = tuple(
            memory.read_u32(_u32(mesh_entry_address + offset))
            for offset in range(0, 0x20, 4)
        )
        index_data_address = mesh_entry_dwords[3]
        index_count = mesh_entry_dwords[4]
        mode = memory.read_u32(_u32(owner_address + 0x14))
        caller_return_address = memory.read_u32(esp)
        ebx = cpu.get_register("ebx")
        if (
            caller_return_address
            in TITLE_WORLD_DRAW_CALLBACK_OBJECT_ROOT_RETURNS
        ):
            mesh_root_address = memory.read_u32(_u32(ebx + 0xCEC))
        elif caller_return_address in TITLE_WORLD_DRAW_CALLBACK_DIRECT_ROOT_RETURNS:
            mesh_root_address = ebx
        else:
            mesh_root_address = 0
        mesh_root_dwords = (
            tuple(
                memory.read_u32(_u32(mesh_root_address + offset))
                for offset in range(0, 0x40, 4)
            )
            if mesh_root_address
            else ()
        )
        sample = {
            "steps": steps,
            "guest_flip_count": self._guest_flip_count(),
            "caller_return_address_hex": _hex32(caller_return_address),
            "owner_address_hex": _hex32(owner_address),
            "owner_mode": mode,
            "mesh_entry_address_hex": _hex32(mesh_entry_address),
            "mesh_entry_index_count_address_hex": _hex32(
                _u32(mesh_entry_address + 0x10)
            ),
            "mesh_entry_dwords_hex": [
                _hex32(value) for value in mesh_entry_dwords
            ],
            "mesh_root_address_hex": (
                _hex32(mesh_root_address) if mesh_root_address else None
            ),
            "mesh_root_dwords_hex": [
                _hex32(value) for value in mesh_root_dwords
            ],
            "registers_hex": {
                register: _hex32(cpu.get_register(register))
                for register in ("eax", "ebx", "ecx", "edx", "esi", "edi")
            },
            "index_data_address_hex": _hex32(index_data_address),
            "index_count": index_count,
        }
        if self.latest_matrix_sample is not None:
            matrix_sample = self.latest_matrix_sample
            sample["active_matrix"] = {
                key: matrix_sample[key]
                for key in (
                    "steps",
                    "guest_flip_count",
                    "caller_return_address_hex",
                    "source_address_hex",
                    "matrix_owner_candidate_hex",
                    "basis_rows",
                    "position",
                    "basis_row_lengths",
                    "basis_determinant",
                    "normalized_basis_determinant",
                    "singular",
                    "reasons",
                )
            }
            sample["active_matrix_step_delta"] = steps - int(matrix_sample["steps"])
        self.world_draw_callback_count += 1
        self.world_draw_callback_caller_counts[caller_return_address] += 1
        self.world_draw_callback_mode_counts[mode] += 1
        self.world_draw_callback_count_values[index_count] += 1
        if index_count == 0:
            self.world_draw_callback_zero_index_count += 1
        prior_caller_sample = self.world_draw_callback_caller_samples.get(
            caller_return_address
        )
        if prior_caller_sample is None or (
            prior_caller_sample["index_count"] != 0 and index_count == 0
        ):
            self.world_draw_callback_caller_samples[
                caller_return_address
            ] = sample
        if len(self.first_world_draw_callback_samples) < self.sample_limit // 2:
            self.first_world_draw_callback_samples.append(sample)
        self.latest_world_draw_callback_samples.append(sample)

    def _observe_indexed_draw(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        esp = cpu.get_register("esp")
        caller_return_address = memory.read_u32(esp)
        upstream_return_address = (
            memory.read_u32(_u32(esp + 0x10))
            if caller_return_address == TITLE_D3D_INDEXED_DRAW_WRAPPER_RETURN_ADDRESS
            else caller_return_address
        )
        primitive_type = memory.read_u32(_u32(esp + 4))
        index_count = memory.read_u32(_u32(esp + 8))
        index_data_address = memory.read_u32(_u32(esp + 12))
        sample = {
            "steps": steps,
            "guest_flip_count": self._guest_flip_count(),
            "caller_return_address_hex": _hex32(caller_return_address),
            "upstream_return_address_hex": _hex32(upstream_return_address),
            "primitive_type": primitive_type,
            "index_count": index_count,
            "index_data_address_hex": _hex32(index_data_address),
        }
        self.indexed_draw_count += 1
        self.indexed_draw_caller_counts[upstream_return_address] += 1
        self.indexed_draw_count_values[index_count] += 1
        if index_count == 0:
            self.zero_index_draw_count += 1
            self.zero_index_draw_caller_counts[upstream_return_address] += 1
        if len(self.first_indexed_draw_samples) < self.sample_limit // 2:
            self.first_indexed_draw_samples.append(sample)
        self.latest_indexed_draw_samples.append(sample)

    def _observe_rotation_entry(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        if self.write_watch_address is None:
            return
        esp = cpu.get_register("esp")
        return_address = memory.read_u32(esp)
        if return_address not in TITLE_WORLD_MATRIX_ROTATE_RETURN_ADDRESSES:
            return
        matrix_address = memory.read_u32(_u32(esp + 4))
        if matrix_address != self.write_watch_address:
            return
        axis_address = memory.read_u32(_u32(esp + 8))
        angle_raw = memory.read_u32(_u32(esp + 12))
        angle = struct.unpack("<f", struct.pack("<I", angle_raw))[0]
        angle_scale_raw = memory.read_u32(TITLE_WORLD_MATRIX_ANGLE_SCALE_ADDRESS)
        angle_scale = struct.unpack(
            "<f", struct.pack("<I", angle_scale_raw)
        )[0]
        one_constant_raw = memory.read_u32(
            TITLE_WORLD_MATRIX_ONE_CONSTANT_ADDRESS
        )
        one_constant = struct.unpack(
            "<f", struct.pack("<I", one_constant_raw)
        )[0]
        axis_raw = memory.read(axis_address, 12)
        axis = struct.unpack("<3f", axis_raw)
        sample = {
            "entry_steps": steps,
            "entry_guest_flip_count": self._guest_flip_count(),
            "return_address_hex": _hex32(return_address),
            "matrix_address_hex": _hex32(matrix_address),
            "axis_address_hex": _hex32(axis_address),
            "axis": list(axis),
            "axis_raw_dwords_hex": [
                _hex32(value) for value in struct.unpack("<3I", axis_raw)
            ],
            "angle_degrees": angle if math.isfinite(angle) else None,
            "angle_raw_hex": _hex32(angle_raw),
            "rotation_constants": {
                "angle_scale": (
                    angle_scale if math.isfinite(angle_scale) else None
                ),
                "angle_scale_raw_hex": _hex32(angle_scale_raw),
                "one": one_constant if math.isfinite(one_constant) else None,
                "one_raw_hex": _hex32(one_constant_raw),
            },
            "combine_mode": memory.read_u32(_u32(esp + 16)),
            "entry_fpu": self._describe_fpu(cpu),
            "input": self._describe_matrix(memory.read(matrix_address, 0x40)),
        }
        self.rotation_entry_count += 1
        if sample["input"]["singular"]:
            self.rotation_singular_input_count += 1
        self.rotation_return_counts[return_address] += 1
        self.pending_rotation_calls.setdefault(return_address, deque()).append(sample)
        self.active_rotation_calls.append(sample)

    def _observe_rotation_builder(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        if self.write_watch_address is None or not self.active_rotation_calls:
            return
        esp = cpu.get_register("esp")
        if memory.read_u32(esp) != TITLE_WORLD_MATRIX_ROTATION_BUILD_RETURN_ADDRESS:
            return
        matrix_address = memory.read_u32(_u32(esp + 4))
        if matrix_address != self.write_watch_address:
            return
        sample = self.active_rotation_calls[-1]
        axis_address = memory.read_u32(_u32(esp + 8))
        axis_raw = memory.read(axis_address, 12)
        axis = struct.unpack("<3f", axis_raw)
        one_minus_cosine_raw = memory.read_u32(_u32(esp + 12))
        sine_raw = memory.read_u32(_u32(esp + 16))
        one_minus_cosine = struct.unpack(
            "<f", struct.pack("<I", one_minus_cosine_raw)
        )[0]
        sine = struct.unpack("<f", struct.pack("<I", sine_raw))[0]
        cosine = 1.0 - one_minus_cosine
        sample["builder"] = {
            "steps": steps,
            "guest_flip_count": self._guest_flip_count(),
            "matrix_address_hex": _hex32(matrix_address),
            "axis_address_hex": _hex32(axis_address),
            "normalized_axis": list(axis),
            "normalized_axis_raw_dwords_hex": [
                _hex32(value) for value in struct.unpack("<3I", axis_raw)
            ],
            "normalized_axis_length": math.sqrt(
                sum(value * value for value in axis)
            )
            if all(math.isfinite(value) for value in axis)
            else None,
            "one_minus_cosine": (
                one_minus_cosine if math.isfinite(one_minus_cosine) else None
            ),
            "one_minus_cosine_raw_hex": _hex32(one_minus_cosine_raw),
            "sine": sine if math.isfinite(sine) else None,
            "sine_raw_hex": _hex32(sine_raw),
            "derived_cosine": cosine if math.isfinite(cosine) else None,
            "unit_circle_error": (
                abs(sine * sine + cosine * cosine - 1.0)
                if math.isfinite(sine) and math.isfinite(cosine)
                else None
            ),
            "combine_mode": memory.read_u32(_u32(esp + 20)),
            "fpu": self._describe_fpu(cpu),
        }

    def _observe_rotation_completion(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        steps: int,
    ) -> None:
        if self.write_watch_address is None:
            return
        return_address = cpu.eip
        pending = self.pending_rotation_calls.get(return_address)
        if not pending:
            self.rotation_unmatched_completion_count += 1
            return
        sample = pending.popleft()
        if sample in self.active_rotation_calls:
            self.active_rotation_calls.remove(sample)
        output = self._describe_matrix(memory.read(self.write_watch_address, 0x40))
        sample.update(
            {
                "completion_steps": steps,
                "completion_guest_flip_count": self._guest_flip_count(),
                "completion_fpu": self._describe_fpu(cpu),
                "output": output,
            }
        )
        self.rotation_completion_count += 1
        output_singular = bool(output["singular"])
        if output_singular:
            self.rotation_singular_output_count += 1
        if "nonfinite_basis" in output["reasons"]:
            self.rotation_nonfinite_output_count += 1
        input_singular = bool(sample["input"]["singular"])
        self.rotation_stage_counts[
            (return_address, input_singular, output_singular)
        ] += 1
        if len(self.first_rotation_samples) < self.sample_limit // 2:
            self.first_rotation_samples.append(sample)
        self.latest_rotation_samples.append(sample)

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if not self.enabled:
            return
        if cpu.eip == TITLE_GENERIC_CAMERA_UPDATE_ADDRESS:
            self._observe_generic_camera_update_entry(cpu, memory, steps)
            return
        if cpu.eip == TITLE_GENERIC_CAMERA_TARGET_FRAME_RETURN_ADDRESS:
            self._observe_generic_camera_target_frame(cpu, memory, steps)
            return
        if cpu.eip in TITLE_GENERIC_CAMERA_UPDATE_RETURN_ADDRESSES:
            self._observe_generic_camera_update_completion(cpu, memory, steps)
            return
        if cpu.eip == TITLE_CAMERA_UPDATE_ADDRESS:
            self._observe_camera_update_entry(cpu, memory, steps)
            return
        if cpu.eip == TITLE_CAMERA_TARGET_FRAME_RETURN_ADDRESS:
            self._observe_camera_target_frame(cpu, memory, steps)
            return
        if cpu.eip == TITLE_CAMERA_UPDATE_RETURN_ADDRESS:
            self._observe_camera_update_completion(cpu, memory, steps)
            return
        if cpu.eip == TITLE_WORLD_DRAW_CALLBACK_ADDRESS:
            self._observe_world_draw_callback(cpu, memory, steps)
            return
        if cpu.eip == TITLE_D3D_INDEXED_DRAW_ADDRESS:
            self._observe_indexed_draw(cpu, memory, steps)
            return
        if cpu.eip == TITLE_WORLD_MATRIX_ROTATE_ADDRESS:
            self._observe_rotation_entry(cpu, memory, steps)
            return
        if cpu.eip == TITLE_WORLD_MATRIX_ROTATION_BUILD_ADDRESS:
            self._observe_rotation_builder(cpu, memory, steps)
            return
        if cpu.eip in TITLE_WORLD_MATRIX_ROTATE_RETURN_ADDRESSES:
            self._observe_rotation_completion(cpu, memory, steps)
            return
        if cpu.eip != self.build_address:
            return
        self.invocation_count += 1
        esp = cpu.get_register("esp")
        caller_return = memory.read_u32(esp)
        source_address = memory.read_u32(_u32(esp + 4))
        raw = memory.read(source_address, 0x40)
        matrix = self._describe_matrix(raw)
        reasons = matrix["reasons"]
        if "nonfinite_basis" in reasons:
            self.nonfinite_matrix_count += 1
        singular = matrix["singular"]
        if singular:
            self.singular_matrix_count += 1
        self.caller_counts[caller_return] += 1
        source_key = (caller_return, source_address)
        self.source_counts[source_key] += 1
        if singular:
            self.singular_source_counts[source_key] += 1
        guest_flip_count = self._guest_flip_count()
        sample = {
            "steps": steps,
            "guest_flip_count": guest_flip_count,
            "caller_return_address_hex": _hex32(caller_return),
            "source_address_hex": _hex32(source_address),
            "matrix_owner_candidate_hex": _hex32(
                _u32(source_address - TITLE_WORLD_MATRIX_OWNER_OFFSET)
            ),
            "eax_hex": _hex32(cpu.get_register("eax")),
            "ebx_hex": _hex32(cpu.get_register("ebx")),
            "ecx_hex": _hex32(cpu.get_register("ecx")),
            "edx_hex": _hex32(cpu.get_register("edx")),
            "esi_hex": _hex32(cpu.get_register("esi")),
            "edi_hex": _hex32(cpu.get_register("edi")),
            **matrix,
        }
        self.latest_matrix_sample = sample
        if singular:
            if len(self.first_singular_samples) < self.sample_limit // 2:
                self.first_singular_samples.append(sample)
            self.latest_singular_samples.append(sample)
            trace.add(
                cpu.eip,
                "title_world_matrix_audit",
                **sample,
            )
        else:
            if self.first_healthy_sample is None:
                self.first_healthy_sample = sample
            self.latest_healthy_sample = sample

    def observe_memory_write(
        self,
        memory: SparseMemory,
        *,
        instruction_address: int,
        write_address: int,
        size: int,
        value: int,
        steps: int,
    ) -> None:
        if self.write_watch_address is None or size <= 0:
            return
        matrix_start = self.write_watch_address
        matrix_end = matrix_start + 0x40
        write_end = write_address + size
        if write_address >= matrix_end or write_end <= matrix_start:
            return
        payload = int(value).to_bytes(size, "little", signed=False)
        before_raw = bytearray(memory.read(matrix_start, 0x40))
        after_raw = bytearray(before_raw)
        overlap_start = max(write_address, matrix_start)
        overlap_end = min(write_end, matrix_end)
        for current in range(overlap_start, overlap_end):
            after_raw[current - matrix_start] = payload[current - write_address]
        before = self._describe_matrix(bytes(before_raw))
        after = self._describe_matrix(bytes(after_raw))
        if before["singular"] and not after["singular"]:
            transition = "restored_nonsingular"
            self.restoring_write_count += 1
        elif not before["singular"] and after["singular"]:
            transition = "became_singular"
            self.singularizing_write_count += 1
        elif after["singular"]:
            transition = "remained_singular"
        else:
            transition = "remained_nonsingular"
        self.write_count += 1
        self.write_instruction_counts[instruction_address] += 1
        sample = {
            "steps": steps,
            "guest_flip_count": (
                self.render_watchpoint.flip_count
                if self.render_watchpoint is not None
                else None
            ),
            "instruction_address_hex": _hex32(instruction_address),
            "write_address_hex": _hex32(write_address),
            "matrix_offset": overlap_start - matrix_start,
            "size": size,
            "value_hex": _hex32(value),
            "transition": transition,
            "before": before,
            "after": after,
        }
        if len(self.first_write_samples) < self.sample_limit // 2:
            self.first_write_samples.append(sample)
        self.latest_write_samples.append(sample)
        if transition in {"became_singular", "restored_nonsingular"}:
            self.transition_samples.append(sample)

    def summary(self) -> dict[str, Any]:
        ranked_sources = sorted(
            self.source_counts.items(),
            key=lambda item: (
                -self.singular_source_counts.get(item[0], 0),
                -item[1],
                item[0],
            ),
        )[: self.sample_limit * 2]
        source_records = [
            {
                "caller_return_address_hex": _hex32(caller),
                "source_address_hex": _hex32(source),
                "matrix_owner_candidate_hex": _hex32(
                    _u32(source - TITLE_WORLD_MATRIX_OWNER_OFFSET)
                ),
                "invocation_count": count,
                "singular_matrix_count": self.singular_source_counts.get(
                    (caller, source), 0
                ),
            }
            for (caller, source), count in ranked_sources
        ]
        singular_samples = [
            *self.first_singular_samples,
            *(
                sample
                for sample in self.latest_singular_samples
                if sample not in self.first_singular_samples
            ),
        ]
        write_samples = [
            *self.first_write_samples,
            *(
                sample
                for sample in self.latest_write_samples
                if sample not in self.first_write_samples
            ),
        ]
        rotation_samples = [
            *self.first_rotation_samples,
            *(
                sample
                for sample in self.latest_rotation_samples
                if sample not in self.first_rotation_samples
            ),
        ]
        world_draw_callback_samples = [
            *self.first_world_draw_callback_samples,
            *(
                sample
                for sample in self.latest_world_draw_callback_samples
                if sample not in self.first_world_draw_callback_samples
            ),
        ]
        indexed_draw_samples = [
            *self.first_indexed_draw_samples,
            *(
                sample
                for sample in self.latest_indexed_draw_samples
                if sample not in self.first_indexed_draw_samples
            ),
        ]
        camera_samples = [
            *self.first_camera_samples,
            *(
                sample
                for sample in self.latest_camera_samples
                if sample not in self.first_camera_samples
            ),
        ]
        generic_camera_samples = [
            *self.first_generic_camera_samples,
            *(
                sample
                for sample in self.latest_generic_camera_samples
                if sample not in self.first_generic_camera_samples
            ),
        ]
        return {
            "enabled": self.enabled,
            "execution_mode": "observer_only_recovered_guest_code",
            "build_address_hex": _hex32(self.build_address),
            "observer_addresses_hex": [
                _hex32(address) for address in sorted(self.observer_addresses)
            ],
            "invocation_count": self.invocation_count,
            "singular_matrix_count": self.singular_matrix_count,
            "nonfinite_matrix_count": self.nonfinite_matrix_count,
            "caller_counts": [
                {
                    "caller_return_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in self.caller_counts.most_common()
            ],
            "source_records": source_records,
            "first_healthy_sample": self.first_healthy_sample,
            "latest_healthy_sample": self.latest_healthy_sample,
            "singular_samples": singular_samples,
            "camera_audit": {
                "entry_address_hex": _hex32(TITLE_CAMERA_UPDATE_ADDRESS),
                "target_frame_return_address_hex": _hex32(
                    TITLE_CAMERA_TARGET_FRAME_RETURN_ADDRESS
                ),
                "completion_address_hex": _hex32(
                    TITLE_CAMERA_UPDATE_RETURN_ADDRESS
                ),
                "update_count": self.camera_update_count,
                "target_frame_count": self.camera_target_frame_count,
                "completion_count": self.camera_update_completion_count,
                "pending_count": len(self.pending_camera_samples),
                "candidate_tables": self.camera_candidate_tables,
                "samples": camera_samples,
            },
            "generic_camera_audit": {
                "entry_address_hex": _hex32(
                    TITLE_GENERIC_CAMERA_UPDATE_ADDRESS
                ),
                "target_frame_return_address_hex": _hex32(
                    TITLE_GENERIC_CAMERA_TARGET_FRAME_RETURN_ADDRESS
                ),
                "completion_addresses_hex": [
                    _hex32(address)
                    for address in sorted(
                        TITLE_GENERIC_CAMERA_UPDATE_RETURN_ADDRESSES
                    )
                ],
                "update_count": self.generic_camera_update_count,
                "target_frame_count": self.generic_camera_target_frame_count,
                "completion_count": self.generic_camera_update_completion_count,
                "pending_count": len(self.pending_generic_camera_samples),
                "samples": generic_camera_samples,
            },
            "indexed_draw_audit": {
                "world_draw_callback_address_hex": _hex32(
                    TITLE_WORLD_DRAW_CALLBACK_ADDRESS
                ),
                "indexed_draw_address_hex": _hex32(
                    TITLE_D3D_INDEXED_DRAW_ADDRESS
                ),
                "world_draw_callback_count": self.world_draw_callback_count,
                "world_draw_callback_zero_index_count": (
                    self.world_draw_callback_zero_index_count
                ),
                "world_draw_callback_caller_counts": [
                    {
                        "caller_return_address_hex": _hex32(address),
                        "invocation_count": count,
                    }
                    for address, count in self.world_draw_callback_caller_counts.most_common()
                ],
                "world_draw_callback_mode_counts": {
                    str(mode): count
                    for mode, count in self.world_draw_callback_mode_counts.most_common()
                },
                "world_draw_callback_count_values": {
                    str(index_count): count
                    for index_count, count in self.world_draw_callback_count_values.most_common()
                },
                "world_draw_callback_caller_samples": [
                    self.world_draw_callback_caller_samples[address]
                    for address in sorted(self.world_draw_callback_caller_samples)
                ],
                "indexed_draw_count": self.indexed_draw_count,
                "zero_index_draw_count": self.zero_index_draw_count,
                "indexed_draw_caller_counts": [
                    {
                        "caller_return_address_hex": _hex32(address),
                        "invocation_count": count,
                        "zero_index_count": self.zero_index_draw_caller_counts[address],
                    }
                    for address, count in self.indexed_draw_caller_counts.most_common()
                ],
                "indexed_draw_count_values": {
                    str(index_count): count
                    for index_count, count in self.indexed_draw_count_values.most_common()
                },
                "world_draw_callback_samples": world_draw_callback_samples,
                "indexed_draw_samples": indexed_draw_samples,
            },
            "write_audit": {
                "enabled": self.write_watch_address is not None,
                "address_hex": (
                    _hex32(self.write_watch_address)
                    if self.write_watch_address is not None
                    else None
                ),
                "byte_count": 0x40 if self.write_watch_address is not None else 0,
                "write_count": self.write_count,
                "singularizing_write_count": self.singularizing_write_count,
                "restoring_write_count": self.restoring_write_count,
                "instruction_counts": [
                    {
                        "instruction_address_hex": _hex32(address),
                        "write_count": count,
                    }
                    for address, count in self.write_instruction_counts.most_common()
                ],
                "write_samples": write_samples,
                "transition_samples": list(self.transition_samples),
            },
            "rotation_audit": {
                "enabled": self.write_watch_address is not None,
                "matrix_address_hex": (
                    _hex32(self.write_watch_address)
                    if self.write_watch_address is not None
                    else None
                ),
                "entry_address_hex": _hex32(TITLE_WORLD_MATRIX_ROTATE_ADDRESS),
                "builder_address_hex": _hex32(
                    TITLE_WORLD_MATRIX_ROTATION_BUILD_ADDRESS
                ),
                "return_addresses_hex": [
                    _hex32(address)
                    for address in sorted(TITLE_WORLD_MATRIX_ROTATE_RETURN_ADDRESSES)
                ],
                "entry_count": self.rotation_entry_count,
                "completion_count": self.rotation_completion_count,
                "pending_count": sum(
                    len(pending) for pending in self.pending_rotation_calls.values()
                ),
                "unmatched_completion_count": (
                    self.rotation_unmatched_completion_count
                ),
                "singular_input_count": self.rotation_singular_input_count,
                "singular_output_count": self.rotation_singular_output_count,
                "nonfinite_output_count": self.rotation_nonfinite_output_count,
                "return_counts": [
                    {
                        "return_address_hex": _hex32(address),
                        "entry_count": count,
                    }
                    for address, count in self.rotation_return_counts.most_common()
                ],
                "stage_records": [
                    {
                        "return_address_hex": _hex32(address),
                        "input_singular": input_singular,
                        "output_singular": output_singular,
                        "completion_count": count,
                    }
                    for (
                        address,
                        input_singular,
                        output_singular,
                    ), count in self.rotation_stage_counts.most_common()
                ],
                "samples": rotation_samples,
            },
        }


@dataclass(frozen=True)
class TitleSceneRecordTableLayout:
    name: str
    record_count: int
    record_address: int
    records: tuple[bytes, ...]


@dataclass(frozen=True)
class TitleSceneRecordSourceLayout:
    title_path: str
    image_base: int
    header: bytes
    tables: tuple[TitleSceneRecordTableLayout, ...]


def _load_title_scene_record_sources(
    extracted_root: Path | None,
) -> tuple[tuple[TitleSceneRecordSourceLayout, ...], tuple[str, ...]]:
    """Load only the small prelinked scene-record tables used by the audit."""

    if extracted_root is None:
        return (), ("extracted disc root is unavailable",)
    track_root = extracted_root / "trackpss"
    if not track_root.is_dir():
        return (), (f"track PSS root does not exist: {track_root}",)

    sources: list[TitleSceneRecordSourceLayout] = []
    errors: list[str] = []
    for path in sorted(track_root.rglob("*.pss")):
        try:
            file_size = path.stat().st_size
            with path.open("rb") as stream:
                header = stream.read(TITLE_TRACK_PSS_HEADER_SIZE)
                if len(header) != TITLE_TRACK_PSS_HEADER_SIZE:
                    raise ValueError("descriptor header is truncated")
                image_anchor = struct.unpack_from(
                    "<I", header, TITLE_TRACK_PSS_IMAGE_ANCHOR_POINTER_OFFSET
                )[0]
                if image_anchor < TITLE_TRACK_PSS_IMAGE_ANCHOR_OFFSET:
                    raise ValueError("image anchor cannot identify a guest base")
                image_base = image_anchor - TITLE_TRACK_PSS_IMAGE_ANCHOR_OFFSET
                tables: list[TitleSceneRecordTableLayout] = []
                for name, count_offset, pointer_offset in TITLE_SCENE_RECORD_TABLE_SPECS:
                    record_count = struct.unpack_from("<I", header, count_offset)[0]
                    record_address = struct.unpack_from("<I", header, pointer_offset)[0]
                    if record_count > TITLE_SCENE_RECORD_MAX_COUNT:
                        raise ValueError(
                            f"{name} scene-record count {record_count} is invalid"
                        )
                    if record_count == 0:
                        tables.append(
                            TitleSceneRecordTableLayout(name, 0, record_address, ())
                        )
                        continue
                    if record_address < image_base:
                        raise ValueError(f"{name} scene-record table precedes its image")
                    table_offset = record_address - image_base
                    table_size = record_count * TITLE_SCENE_RECORD_SIZE
                    if table_offset + table_size > file_size:
                        raise ValueError(f"{name} scene-record table is truncated")
                    stream.seek(table_offset)
                    payload = stream.read(table_size)
                    if len(payload) != table_size:
                        raise ValueError(f"{name} scene-record table read was short")
                    tables.append(
                        TitleSceneRecordTableLayout(
                            name,
                            record_count,
                            record_address,
                            tuple(
                                payload[
                                    index * TITLE_SCENE_RECORD_SIZE :
                                    (index + 1) * TITLE_SCENE_RECORD_SIZE
                                ]
                                for index in range(record_count)
                            ),
                        )
                    )
            sources.append(
                TitleSceneRecordSourceLayout(
                    path.relative_to(extracted_root).as_posix().lower(),
                    image_base,
                    header,
                    tuple(tables),
                )
            )
        except (OSError, ValueError, struct.error) as exc:
            errors.append(f"{path.name}: {exc}")
    return tuple(sources), tuple(errors)


class TitleSceneRecordAudit:
    """Correlate indexed-draw arguments with RAM and prelinked Track PSS records."""

    def __init__(
        self,
        *,
        enabled: bool = False,
        source_layouts: Iterable[TitleSceneRecordSourceLayout] = (),
        source_errors: Iterable[str] = (),
        render_watchpoint: RenderWriteWatchpoint | None = None,
        sample_limit: int = TITLE_SCENE_RECORD_SAMPLE_LIMIT,
    ) -> None:
        self.enabled = enabled
        self.source_layouts = tuple(source_layouts) if enabled else ()
        self.source_errors = tuple(source_errors) if enabled else ()
        self.render_watchpoint = render_watchpoint
        self.sample_limit = max(16, sample_limit)
        self.observer_addresses = (
            {TITLE_D3D_INDEXED_DRAW_ADDRESS} if enabled else set()
        )
        pointer_fields = {
            table.record_address
            + index * TITLE_SCENE_RECORD_SIZE
            + TITLE_SCENE_RECORD_INDEX_POINTER_OFFSET
            for source in self.source_layouts
            for table in source.tables
            for index in range(table.record_count)
        }
        count_fields = {
            table.record_address
            + index * TITLE_SCENE_RECORD_SIZE
            + TITLE_SCENE_RECORD_INDEX_COUNT_OFFSET
            for source in self.source_layouts
            for table in source.tables
            for index in range(table.record_count)
        }
        self.pointer_field_addresses = frozenset(pointer_fields)
        self.watched_field_addresses = tuple(sorted(pointer_fields | count_fields))
        self.scene_draw_count = 0
        self.passed_zero_count = 0
        self.authoritative_zero_count = 0
        self.argument_memory_divergence_count = 0
        self.runtime_source_divergence_count = 0
        self.source_match_counts: Counter[str] = Counter()
        self.status_counts: Counter[str] = Counter()
        self.record_observation_counts: Counter[int] = Counter()
        self.record_samples: list[dict[str, Any]] = []
        self._sample_signatures: set[tuple[Any, ...]] = set()
        self._observed_table_indices: dict[tuple[int, str], set[int]] = {}
        self.first_scene_flip: int | None = None
        self.completed_scene_flip: int | None = None
        self.complete = False
        self.complete_reason: str | None = None
        self.write_count = 0
        self.write_source_counts: Counter[str] = Counter()
        self.write_transition_counts: Counter[str] = Counter()
        self.first_clearing_write: dict[str, Any] | None = None
        self.write_samples: list[dict[str, Any]] = []
        self.latest_write_samples: deque[dict[str, Any]] = deque(maxlen=64)

    def _guest_flip_count(self) -> int | None:
        return (
            self.render_watchpoint.flip_count
            if self.render_watchpoint is not None
            else None
        )

    def _matching_sources(
        self,
        memory: SparseMemory,
        root_address: int,
    ) -> tuple[TitleSceneRecordSourceLayout, ...]:
        runtime_tables = {
            name: (
                memory.read_u32(_u32(root_address + count_offset)),
                memory.read_u32(_u32(root_address + pointer_offset)),
            )
            for name, count_offset, pointer_offset in TITLE_SCENE_RECORD_TABLE_SPECS
        }
        return tuple(
            source
            for source in self.source_layouts
            if all(
                runtime_tables.get(table.name)
                == (table.record_count, table.record_address)
                for table in source.tables
            )
        )

    @staticmethod
    def _runtime_table_record(
        memory: SparseMemory,
        root_address: int,
        record_address: int,
    ) -> tuple[str | None, int | None, int | None]:
        for name, count_offset, pointer_offset in TITLE_SCENE_RECORD_TABLE_SPECS:
            record_count = memory.read_u32(_u32(root_address + count_offset))
            table_address = memory.read_u32(_u32(root_address + pointer_offset))
            table_end = table_address + record_count * TITLE_SCENE_RECORD_SIZE
            if (
                record_count <= TITLE_SCENE_RECORD_MAX_COUNT
                and table_address <= record_address < table_end
                and (record_address - table_address) % TITLE_SCENE_RECORD_SIZE == 0
            ):
                return (
                    name,
                    (record_address - table_address) // TITLE_SCENE_RECORD_SIZE,
                    record_count,
                )
        return None, None, None

    @staticmethod
    def _expected_pairs(
        sources: Iterable[TitleSceneRecordSourceLayout],
        table_name: str | None,
        record_index: int | None,
    ) -> tuple[tuple[int, int], ...]:
        if table_name is None or record_index is None:
            return ()
        pairs = {
            struct.unpack_from(
                "<II",
                table.records[record_index],
                TITLE_SCENE_RECORD_INDEX_POINTER_OFFSET,
            )
            for source in sources
            for table in source.tables
            if table.name == table_name and record_index < table.record_count
        }
        return tuple(sorted(pairs))

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        steps: int,
    ) -> None:
        if not self.enabled or cpu.eip != TITLE_D3D_INDEXED_DRAW_ADDRESS:
            return
        esp = cpu.get_register("esp")
        if memory.read_u32(esp) != TITLE_D3D_INDEXED_DRAW_WRAPPER_RETURN_ADDRESS:
            return
        if memory.read_u32(_u32(esp + 0x10)) != TITLE_SCENE_RECORD_DRAW_RETURN_ADDRESS:
            return

        scene_call_return = memory.read_u32(_u32(esp + 0x20))
        scene_call_address = TITLE_SCENE_RECORD_DRAW_CALL_RETURNS.get(scene_call_return)
        record_address = memory.read_u32(_u32(esp + 0x24))
        if scene_call_address is None or record_address == 0:
            return

        passed_count = memory.read_u32(_u32(esp + 0x08))
        passed_pointer = memory.read_u32(_u32(esp + 0x0C))
        authoritative_pointer = memory.read_u32(
            _u32(record_address + TITLE_SCENE_RECORD_INDEX_POINTER_OFFSET)
        )
        authoritative_count = memory.read_u32(
            _u32(record_address + TITLE_SCENE_RECORD_INDEX_COUNT_OFFSET)
        )
        root_address = memory.read_u32(TITLE_SCENE_RECORD_ROOT_POINTER_ADDRESS)
        table_name, record_index, runtime_table_count = self._runtime_table_record(
            memory, root_address, record_address
        )
        matching_sources = self._matching_sources(memory, root_address)
        expected_pairs = self._expected_pairs(
            matching_sources, table_name, record_index
        )
        passed_pair = (passed_pointer, passed_count)
        authoritative_pair = (authoritative_pointer, authoritative_count)
        if passed_pair != authoritative_pair:
            status = "native_argument_memory_divergence"
            self.argument_memory_divergence_count += 1
        elif expected_pairs and authoritative_pair not in expected_pairs:
            status = "runtime_source_divergence"
            self.runtime_source_divergence_count += 1
        elif passed_pair == (0, 0):
            status = "zero_indices_unattributed"
        else:
            status = "healthy"

        guest_flip_count = self._guest_flip_count()
        if self.first_scene_flip is None:
            self.first_scene_flip = guest_flip_count
        elif guest_flip_count != self.first_scene_flip and not self.complete:
            self.complete = True
            self.complete_reason = "next_scene_flip_observed"
            self.completed_scene_flip = self.first_scene_flip

        self.scene_draw_count += 1
        self.passed_zero_count += int(passed_pair == (0, 0))
        self.authoritative_zero_count += int(authoritative_pair == (0, 0))
        self.status_counts[status] += 1
        self.record_observation_counts[record_address] += 1
        for source in matching_sources:
            self.source_match_counts[source.title_path] += 1
        if table_name is not None and record_index is not None:
            observed = self._observed_table_indices.setdefault(
                (root_address, table_name), set()
            )
            observed.add(record_index)
            if (
                table_name == "primary"
                and runtime_table_count
                and len(observed) >= runtime_table_count
                and not self.complete
            ):
                self.complete = True
                self.complete_reason = "complete_primary_table_observed"
                self.completed_scene_flip = guest_flip_count

        sample = {
            "steps": steps,
            "guest_flip_count": guest_flip_count,
            "scene_loop_call_address_hex": _hex32(scene_call_address),
            "scene_loop_return_address_hex": _hex32(scene_call_return),
            "root_address_hex": _hex32(root_address),
            "table": table_name,
            "record_index": record_index,
            "runtime_table_count": runtime_table_count,
            "record_address_hex": _hex32(record_address),
            "passed_index_pointer_hex": _hex32(passed_pointer),
            "passed_index_count": passed_count,
            "authoritative_index_pointer_hex": _hex32(authoritative_pointer),
            "authoritative_index_count": authoritative_count,
            "expected_pairs": [
                {
                    "index_pointer_hex": _hex32(pointer),
                    "index_count": count,
                }
                for pointer, count in expected_pairs
            ],
            "matching_source_paths": [
                source.title_path for source in matching_sources
            ],
            "status": status,
        }
        signature = (
            record_address,
            passed_pair,
            authoritative_pair,
            expected_pairs,
            status,
        )
        if (
            signature not in self._sample_signatures
            and len(self.record_samples) < self.sample_limit
        ):
            self._sample_signatures.add(signature)
            self.record_samples.append(sample)
        if status != "healthy":
            trace.add(cpu.eip, "title_scene_record_audit", **sample)

    def observe_memory_write(
        self,
        memory: SparseMemory,
        *,
        source: str,
        instruction_address: int | None,
        write_address: int,
        payload: bytes,
        steps: int | None,
    ) -> None:
        if not self.enabled or not payload or not self.watched_field_addresses:
            return
        canonicalize = getattr(memory, "_canonical_address", None)
        start = (
            int(canonicalize(write_address))
            if callable(canonicalize)
            else _u32(write_address)
        )
        end = start + len(payload)
        first = bisect.bisect_left(self.watched_field_addresses, max(0, start - 3))
        for field_address in self.watched_field_addresses[first:]:
            if field_address >= end:
                break
            if field_address + 4 <= start:
                continue
            before_bytes = bytearray(memory.read(field_address, 4))
            after_bytes = bytearray(before_bytes)
            overlap_start = max(start, field_address)
            overlap_end = min(end, field_address + 4)
            for current in range(overlap_start, overlap_end):
                after_bytes[current - field_address] = payload[current - start]
            before = int.from_bytes(before_bytes, "little")
            after = int.from_bytes(after_bytes, "little")
            if before == after:
                continue
            if before != 0 and after == 0:
                transition = "cleared"
            elif before == 0 and after != 0:
                transition = "initialized"
            else:
                transition = "changed"
            sample = {
                "source": source,
                "instruction_address_hex": (
                    _hex32(instruction_address)
                    if instruction_address is not None
                    else None
                ),
                "steps": steps,
                "guest_flip_count": self._guest_flip_count(),
                "write_address_hex": _hex32(start),
                "write_size": len(payload),
                "field_address_hex": _hex32(field_address),
                "field_kind": (
                    "index_pointer"
                    if field_address in self.pointer_field_addresses
                    else "index_count"
                ),
                "before": before,
                "before_hex": _hex32(before),
                "after": after,
                "after_hex": _hex32(after),
                "transition": transition,
            }
            self.write_count += 1
            self.write_source_counts[source] += 1
            self.write_transition_counts[transition] += 1
            if transition == "cleared" and self.first_clearing_write is None:
                self.first_clearing_write = sample
            if len(self.write_samples) < self.sample_limit // 2:
                self.write_samples.append(sample)
            self.latest_write_samples.append(sample)

    def summary(self) -> dict[str, Any]:
        if not self.enabled:
            status = "disabled"
        elif self.argument_memory_divergence_count:
            status = "native_read_divergence"
        elif self.runtime_source_divergence_count:
            status = "runtime_record_corruption"
        elif self.scene_draw_count and self.passed_zero_count:
            status = "zero_indices_unattributed"
        elif self.scene_draw_count:
            status = "records_healthy"
        else:
            status = "waiting_for_scene"
        write_samples = [
            *self.write_samples,
            *(
                sample
                for sample in self.latest_write_samples
                if sample not in self.write_samples
            ),
        ]
        return {
            "enabled": self.enabled,
            "status": status,
            "execution_mode": "downstream_observer_only_recovered_guest_code",
            "observer_addresses_hex": [
                _hex32(address) for address in sorted(self.observer_addresses)
            ],
            "source_catalog": {
                "layout_count": len(self.source_layouts),
                "error_count": len(self.source_errors),
                "errors": list(self.source_errors),
                "watched_field_count": len(self.watched_field_addresses),
            },
            "complete": self.complete,
            "complete_reason": self.complete_reason,
            "first_scene_flip": self.first_scene_flip,
            "completed_scene_flip": self.completed_scene_flip,
            "scene_draw_count": self.scene_draw_count,
            "passed_zero_count": self.passed_zero_count,
            "authoritative_zero_count": self.authoritative_zero_count,
            "argument_memory_divergence_count": (
                self.argument_memory_divergence_count
            ),
            "runtime_source_divergence_count": (
                self.runtime_source_divergence_count
            ),
            "status_counts": dict(self.status_counts.most_common()),
            "matching_source_counts": dict(self.source_match_counts.most_common()),
            "record_observation_counts": [
                {
                    "record_address_hex": _hex32(address),
                    "observation_count": count,
                }
                for address, count in self.record_observation_counts.most_common()
            ],
            "record_samples": self.record_samples,
            "write_audit": {
                "write_count": self.write_count,
                "source_counts": dict(self.write_source_counts.most_common()),
                "transition_counts": dict(
                    self.write_transition_counts.most_common()
                ),
                "first_clearing_write": self.first_clearing_write,
                "samples": write_samples,
            },
        }


class TitleD3DFlushFastPath:
    """Fast-path the observed D3D push-buffer flush/progress helper."""

    def __init__(self, *, flush_address: int = TITLE_D3D_FLUSH_ADDRESS) -> None:
        self.flush_address = flush_address
        self.invocation_count = 0
        self.progress_update_count = 0
        self.last_context_address: int | None = None
        self.last_progress_value: int | None = None

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.flush_address: self.flush_handler}

    def flush_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        context_address = cpu.get_register("ecx")
        current_push_address = memory.read_u32(context_address) if context_address else 0
        progress_value = current_push_address & TITLE_GPU_COMPLETION_MASK
        dma_state_address = (
            memory.read_u32(_u32(context_address + 0x17F4))
            if context_address
            else 0
        )
        if dma_state_address:
            memory.write_u32(_u32(dma_state_address + 0x40), progress_value)
            self.progress_update_count += 1

        cpu.set_register("eax", 0)
        cpu.set_register("ecx", context_address)
        self.invocation_count += 1
        self.last_context_address = context_address
        self.last_progress_value = progress_value
        trace.add(
            target,
            "title_d3d_flush_fast_path",
            invocation_count=self.invocation_count,
            context_address=context_address,
            context_address_hex=_hex32(context_address),
            current_push_address=current_push_address,
            current_push_address_hex=_hex32(current_push_address),
            progress_value=progress_value,
            progress_value_hex=_hex32(progress_value),
            dma_state_address=dma_state_address,
            dma_state_address_hex=_hex32(dma_state_address),
        )

    def summary(self) -> dict[str, Any]:
        return {
            "flush_address": self.flush_address,
            "flush_address_hex": _hex32(self.flush_address),
            "invocation_count": self.invocation_count,
            "progress_update_count": self.progress_update_count,
            "last_context_address_hex": _hex32(self.last_context_address or 0)
            if self.last_context_address is not None
            else None,
            "last_progress_value_hex": _hex32(self.last_progress_value or 0)
            if self.last_progress_value is not None
            else None,
        }


def _emit_title_d3d_marker_packet(
    memory: SparseMemory,
    *,
    context_address: int,
    packet_size: int,
) -> dict[str, Any]:
    packet_address = memory.read_u32(context_address) if context_address else 0
    packet_end_address = (
        memory.read_u32(_u32(context_address + 4)) if context_address else 0
    )
    ring_base = (
        memory.read_u32(_u32(context_address + 0x24)) if context_address else 0
    )
    put_value = (
        memory.read_u32(_u32(context_address + 0x2C)) if context_address else 0
    )

    wrapped = False
    if (
        not packet_address
        or not packet_end_address
        or _u32(packet_address + packet_size) > packet_end_address
    ):
        packet_address = ring_base or TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS
        wrapped = True

    memory.write_u32(packet_address, 0x00041D70)
    memory.write_u32(_u32(packet_address + 0x04), put_value)
    memory.write_u32(_u32(packet_address + 0x08), 0x00041D90)
    memory.write_u32(_u32(packet_address + 0x0C), 0)
    memory.write_u32(_u32(packet_address + 0x10), 0x00041D90)
    memory.write_u32(_u32(packet_address + 0x14), 0)
    if context_address:
        memory.write_u32(
            _u32(context_address + 0x00),
            _u32(packet_address + packet_size),
        )
        memory.write_u32(_u32(context_address + 0x2C), _u32(put_value + 2))

    return {
        "packet_address": packet_address,
        "put_value": put_value,
        "wrapped": wrapped,
    }


class TitleD3DPacketAllocFastPath:
    """Fast-path the observed D3D packet allocation/emission helper."""

    def __init__(
        self,
        *,
        allocation_address: int = TITLE_D3D_PACKET_ALLOC_ADDRESS,
        packet_size: int = TITLE_D3D_PACKET_ALLOC_SIZE,
    ) -> None:
        self.allocation_address = allocation_address
        self.packet_size = packet_size
        self.invocation_count = 0
        self.wrap_count = 0
        self.flush_requested_count = 0
        self.last_context_address: int | None = None
        self.last_packet_address: int | None = None
        self.last_put_value: int | None = None

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.allocation_address: self.allocation_handler}

    def allocation_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        flags = memory.read_u32(_u32(esp + 4))
        context_address = memory.read_u32(TITLE_D3D_CONTEXT_GLOBAL_ADDRESS)
        packet = _emit_title_d3d_marker_packet(
            memory,
            context_address=context_address,
            packet_size=self.packet_size,
        )
        packet_address = int(packet["packet_address"])
        put_value = int(packet["put_value"])
        wrapped = bool(packet["wrapped"])
        if wrapped:
            self.wrap_count += 1
        if (flags & 0x2) == 0 and context_address:
            get_pointer_address = memory.read_u32(_u32(context_address + 0x30))
            if get_pointer_address:
                # Bit 0x2 skips the title's nested flush call. When the bit is
                # clear, the native title waits on this GET counter after the
                # marker is submitted. With no asynchronous NV2A command
                # processor, completing only the DMA status word leaves the
                # guest parked forever in the 0x0021B180 fence loop.
                memory.write_u32(get_pointer_address, put_value)
            dma_state_address = memory.read_u32(_u32(context_address + 0x17F4))
            if dma_state_address:
                memory.write_u32(
                    _u32(dma_state_address + 0x40),
                    put_value & TITLE_GPU_COMPLETION_MASK,
                )
            self.flush_requested_count += 1

        cpu.set_register("eax", put_value)
        _prepare_stdcall_return(cpu, memory, 4)
        self.invocation_count += 1
        self.last_context_address = context_address
        self.last_packet_address = packet_address
        self.last_put_value = put_value
        trace.add(
            target,
            "title_d3d_packet_alloc_fast_path",
            invocation_count=self.invocation_count,
            context_address=context_address,
            context_address_hex=_hex32(context_address),
            packet_address=packet_address,
            packet_address_hex=_hex32(packet_address),
            put_value=put_value,
            put_value_hex=_hex32(put_value),
            flags=flags,
            flags_hex=_hex32(flags),
            wrapped=wrapped,
        )

    def summary(self) -> dict[str, Any]:
        return {
            "allocation_address": self.allocation_address,
            "allocation_address_hex": _hex32(self.allocation_address),
            "packet_size": self.packet_size,
            "invocation_count": self.invocation_count,
            "wrap_count": self.wrap_count,
            "flush_requested_count": self.flush_requested_count,
            "last_context_address_hex": _hex32(self.last_context_address or 0)
            if self.last_context_address is not None
            else None,
            "last_packet_address_hex": _hex32(self.last_packet_address or 0)
            if self.last_packet_address is not None
            else None,
            "last_put_value_hex": _hex32(self.last_put_value or 0)
            if self.last_put_value is not None
            else None,
        }


class TitleD3DReserveFastPath:
    """Fast-path the observed D3D push-buffer reserve helper."""

    def __init__(
        self,
        *,
        reserve_address: int = TITLE_D3D_RESERVE_ADDRESS,
        packet_size: int = TITLE_D3D_PACKET_ALLOC_SIZE,
    ) -> None:
        self.reserve_address = reserve_address
        self.packet_size = packet_size
        self.invocation_count = 0
        self.limit_update_count = 0
        self.marker_packet_count = 0
        self.wrap_count = 0
        self.flush_progress_update_count = 0
        self.last_context_address: int | None = None
        self.last_reserved_start_address: int | None = None
        self.last_reserved_limit_address: int | None = None
        self.last_return_address: int | None = None

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.reserve_address: self.reserve_handler}

    def reserve_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        half_reserve_bytes = memory.read_u32(_u32(esp + 4))
        full_reserve_bytes = memory.read_u32(_u32(esp + 8))
        context_address = memory.read_u32(TITLE_D3D_CONTEXT_GLOBAL_ADDRESS)
        current_address = memory.read_u32(context_address) if context_address else 0
        ring_base = (
            memory.read_u32(_u32(context_address + 0x24)) if context_address else 0
        )
        ring_end = (
            memory.read_u32(_u32(context_address + 0x28)) if context_address else 0
        )
        if not ring_base:
            ring_base = TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS
        if not ring_end:
            ring_end = TITLE_D3D_PUSH_BUFFER_END_ADDRESS

        reserved_start = current_address or ring_base
        wrapped = False
        if reserved_start < ring_base or reserved_start >= ring_end:
            reserved_start = ring_base
            wrapped = True

        guarded_end = _u32(
            reserved_start + full_reserve_bytes + TITLE_D3D_RESERVE_GUARD_BYTES
        )
        if guarded_end > ring_end:
            half_end = _u32(reserved_start + half_reserve_bytes)
            if half_end > ring_end:
                reserved_start = ring_base
                reserved_end = min(
                    _u32(reserved_start + full_reserve_bytes),
                    ring_end,
                )
                wrapped = True
            else:
                reserved_end = ring_end
        else:
            reserved_end = _u32(reserved_start + full_reserve_bytes)
            if reserved_end > ring_end:
                reserved_end = ring_end

        limit_address = reserved_end
        if limit_address > _u32(reserved_start + TITLE_D3D_RESERVE_LIMIT_MARGIN):
            limit_address = _u32(limit_address - TITLE_D3D_RESERVE_LIMIT_MARGIN)
        minimum_limit = _u32(reserved_start + self.packet_size)
        if limit_address < minimum_limit:
            limit_address = min(minimum_limit, ring_end)

        if context_address:
            memory.write_u32(_u32(context_address + 0x00), reserved_start)
            memory.write_u32(_u32(context_address + 0x04), limit_address)
            get_pointer_address = memory.read_u32(_u32(context_address + 0x30))
            put_value = memory.read_u32(_u32(context_address + 0x2C))
            if get_pointer_address:
                memory.write_u32(get_pointer_address, put_value)
            self.limit_update_count += 1

        packet = _emit_title_d3d_marker_packet(
            memory,
            context_address=context_address,
            packet_size=self.packet_size,
        )
        packet_address = int(packet["packet_address"])
        packet_wrapped = bool(packet["wrapped"])
        if packet_wrapped and not wrapped:
            wrapped = True
        if wrapped:
            self.wrap_count += 1
        self.marker_packet_count += 1

        return_address = (
            memory.read_u32(context_address) if context_address else packet_address
        )
        if context_address:
            memory.write_u32(TITLE_GPU_SUBMISSION_BASE_ADDRESS, return_address)
            memory.write_u32(TITLE_GPU_SUBMISSION_LIMIT_ADDRESS, limit_address)
        if context_address:
            dma_state_address = memory.read_u32(_u32(context_address + 0x17F4))
            if dma_state_address:
                memory.write_u32(
                    _u32(dma_state_address + 0x40),
                    return_address & TITLE_GPU_COMPLETION_MASK,
                )
                self.flush_progress_update_count += 1

        cpu.set_register("eax", return_address)
        _prepare_stdcall_return(cpu, memory, TITLE_D3D_RESERVE_STACK_CLEANUP)
        self.invocation_count += 1
        self.last_context_address = context_address
        self.last_reserved_start_address = reserved_start
        self.last_reserved_limit_address = limit_address
        self.last_return_address = return_address
        trace.add(
            target,
            "title_d3d_reserve_fast_path",
            invocation_count=self.invocation_count,
            context_address=context_address,
            context_address_hex=_hex32(context_address),
            current_address=current_address,
            current_address_hex=_hex32(current_address),
            half_reserve_bytes=half_reserve_bytes,
            full_reserve_bytes=full_reserve_bytes,
            reserved_start_address=reserved_start,
            reserved_start_address_hex=_hex32(reserved_start),
            reserved_limit_address=limit_address,
            reserved_limit_address_hex=_hex32(limit_address),
            return_address=return_address,
            return_address_hex=_hex32(return_address),
            packet_address=packet_address,
            packet_address_hex=_hex32(packet_address),
            wrapped=wrapped,
        )

    def summary(self) -> dict[str, Any]:
        return {
            "reserve_address": self.reserve_address,
            "reserve_address_hex": _hex32(self.reserve_address),
            "packet_size": self.packet_size,
            "invocation_count": self.invocation_count,
            "limit_update_count": self.limit_update_count,
            "marker_packet_count": self.marker_packet_count,
            "wrap_count": self.wrap_count,
            "flush_progress_update_count": self.flush_progress_update_count,
            "last_context_address_hex": _hex32(self.last_context_address or 0)
            if self.last_context_address is not None
            else None,
            "last_reserved_start_address_hex": _hex32(
                self.last_reserved_start_address or 0
            )
            if self.last_reserved_start_address is not None
            else None,
            "last_reserved_limit_address_hex": _hex32(
                self.last_reserved_limit_address or 0
            )
            if self.last_reserved_limit_address is not None
            else None,
            "last_return_address_hex": _hex32(self.last_return_address or 0)
            if self.last_return_address is not None
            else None,
        }


class TitleD3DPrimitiveDrawFastPath:
    """Audit the recovered D3D Clear entry; retain the legacy schema name."""

    def __init__(
        self,
        *,
        draw_address: int = TITLE_D3D_PRIMITIVE_DRAW_ADDRESS,
        stack_cleanup: int = TITLE_D3D_PRIMITIVE_DRAW_STACK_CLEANUP,
        argument_count: int = TITLE_D3D_PRIMITIVE_DRAW_ARGUMENT_COUNT,
        sample_limit: int = TITLE_D3D_PRIMITIVE_DRAW_SAMPLE_LIMIT,
        render_watchpoint: RenderWriteWatchpoint | None = None,
        execute_fast_path: bool = False,
    ) -> None:
        self.draw_address = draw_address
        self.stack_cleanup = stack_cleanup
        self.argument_count = argument_count
        self.sample_limit = sample_limit
        self.render_watchpoint = render_watchpoint
        self.execute_fast_path = execute_fast_path
        self.invocation_count = 0
        self.last_arguments: tuple[int, ...] = ()
        self.last_context_address: int | None = None
        self.last_put_address: int | None = None
        self.sampled_invocations: list[dict[str, Any]] = []
        self.latest_invocations: deque[dict[str, Any]] = deque(maxlen=sample_limit)
        self.caller_return_counts: Counter[int] = Counter()

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.draw_address: self.draw_handler} if self.execute_fast_path else {}

    @property
    def observer_addresses(self) -> set[int]:
        return {self.draw_address} if not self.execute_fast_path else set()

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        _steps: int,
    ) -> None:
        if self.execute_fast_path or cpu.eip != self.draw_address:
            return
        self._record_invocation(cpu, memory, self.draw_address, trace, mutate=False)

    def draw_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        self._record_invocation(cpu, memory, target, trace, mutate=True)

    def _record_invocation(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
        *,
        mutate: bool,
    ) -> None:
        esp = cpu.get_register("esp")
        caller_return_address = memory.read_u32(esp)
        arguments = tuple(
            memory.read_u32(_u32(esp + 4 + index * 4))
            for index in range(self.argument_count)
        )
        context_address = memory.read_u32(TITLE_D3D_CONTEXT_GLOBAL_ADDRESS)
        put_address = memory.read_u32(context_address) if context_address else 0

        if mutate:
            cpu.set_register("eax", put_address)
            _prepare_stdcall_return(cpu, memory, self.stack_cleanup)
        self.invocation_count += 1
        self.last_arguments = arguments
        self.last_context_address = context_address
        self.last_put_address = put_address
        self.caller_return_counts[caller_return_address] += 1
        sample = {
            "invocation_count": self.invocation_count,
            "arguments": [_hex32(argument) for argument in arguments],
            "context_address_hex": _hex32(context_address),
            "put_address_hex": _hex32(put_address),
            "caller_return_address_hex": _hex32(caller_return_address),
            "render_write_count": (
                self.render_watchpoint.write_count
                if self.render_watchpoint is not None
                else None
            ),
            "guest_flip_count": (
                self.render_watchpoint.flip_count
                if self.render_watchpoint is not None
                else None
            ),
        }
        if len(self.sampled_invocations) < self.sample_limit:
            self.sampled_invocations.append(sample)
        self.latest_invocations.append(sample)
        if trace.enabled:
            trace.add(
                target,
                (
                    "title_d3d_primitive_draw_fast_path"
                    if mutate
                    else "title_d3d_primitive_draw_recovered_entry"
                ),
                invocation_count=self.invocation_count,
                arguments=sample["arguments"],
                context_address=context_address,
                context_address_hex=sample["context_address_hex"],
                put_address=put_address,
                put_address_hex=sample["put_address_hex"],
                caller_return_address=caller_return_address,
                caller_return_address_hex=sample["caller_return_address_hex"],
                render_write_count=sample["render_write_count"],
                guest_flip_count=sample["guest_flip_count"],
                stack_cleanup=self.stack_cleanup,
            )

    def summary(self) -> dict[str, Any]:
        samples_by_invocation = {
            int(sample["invocation_count"]): sample
            for sample in [*self.sampled_invocations, *self.latest_invocations]
        }
        return {
            "draw_address": self.draw_address,
            "draw_address_hex": _hex32(self.draw_address),
            "stack_cleanup": self.stack_cleanup,
            "argument_count": self.argument_count,
            "execution_mode": (
                "return_only_fast_path"
                if self.execute_fast_path
                else "recovered_guest_code"
            ),
            "operation": "clear",
            "invocation_count": self.invocation_count,
            "last_context_address_hex": _hex32(self.last_context_address or 0)
            if self.last_context_address is not None
            else None,
            "last_put_address_hex": _hex32(self.last_put_address or 0)
            if self.last_put_address is not None
            else None,
            "last_arguments": [_hex32(argument) for argument in self.last_arguments],
            "sampled_invocations": [
                sample for _, sample in sorted(samples_by_invocation.items())
            ],
            "caller_return_counts": [
                {
                    "caller_return_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in self.caller_return_counts.most_common()
            ],
        }


class TitleImmediateDrawAudit:
    """Observe immediate-array draw submissions without changing guest execution."""

    def __init__(
        self,
        *,
        draw_address: int = TITLE_IMMEDIATE_DRAW_ADDRESS,
        sample_limit: int = TITLE_IMMEDIATE_DRAW_SAMPLE_LIMIT,
        max_vertices: int = TITLE_IMMEDIATE_DRAW_MAX_VERTICES,
        render_watchpoint: RenderWriteWatchpoint | None = None,
    ) -> None:
        self.draw_address = draw_address
        self.sample_limit = max(2, sample_limit)
        self.max_vertices = max_vertices
        self.render_watchpoint = render_watchpoint
        self.invocation_count = 0
        self.invalid_submission_count = 0
        self.caller_return_counts: Counter[int] = Counter()
        self.first_invocations: list[dict[str, Any]] = []
        self.latest_invocations: deque[dict[str, Any]] = deque(
            maxlen=self.sample_limit // 2
        )
        self.flip_geometry_stats: dict[int, dict[str, Any]] = {}
        self.batch_flush_count = 0
        self.suppressed_batch_flush_count = 0
        self.suppressed_batch_vertex_count = 0
        self.batch_flush_caller_counts: Counter[int] = Counter()
        self.suppressed_batch_flush_caller_counts: Counter[int] = Counter()
        self.latest_batch_flushes: deque[dict[str, Any]] = deque(maxlen=64)
        self.latest_suppressed_batch_flushes: deque[dict[str, Any]] = deque(
            maxlen=64
        )
        self.clip_update_count = 0
        self.empty_clip_update_count = 0
        self.clip_update_caller_counts: Counter[int] = Counter()
        self.empty_clip_update_caller_counts: Counter[int] = Counter()
        self.latest_clip_updates: deque[dict[str, Any]] = deque(maxlen=64)
        self.latest_empty_clip_updates: deque[dict[str, Any]] = deque(maxlen=64)
        self.plugin_open_attempts: list[dict[str, Any]] = []
        self.pending_plugin_open_attempts: list[dict[str, Any]] = []
        self.render_module_open_count = 0
        self.d3d_create_device_results: list[dict[str, Any]] = []

    @property
    def observer_addresses(self) -> set[int]:
        return {
            self.draw_address,
            TITLE_QUAD_BATCH_FLUSH_ADDRESS,
            TITLE_QUAD_CLIP_UPDATE_ADDRESS,
            TITLE_QUAD_CLIP_NONEMPTY_ADDRESS,
            TITLE_QUAD_CLIP_EMPTY_ADDRESS,
            TITLE_ENGINE_PLUGIN_OPEN_CALL_ADDRESS,
            TITLE_ENGINE_PLUGIN_OPEN_RETURN_ADDRESS,
            TITLE_RENDER_MODULE_OPEN_ADDRESS,
            TITLE_D3D_CREATE_DEVICE_RETURN_ADDRESS,
        }

    def observer(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        trace: ExecutionTrace,
        _steps: int,
    ) -> None:
        if cpu.eip == TITLE_ENGINE_PLUGIN_OPEN_CALL_ADDRESS:
            self._record_plugin_open_call(cpu, memory)
            return
        if cpu.eip == TITLE_ENGINE_PLUGIN_OPEN_RETURN_ADDRESS:
            self._record_plugin_open_return(cpu)
            return
        if cpu.eip == TITLE_RENDER_MODULE_OPEN_ADDRESS:
            self.render_module_open_count += 1
            return
        if cpu.eip == TITLE_D3D_CREATE_DEVICE_RETURN_ADDRESS:
            self.d3d_create_device_results.append(
                {
                    "result": cpu.get_register("eax"),
                    "result_hex": _hex32(cpu.get_register("eax")),
                    "width": memory.read_u32(0x005A66F0),
                    "height": memory.read_u32(0x005A66F4),
                    "back_buffer_count": memory.read_u32(0x005A66FC),
                }
            )
            return
        if cpu.eip == TITLE_QUAD_CLIP_UPDATE_ADDRESS:
            self._record_clip_update(cpu, memory)
            return
        if cpu.eip in {
            TITLE_QUAD_CLIP_NONEMPTY_ADDRESS,
            TITLE_QUAD_CLIP_EMPTY_ADDRESS,
        }:
            self._record_clip_decision(cpu.eip == TITLE_QUAD_CLIP_EMPTY_ADDRESS)
            return
        if cpu.eip == TITLE_QUAD_BATCH_FLUSH_ADDRESS:
            self._record_batch_flush(cpu, memory)
            return
        if cpu.eip != self.draw_address:
            return
        esp = cpu.get_register("esp")
        caller_return_address = memory.read_u32(esp)
        primitive_type = memory.read_u32(_u32(esp + 4))
        vertex_count = memory.read_u32(_u32(esp + 8))
        vertex_data_address = memory.read_u32(_u32(esp + 12))
        stride = memory.read_u32(_u32(esp + 16))
        guest_flip_count = (
            self.render_watchpoint.flip_count
            if self.render_watchpoint is not None
            else None
        )
        render_write_count = (
            self.render_watchpoint.write_count
            if self.render_watchpoint is not None
            else None
        )
        invalid_reason = None
        if vertex_count == 0:
            invalid_reason = "zero_vertex_count"
        elif vertex_count > self.max_vertices:
            invalid_reason = "vertex_count_exceeds_audit_limit"
        elif vertex_data_address == 0:
            invalid_reason = "null_vertex_data"
        elif stride < 8 or stride > 0x400:
            invalid_reason = "invalid_vertex_stride"

        finite_vertex_count = 0
        non_finite_vertex_count = 0
        min_x: float | None = None
        max_x: float | None = None
        min_y: float | None = None
        max_y: float | None = None
        if invalid_reason is None:
            for vertex_index in range(vertex_count):
                address = _u32(vertex_data_address + vertex_index * stride)
                x = struct.unpack("<f", struct.pack("<I", memory.read_u32(address)))[0]
                y = struct.unpack(
                    "<f", struct.pack("<I", memory.read_u32(_u32(address + 4)))
                )[0]
                if not math.isfinite(x) or not math.isfinite(y):
                    non_finite_vertex_count += 1
                    continue
                finite_vertex_count += 1
                min_x = x if min_x is None else min(min_x, x)
                max_x = x if max_x is None else max(max_x, x)
                min_y = y if min_y is None else min(min_y, y)
                max_y = y if max_y is None else max(max_y, y)

        self.invocation_count += 1
        self.caller_return_counts[caller_return_address] += 1
        if invalid_reason is not None:
            self.invalid_submission_count += 1
        sample = {
            "invocation_count": self.invocation_count,
            "caller_return_address_hex": _hex32(caller_return_address),
            "primitive_type": primitive_type,
            "vertex_count": vertex_count,
            "vertex_data_address_hex": _hex32(vertex_data_address),
            "stride": stride,
            "finite_vertex_count": finite_vertex_count,
            "non_finite_vertex_count": non_finite_vertex_count,
            "min_x": min_x,
            "max_x": max_x,
            "min_y": min_y,
            "max_y": max_y,
            "invalid_reason": invalid_reason,
            "render_write_count": render_write_count,
            "guest_flip_count": guest_flip_count,
        }
        if len(self.first_invocations) < self.sample_limit // 2:
            self.first_invocations.append(sample)
        self.latest_invocations.append(sample)

        if guest_flip_count is not None:
            flip = self.flip_geometry_stats.setdefault(
                guest_flip_count,
                {
                    "guest_flip_count": guest_flip_count,
                    "draw_call_count": 0,
                    "vertex_count": 0,
                    "finite_vertex_count": 0,
                    "non_finite_vertex_count": 0,
                    "invalid_submission_count": 0,
                    "primitive_type_counts": Counter(),
                    "min_x": None,
                    "max_x": None,
                    "min_y": None,
                    "max_y": None,
                },
            )
            flip["draw_call_count"] += 1
            flip["vertex_count"] += vertex_count
            flip["finite_vertex_count"] += finite_vertex_count
            flip["non_finite_vertex_count"] += non_finite_vertex_count
            flip["primitive_type_counts"][primitive_type] += 1
            if invalid_reason is not None:
                flip["invalid_submission_count"] += 1
            for key, value, reducer in (
                ("min_x", min_x, min),
                ("max_x", max_x, max),
                ("min_y", min_y, min),
                ("max_y", max_y, max),
            ):
                if value is not None:
                    flip[key] = value if flip[key] is None else reducer(flip[key], value)

        if trace.enabled:
            trace.add(
                self.draw_address,
                "title_immediate_draw_submission",
                **sample,
            )

    def _record_plugin_open_call(
        self,
        cpu: CpuState,
        memory: SparseMemory,
    ) -> None:
        node_address = cpu.get_register("esi")
        callback_address = memory.read_u32(_u32(node_address + 0x20))
        sample = {
            "node_address_hex": _hex32(node_address),
            "plugin_id_hex": _hex32(memory.read_u32(node_address)),
            "plugin_offset": memory.read_u32(_u32(node_address + 4)),
            "callback_address_hex": _hex32(callback_address),
            "result": None,
            "result_hex": None,
        }
        self.plugin_open_attempts.append(sample)
        self.pending_plugin_open_attempts.append(sample)

    def _record_plugin_open_return(self, cpu: CpuState) -> None:
        if not self.pending_plugin_open_attempts:
            return
        sample = self.pending_plugin_open_attempts.pop()
        result = cpu.get_register("eax")
        sample["result"] = result
        sample["result_hex"] = _hex32(result)

    def _record_batch_flush(
        self,
        cpu: CpuState,
        memory: SparseMemory,
    ) -> None:
        object_address = cpu.get_register("ecx")
        esp = cpu.get_register("esp")
        caller_return_address = memory.read_u32(esp)
        vertex_count = memory.read_u32(
            _u32(object_address + TITLE_VERTEX_APPEND_COUNT_OFFSET)
        )
        batch_mode = memory.read_u32(
            _u32(object_address + TITLE_QUAD_BATCH_MODE_OFFSET)
        )
        finite_vertex_count = 0
        min_x: float | None = None
        max_x: float | None = None
        min_y: float | None = None
        max_y: float | None = None
        if vertex_count <= 0x100:
            for vertex_index in range(vertex_count):
                address = _u32(
                    object_address + vertex_index * TITLE_VERTEX_APPEND_STRIDE
                )
                x = struct.unpack(
                    "<f", struct.pack("<I", memory.read_u32(address))
                )[0]
                y = struct.unpack(
                    "<f", struct.pack("<I", memory.read_u32(_u32(address + 4)))
                )[0]
                if not math.isfinite(x) or not math.isfinite(y):
                    continue
                finite_vertex_count += 1
                min_x = x if min_x is None else min(min_x, x)
                max_x = x if max_x is None else max(max_x, x)
                min_y = y if min_y is None else min(min_y, y)
                max_y = y if max_y is None else max(max_y, y)
        suppressed = batch_mode == 2
        sample = {
            "invocation_count": self.batch_flush_count + 1,
            "caller_return_address_hex": _hex32(caller_return_address),
            "object_address_hex": _hex32(object_address),
            "batch_mode": batch_mode,
            "suppressed": suppressed,
            "texture_address_hex": _hex32(
                memory.read_u32(TITLE_QUAD_BATCH_TEXTURE_ADDRESS)
            ),
            "vertex_count": vertex_count,
            "finite_vertex_count": finite_vertex_count,
            "min_x": min_x,
            "max_x": max_x,
            "min_y": min_y,
            "max_y": max_y,
            "render_write_count": (
                self.render_watchpoint.write_count
                if self.render_watchpoint is not None
                else None
            ),
            "guest_flip_count": (
                self.render_watchpoint.flip_count
                if self.render_watchpoint is not None
                else None
            ),
        }
        self.batch_flush_count += 1
        self.batch_flush_caller_counts[caller_return_address] += 1
        self.latest_batch_flushes.append(sample)
        if suppressed:
            self.suppressed_batch_flush_count += 1
            self.suppressed_batch_vertex_count += vertex_count
            self.suppressed_batch_flush_caller_counts[caller_return_address] += 1
            self.latest_suppressed_batch_flushes.append(sample)

    def _record_clip_update(
        self,
        cpu: CpuState,
        memory: SparseMemory,
    ) -> None:
        esp = cpu.get_register("esp")
        caller_return_address = memory.read_u32(esp)
        argument_bits = [
            memory.read_u32(_u32(esp + 4 + index * 4)) for index in range(4)
        ]
        arguments = [
            struct.unpack("<f", struct.pack("<I", value))[0]
            for value in argument_bits
        ]
        surface_owner = memory.read_u32(TITLE_QUAD_CLIP_SURFACE_OWNER_ADDRESS)
        surface = (
            memory.read_u32(_u32(surface_owner + 0x60)) if surface_owner else 0
        )
        sample = {
            "invocation_count": self.clip_update_count + 1,
            "caller_return_address_hex": _hex32(caller_return_address),
            "arguments": arguments,
            "argument_bits_hex": [_hex32(value) for value in argument_bits],
            "surface_owner_address_hex": _hex32(surface_owner),
            "surface_address_hex": _hex32(surface),
            "surface_width": memory.read_u32(_u32(surface + 0x0C)) if surface else 0,
            "surface_height": memory.read_u32(_u32(surface + 0x10)) if surface else 0,
            "batch_mode_before": memory.read_u32(
                _u32(TITLE_VERTEX_APPEND_OBJECT_ADDRESS + TITLE_QUAD_BATCH_MODE_OFFSET)
            ),
            "decision": None,
            "guest_flip_count": (
                self.render_watchpoint.flip_count
                if self.render_watchpoint is not None
                else None
            ),
        }
        self.clip_update_count += 1
        self.clip_update_caller_counts[caller_return_address] += 1
        self.latest_clip_updates.append(sample)

    def _record_clip_decision(self, empty: bool) -> None:
        if not self.latest_clip_updates:
            return
        sample = self.latest_clip_updates[-1]
        if sample["decision"] is not None:
            return
        sample["decision"] = "empty" if empty else "nonempty"
        if empty:
            self.empty_clip_update_count += 1
            caller_return_address = int(
                str(sample["caller_return_address_hex"]), 16
            )
            self.empty_clip_update_caller_counts[caller_return_address] += 1
            self.latest_empty_clip_updates.append(dict(sample))

    def summary(self) -> dict[str, Any]:
        samples_by_invocation = {
            int(sample["invocation_count"]): sample
            for sample in [*self.first_invocations, *self.latest_invocations]
        }
        geometry_by_guest_flip = []
        for flip_count, stats in sorted(self.flip_geometry_stats.items()):
            geometry_by_guest_flip.append(
                {
                    **{
                        key: value
                        for key, value in stats.items()
                        if key != "primitive_type_counts"
                    },
                    "primitive_type_counts": [
                        {
                            "primitive_type": primitive_type,
                            "draw_call_count": count,
                        }
                        for primitive_type, count in stats[
                            "primitive_type_counts"
                        ].most_common()
                    ],
                }
            )
        return {
            "draw_address": self.draw_address,
            "draw_address_hex": _hex32(self.draw_address),
            "execution_mode": "observer_only_recovered_guest_code",
            "argument_count": TITLE_IMMEDIATE_DRAW_ARGUMENT_COUNT,
            "max_vertices_per_submission": self.max_vertices,
            "invocation_count": self.invocation_count,
            "invalid_submission_count": self.invalid_submission_count,
            "caller_return_counts": [
                {
                    "caller_return_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in self.caller_return_counts.most_common()
            ],
            "sampled_invocations": [
                sample for _, sample in sorted(samples_by_invocation.items())
            ],
            "geometry_by_guest_flip": geometry_by_guest_flip,
            "batch_flush_count": self.batch_flush_count,
            "batch_flush_caller_counts": [
                {
                    "caller_return_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in self.batch_flush_caller_counts.most_common()
            ],
            "suppressed_batch_flush_count": self.suppressed_batch_flush_count,
            "suppressed_batch_vertex_count": self.suppressed_batch_vertex_count,
            "suppressed_batch_flush_caller_counts": [
                {
                    "caller_return_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in self.suppressed_batch_flush_caller_counts.most_common()
            ],
            "latest_batch_flushes": list(self.latest_batch_flushes),
            "latest_suppressed_batch_flushes": list(
                self.latest_suppressed_batch_flushes
            ),
            "clip_update_count": self.clip_update_count,
            "empty_clip_update_count": self.empty_clip_update_count,
            "clip_update_caller_counts": [
                {
                    "caller_return_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in self.clip_update_caller_counts.most_common()
            ],
            "empty_clip_update_caller_counts": [
                {
                    "caller_return_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in self.empty_clip_update_caller_counts.most_common()
            ],
            "latest_clip_updates": list(self.latest_clip_updates),
            "latest_empty_clip_updates": list(self.latest_empty_clip_updates),
            "plugin_open_attempts": self.plugin_open_attempts,
            "render_module_open_count": self.render_module_open_count,
            "d3d_create_device_results": self.d3d_create_device_results,
        }


class TitleVertexAppendFastPath:
    """Fast-path the observed immediate vertex-list append helper."""

    def __init__(
        self,
        *,
        append_address: int = TITLE_VERTEX_APPEND_ADDRESS,
        count_offset: int = TITLE_VERTEX_APPEND_COUNT_OFFSET,
        default_z_offset: int = TITLE_VERTEX_APPEND_DEFAULT_Z_OFFSET,
        stride: int = TITLE_VERTEX_APPEND_STRIDE,
        render_watchpoint: RenderWriteWatchpoint | None = None,
        anomaly_sample_limit: int = TITLE_VERTEX_APPEND_ANOMALY_SAMPLE_LIMIT,
    ) -> None:
        self.append_address = append_address
        self.count_offset = count_offset
        self.default_z_offset = default_z_offset
        self.stride = stride
        self.render_watchpoint = render_watchpoint
        self.anomaly_sample_limit = max(2, anomaly_sample_limit)
        self.invocation_count = 0
        self.last_object_address: int | None = None
        self.last_record_address: int | None = None
        self.last_vertex_index: int | None = None
        self.max_vertex_index = 0
        self.caller_stats: dict[int, dict[str, Any]] = {}
        self.upstream_caller_stats: dict[int, dict[str, Any]] = {}
        self.anomaly_counts: Counter[str] = Counter()
        self.first_anomaly_samples: list[dict[str, Any]] = []
        self.latest_anomaly_samples: deque[dict[str, Any]] = deque(
            maxlen=self.anomaly_sample_limit // 2
        )
        self.sampled_anomaly_flips: set[int] = set()
        self.recent_vertices: deque[tuple[Any, ...]] = deque(maxlen=8)
        self.flip_geometry_stats: dict[int, dict[str, Any]] = {}
        self.finite_min_x: float | None = None
        self.finite_max_x: float | None = None
        self.finite_min_y: float | None = None
        self.finite_max_y: float | None = None

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.append_address: self.append_handler}

    def append_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        object_address = cpu.get_register("ecx")
        esp = cpu.get_register("esp")
        caller_return_address = memory.read_u32(esp)
        upstream_return_address = (
            memory.read_u32(
                _u32(esp + TITLE_VERTEX_APPEND_QUAD_PARENT_RETURN_STACK_OFFSET)
            )
            if TITLE_QUAD_SUBMIT_ADDRESS
            <= caller_return_address
            <= TITLE_QUAD_SUBMIT_END_ADDRESS
            else 0
        )
        entry_eax = cpu.get_register("eax")
        x_bits = memory.read_u32(_u32(esp + 4))
        y_bits = memory.read_u32(_u32(esp + 8))
        color_vector_address = memory.read_u32(_u32(esp + 12))
        tail0_bits = memory.read_u32(_u32(esp + 16))
        tail1_bits = memory.read_u32(_u32(esp + 20))
        vertex_index = memory.read_u32(_u32(object_address + self.count_offset))
        record_address = _u32(object_address + vertex_index * self.stride)
        default_z_bits = memory.read_u32(_u32(object_address + self.default_z_offset))
        packed_color = _pack_title_vertex_color(memory, color_vector_address)
        x = struct.unpack("<f", struct.pack("<I", x_bits))[0]
        y = struct.unpack("<f", struct.pack("<I", y_bits))[0]
        render_write_count = (
            self.render_watchpoint.write_count
            if self.render_watchpoint is not None
            else None
        )
        guest_flip_count = (
            self.render_watchpoint.flip_count
            if self.render_watchpoint is not None
            else None
        )

        memory.write_u32(record_address, x_bits)
        memory.write_u32(_u32(record_address + 0x04), y_bits)
        memory.write_u32(_u32(record_address + 0x08), default_z_bits)
        memory.write_u32(_u32(record_address + 0x10), packed_color)
        memory.write_u32(_u32(record_address + 0x14), tail0_bits)
        memory.write_u32(_u32(record_address + 0x18), tail1_bits)
        memory.write_u32(_u32(object_address + self.count_offset), _u32(vertex_index + 1))

        cpu.set_register("eax", object_address)
        _prepare_stdcall_return(cpu, memory, TITLE_VERTEX_APPEND_STACK_CLEANUP)
        self.invocation_count += 1
        self.last_object_address = object_address
        self.last_record_address = record_address
        self.last_vertex_index = vertex_index
        self.max_vertex_index = max(self.max_vertex_index, vertex_index)
        anomalies: list[str] = []
        if not math.isfinite(x) or not math.isfinite(y):
            anomalies.append("non_finite_position")
        else:
            self.finite_min_x = x if self.finite_min_x is None else min(self.finite_min_x, x)
            self.finite_max_x = x if self.finite_max_x is None else max(self.finite_max_x, x)
            self.finite_min_y = y if self.finite_min_y is None else min(self.finite_min_y, y)
            self.finite_max_y = y if self.finite_max_y is None else max(self.finite_max_y, y)
            if x < -640.0 or x > 1280.0 or y < -480.0 or y > 960.0:
                anomalies.append("outside_reference_envelope")
        if x_bits == 0x43A00000 and (y_bits & 0x7FFFFFFF) == 0:
            anomalies.append("exact_center_origin")

        caller_stat = self._record_producer(
            self.caller_stats,
            caller_return_address,
            object_address=object_address,
            x=x,
            y=y,
            anomalies=anomalies,
            render_write_count=render_write_count,
            guest_flip_count=guest_flip_count,
        )
        if 0x00010000 <= upstream_return_address < 0x00300000:
            self._record_producer(
                self.upstream_caller_stats,
                upstream_return_address,
                object_address=object_address,
                x=x,
                y=y,
                anomalies=anomalies,
                render_write_count=render_write_count,
                guest_flip_count=guest_flip_count,
            )
        if guest_flip_count is not None:
            self._record_flip_geometry(
                guest_flip_count,
                upstream_return_address=upstream_return_address,
                x=x,
                y=y,
                anomalies=anomalies,
            )
        if anomalies:
            self.anomaly_counts.update(anomalies)

        recent_vertex = (
            self.invocation_count,
            object_address,
            record_address,
            vertex_index,
            x if math.isfinite(x) else None,
            y if math.isfinite(y) else None,
            x_bits,
            y_bits,
            caller_return_address,
            upstream_return_address,
            render_write_count,
            guest_flip_count,
        )
        self.recent_vertices.append(recent_vertex)
        if anomalies:
            anomaly_total = sum(self.anomaly_counts.values())
            should_sample = (
                len(self.first_anomaly_samples) < self.anomaly_sample_limit // 2
                or caller_stat["anomaly_count"] == 1
                or (
                    guest_flip_count is not None
                    and guest_flip_count not in self.sampled_anomaly_flips
                )
                or anomaly_total % 1024 == 0
            )
            if should_sample:
                vertex_summary = self._vertex_summary(recent_vertex)
                register_snapshot = {
                    register: _hex32(
                        entry_eax
                        if register == "eax"
                        else esp
                        if register == "esp"
                        else cpu.get_register(register)
                    )
                    for register in (
                        "eax",
                        "ebx",
                        "ecx",
                        "edx",
                        "esi",
                        "edi",
                        "ebp",
                        "esp",
                    )
                }
                sample = {
                    **vertex_summary,
                    "anomalies": anomalies,
                    "registers": register_snapshot,
                    "frame_chain": self._frame_chain(
                        memory, esp, cpu.get_register("ebp")
                    ),
                    "stack_words": self._stack_words(memory, esp),
                    "stack_code_candidates": self._stack_code_candidates(memory, esp),
                    "frontend_context": self._frontend_context(memory),
                    "vertex_object_control_words": self._memory_words(
                        memory,
                        _u32(object_address + self.count_offset - 0x20),
                        13,
                    ),
                    "recent_vertices": [
                        self._vertex_summary(vertex)
                        for vertex in self.recent_vertices
                    ],
                }
                if guest_flip_count is not None:
                    self.sampled_anomaly_flips.add(guest_flip_count)
                if len(self.first_anomaly_samples) < self.anomaly_sample_limit // 2:
                    self.first_anomaly_samples.append(sample)
                self.latest_anomaly_samples.append(sample)

        if trace.enabled:
            vertex_summary = self._vertex_summary(recent_vertex)
            trace.add(
                target,
                "title_vertex_append_fast_path",
                **vertex_summary,
                default_z_bits_hex=_hex32(default_z_bits),
                color_vector_address=color_vector_address,
                color_vector_address_hex=_hex32(color_vector_address),
                packed_color=packed_color,
                packed_color_hex=_hex32(packed_color),
                tail0_bits_hex=_hex32(tail0_bits),
                tail1_bits_hex=_hex32(tail1_bits),
                anomalies=anomalies,
            )

    @staticmethod
    def _vertex_summary(vertex: tuple[Any, ...]) -> dict[str, Any]:
        (
            invocation_count,
            object_address,
            record_address,
            vertex_index,
            x,
            y,
            x_bits,
            y_bits,
            caller_return_address,
            upstream_return_address,
            render_write_count,
            guest_flip_count,
        ) = vertex
        return {
            "invocation_count": invocation_count,
            "object_address_hex": _hex32(object_address),
            "record_address_hex": _hex32(record_address),
            "vertex_index": vertex_index,
            "x": x,
            "y": y,
            "x_bits_hex": _hex32(x_bits),
            "y_bits_hex": _hex32(y_bits),
            "caller_return_address_hex": _hex32(caller_return_address),
            "upstream_return_address_hex": _hex32(upstream_return_address)
            if upstream_return_address
            else None,
            "render_write_count": render_write_count,
            "guest_flip_count": guest_flip_count,
        }

    def _record_producer(
        self,
        stats_by_address: dict[int, dict[str, Any]],
        address: int,
        *,
        object_address: int,
        x: float,
        y: float,
        anomalies: list[str],
        render_write_count: int | None,
        guest_flip_count: int | None,
    ) -> dict[str, Any]:
        stats = stats_by_address.setdefault(
            address,
            {
                "invocation_count": 0,
                "anomaly_count": 0,
                "anomaly_counts": Counter(),
                "object_counts": Counter(),
                "min_x": None,
                "max_x": None,
                "min_y": None,
                "max_y": None,
                "first_invocation": self.invocation_count,
                "last_invocation": self.invocation_count,
                "first_render_write_count": render_write_count,
                "last_render_write_count": render_write_count,
                "first_guest_flip_count": guest_flip_count,
                "last_guest_flip_count": guest_flip_count,
            },
        )
        stats["invocation_count"] += 1
        stats["last_invocation"] = self.invocation_count
        stats["last_render_write_count"] = render_write_count
        stats["last_guest_flip_count"] = guest_flip_count
        stats["object_counts"][object_address] += 1
        if math.isfinite(x) and math.isfinite(y):
            stats["min_x"] = x if stats["min_x"] is None else min(stats["min_x"], x)
            stats["max_x"] = x if stats["max_x"] is None else max(stats["max_x"], x)
            stats["min_y"] = y if stats["min_y"] is None else min(stats["min_y"], y)
            stats["max_y"] = y if stats["max_y"] is None else max(stats["max_y"], y)
        if anomalies:
            stats["anomaly_count"] += 1
            stats["anomaly_counts"].update(anomalies)
        return stats

    def _record_flip_geometry(
        self,
        guest_flip_count: int,
        *,
        upstream_return_address: int,
        x: float,
        y: float,
        anomalies: list[str],
    ) -> None:
        if guest_flip_count not in self.flip_geometry_stats:
            if len(self.flip_geometry_stats) >= 256:
                del self.flip_geometry_stats[next(iter(self.flip_geometry_stats))]
            self.flip_geometry_stats[guest_flip_count] = {
                "vertex_count": 0,
                "anomaly_count": 0,
                "anomaly_counts": Counter(),
                "min_x": None,
                "max_x": None,
                "min_y": None,
                "max_y": None,
                "upstream_producers": {},
            }
        stats = self.flip_geometry_stats[guest_flip_count]
        stats["vertex_count"] += 1
        stats["anomaly_count"] += bool(anomalies)
        stats["anomaly_counts"].update(anomalies)
        if math.isfinite(x) and math.isfinite(y):
            stats["min_x"] = x if stats["min_x"] is None else min(stats["min_x"], x)
            stats["max_x"] = x if stats["max_x"] is None else max(stats["max_x"], x)
            stats["min_y"] = y if stats["min_y"] is None else min(stats["min_y"], y)
            stats["max_y"] = y if stats["max_y"] is None else max(stats["max_y"], y)
        if not 0x00010000 <= upstream_return_address < 0x00300000:
            return
        producer = stats["upstream_producers"].setdefault(
            upstream_return_address,
            {
                "vertex_count": 0,
                "anomaly_count": 0,
                "min_x": None,
                "max_x": None,
                "min_y": None,
                "max_y": None,
            },
        )
        producer["vertex_count"] += 1
        producer["anomaly_count"] += bool(anomalies)
        if math.isfinite(x) and math.isfinite(y):
            producer["min_x"] = x if producer["min_x"] is None else min(producer["min_x"], x)
            producer["max_x"] = x if producer["max_x"] is None else max(producer["max_x"], x)
            producer["min_y"] = y if producer["min_y"] is None else min(producer["min_y"], y)
            producer["max_y"] = y if producer["max_y"] is None else max(producer["max_y"], y)

    @staticmethod
    def _frame_chain(
        memory: SparseMemory,
        esp: int,
        frame_pointer: int,
    ) -> list[dict[str, Any]]:
        frames: list[dict[str, Any]] = []
        current = frame_pointer
        for depth in range(8):
            if current < esp or current - esp > 0x00200000 or current & 3:
                break
            parent = memory.read_u32(current)
            return_address = memory.read_u32(_u32(current + 4))
            frames.append(
                {
                    "depth": depth,
                    "frame_pointer_hex": _hex32(current),
                    "return_address_hex": _hex32(return_address),
                }
            )
            if parent <= current:
                break
            current = parent
        return frames

    @staticmethod
    def _memory_words(
        memory: SparseMemory,
        base_address: int,
        word_count: int,
    ) -> list[dict[str, Any]]:
        return [
            {
                "offset_hex": _hex32(index * 4),
                "address_hex": _hex32(_u32(base_address + index * 4)),
                "value_hex": _hex32(
                    memory.read_u32(_u32(base_address + index * 4))
                ),
            }
            for index in range(word_count)
        ]

    @classmethod
    def _stack_words(
        cls,
        memory: SparseMemory,
        esp: int,
    ) -> list[dict[str, Any]]:
        return cls._memory_words(memory, esp, TITLE_VERTEX_APPEND_STACK_SCAN_WORDS)

    @classmethod
    def _frontend_context(cls, memory: SparseMemory) -> dict[str, Any]:
        frontend_index = memory.read_u32(0x00353104)
        frontend_object_address = (
            memory.read_u32(_u32(0x00353108 + frontend_index * 4))
            if frontend_index < 0x1000
            else 0
        )
        dynamic_object_address = memory.read_u32(
            _u32(
                TITLE_FRONTEND_DYNAMIC_OBJECT_OWNER_ADDRESS
                + TITLE_FRONTEND_DYNAMIC_OBJECT_POINTER_OFFSET
            )
        )
        return {
            "frontend_index": frontend_index,
            "frontend_object_address_hex": _hex32(frontend_object_address),
            "frontend_source_text_address_hex": _hex32(
                memory.read_u32(_u32(frontend_object_address + 0x0DE4))
                if frontend_object_address
                else 0
            ),
            "frontend_object_head_words": cls._memory_words(
                memory,
                frontend_object_address,
                16,
            )
            if frontend_object_address
            else [],
            "frontend_object_render_words": cls._memory_words(
                memory,
                _u32(frontend_object_address + 0x0DD0),
                16,
            )
            if frontend_object_address
            else [],
            "dynamic_object_address_hex": _hex32(dynamic_object_address),
            "dynamic_object_head_words": cls._memory_words(
                memory,
                dynamic_object_address,
                16,
            )
            if dynamic_object_address
            else [],
        }

    @staticmethod
    def _stack_code_candidates(
        memory: SparseMemory,
        esp: int,
    ) -> list[dict[str, Any]]:
        candidates: list[dict[str, Any]] = []
        for index in range(TITLE_VERTEX_APPEND_STACK_SCAN_WORDS):
            offset = index * 4
            value = memory.read_u32(_u32(esp + offset))
            if 0x00010000 <= value < 0x00300000:
                candidates.append(
                    {
                        "stack_offset_hex": _hex32(offset),
                        "address_hex": _hex32(value),
                    }
                )
        return candidates

    def summary(self) -> dict[str, Any]:
        samples_by_invocation: dict[int, dict[str, Any]] = {}
        for sample in [*self.first_anomaly_samples, *self.latest_anomaly_samples]:
            samples_by_invocation[int(sample["invocation_count"])] = sample
        producer_callers = self._producer_summaries(
            self.caller_stats,
            address_field="caller_return_address_hex",
        )
        upstream_producers = self._producer_summaries(
            self.upstream_caller_stats,
            address_field="upstream_return_address_hex",
        )
        return {
            "append_address": self.append_address,
            "append_address_hex": _hex32(self.append_address),
            "count_offset": self.count_offset,
            "count_offset_hex": _hex32(self.count_offset),
            "default_z_offset": self.default_z_offset,
            "default_z_offset_hex": _hex32(self.default_z_offset),
            "stack_cleanup": TITLE_VERTEX_APPEND_STACK_CLEANUP,
            "stride": self.stride,
            "invocation_count": self.invocation_count,
            "max_vertex_index": self.max_vertex_index,
            "last_object_address_hex": _hex32(self.last_object_address or 0)
            if self.last_object_address is not None
            else None,
            "last_record_address_hex": _hex32(self.last_record_address or 0)
            if self.last_record_address is not None
            else None,
            "last_vertex_index": self.last_vertex_index,
            "geometry_bounds": {
                "min_x": self.finite_min_x,
                "max_x": self.finite_max_x,
                "min_y": self.finite_min_y,
                "max_y": self.finite_max_y,
            },
            "anomaly_counts": dict(sorted(self.anomaly_counts.items())),
            "producer_callers": producer_callers,
            "upstream_producers": upstream_producers,
            "geometry_by_guest_flip": [
                {
                    "guest_flip_count": flip,
                    "vertex_count": stats["vertex_count"],
                    "anomaly_count": stats["anomaly_count"],
                    "anomaly_counts": dict(
                        sorted(stats["anomaly_counts"].items())
                    ),
                    "min_x": stats["min_x"],
                    "max_x": stats["max_x"],
                    "min_y": stats["min_y"],
                    "max_y": stats["max_y"],
                    "upstream_producers": [
                        {
                            "upstream_return_address_hex": _hex32(address),
                            **producer,
                        }
                        for address, producer in sorted(
                            stats["upstream_producers"].items(),
                            key=lambda item: (
                                -int(item[1]["anomaly_count"]),
                                -int(item[1]["vertex_count"]),
                                item[0],
                            ),
                        )
                    ],
                }
                for flip, stats in self.flip_geometry_stats.items()
            ],
            "anomalous_samples": list(
                sample for _, sample in sorted(samples_by_invocation.items())
            ),
        }

    @staticmethod
    def _producer_summaries(
        stats_by_address: dict[int, dict[str, Any]],
        *,
        address_field: str,
    ) -> list[dict[str, Any]]:
        producers: list[dict[str, Any]] = []
        for address, stats in sorted(
            stats_by_address.items(),
            key=lambda item: (
                -int(item[1]["anomaly_count"]),
                -int(item[1]["invocation_count"]),
                item[0],
            ),
        ):
            producers.append(
                {
                    address_field: _hex32(address),
                    "invocation_count": stats["invocation_count"],
                    "anomaly_count": stats["anomaly_count"],
                    "anomaly_counts": dict(sorted(stats["anomaly_counts"].items())),
                    "min_x": stats["min_x"],
                    "max_x": stats["max_x"],
                    "min_y": stats["min_y"],
                    "max_y": stats["max_y"],
                    "first_invocation": stats["first_invocation"],
                    "last_invocation": stats["last_invocation"],
                    "first_render_write_count": stats["first_render_write_count"],
                    "last_render_write_count": stats["last_render_write_count"],
                    "first_guest_flip_count": stats["first_guest_flip_count"],
                    "last_guest_flip_count": stats["last_guest_flip_count"],
                    "object_counts": [
                        {
                            "object_address_hex": _hex32(object_address),
                            "invocation_count": count,
                        }
                        for object_address, count in stats["object_counts"].most_common()
                    ],
                }
            )
        return producers


class TitleTextDrawFastPath:
    """Fast-path the observed title text draw helper after its contract is known."""

    def __init__(
        self,
        *,
        draw_address: int = TITLE_TEXT_DRAW_ADDRESS,
        stack_cleanup: int = TITLE_TEXT_DRAW_STACK_CLEANUP,
        max_sample_bytes: int = TITLE_TEXT_DRAW_MAX_SAMPLE_BYTES,
        render_watchpoint: RenderWriteWatchpoint | None = None,
    ) -> None:
        self.draw_address = draw_address
        self.stack_cleanup = stack_cleanup
        self.max_sample_bytes = max_sample_bytes
        self.render_watchpoint = render_watchpoint
        self.invocation_count = 0
        self.total_character_count = 0
        self.max_character_count = 0
        self.last_object_address: int | None = None
        self.last_string_address: int | None = None
        self.last_character_count: int | None = None
        self.last_arguments: tuple[int, ...] = ()
        self.sampled_strings: list[dict[str, Any]] = []
        self.latest_sampled_strings: deque[dict[str, Any]] = deque(maxlen=16)
        self.frame_text: deque[
            tuple[int, bytes, tuple[int, ...], int]
        ] = deque(maxlen=64)
        self.caller_return_counts: Counter[int] = Counter()
        self.frontend_renderer_parent_return_counts: Counter[int] = Counter()
        self.source_text_counts: Counter[int] = Counter()

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.draw_address: self.draw_handler}

    def draw_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        caller_return_address = memory.read_u32(esp)
        frontend_renderer_parent_return = (
            memory.read_u32(_u32(esp + 0xBC))
            if caller_return_address == 0x000B8B44
            else 0
        )
        arguments = tuple(memory.read_u32(_u32(esp + 4 + index * 4)) for index in range(5))
        string_address = arguments[0]
        color_argb = _pack_title_vertex_color(memory, arguments[4])
        object_address = cpu.get_register("ecx")
        frontend_index = memory.read_u32(0x00353104)
        frontend_object_address = memory.read_u32(
            _u32(0x00353108 + frontend_index * 4)
        )
        source_text_address = (
            memory.read_u32(_u32(frontend_object_address + 0x0DE4))
            if frontend_object_address
            else 0
        )
        parent_stack_strings: list[dict[str, Any]] = []
        if caller_return_address == 0x000B8B44 and not self.sampled_strings:
            for stack_offset in range(0xBC, 0x181, 4):
                candidate_address = memory.read_u32(_u32(esp + stack_offset))
                if not 0x00010000 <= candidate_address < 0x80000000:
                    continue
                candidate = _read_guest_c_string(
                    memory,
                    candidate_address,
                    max_bytes=160,
                )
                if len(candidate) < 3 or any(byte < 0x20 or byte >= 0x7F for byte in candidate):
                    continue
                parent_stack_strings.append(
                    {
                        "stack_offset_hex": _hex32(stack_offset),
                        "address_hex": _hex32(candidate_address),
                        "bytes_hex": candidate.hex().upper(),
                    }
                )
        payload = _read_guest_c_string(
            memory,
            string_address,
            max_bytes=self.max_sample_bytes,
        )
        character_count = len(payload)

        _prepare_stdcall_return(cpu, memory, self.stack_cleanup)
        self.invocation_count += 1
        self.total_character_count += character_count
        self.max_character_count = max(self.max_character_count, character_count)
        self.last_object_address = object_address
        self.last_string_address = string_address
        self.last_character_count = character_count
        self.last_arguments = arguments
        self.caller_return_counts[caller_return_address] += 1
        if frontend_renderer_parent_return:
            self.frontend_renderer_parent_return_counts[
                frontend_renderer_parent_return
            ] += 1
        self.source_text_counts[source_text_address] += 1
        sample = {
            "invocation_count": self.invocation_count,
            "string_address_hex": _hex32(string_address),
            "character_count": character_count,
            "bytes_hex": payload.hex().upper(),
            "caller_return_address_hex": _hex32(caller_return_address),
            "frontend_renderer_parent_return_hex": _hex32(
                frontend_renderer_parent_return
            ),
            "frontend_index": frontend_index,
            "frontend_object_address_hex": _hex32(frontend_object_address),
            "source_text_address_hex": _hex32(source_text_address),
            "arguments": [_hex32(argument) for argument in arguments],
            "color_argb": color_argb,
            "color_argb_hex": _hex32(color_argb),
            "parent_stack_strings": parent_stack_strings,
            "render_write_count": (
                self.render_watchpoint.write_count
                if self.render_watchpoint is not None
                else None
            ),
            "guest_flip_count": (
                self.render_watchpoint.flip_count
                if self.render_watchpoint is not None
                else None
            ),
        }
        if len(self.sampled_strings) < 16:
            self.sampled_strings.append(sample)
        self.latest_sampled_strings.append(sample)
        if self.render_watchpoint is not None:
            self.frame_text.append(
                (
                    self.render_watchpoint.flip_count,
                    payload,
                    arguments,
                    color_argb,
                )
            )
        trace.add(
            target,
            "title_text_draw_fast_path",
            invocation_count=self.invocation_count,
            object_address=object_address,
            object_address_hex=_hex32(object_address),
            string_address=string_address,
            string_address_hex=_hex32(string_address),
            character_count=character_count,
            arguments=[_hex32(argument) for argument in arguments],
            color_argb=color_argb,
            color_argb_hex=_hex32(color_argb),
            stack_cleanup=self.stack_cleanup,
            bytes_hex=sample["bytes_hex"],
            caller_return_address=caller_return_address,
            caller_return_address_hex=_hex32(caller_return_address),
            frontend_renderer_parent_return_hex=_hex32(
                frontend_renderer_parent_return
            ),
            frontend_index=frontend_index,
            frontend_object_address_hex=_hex32(frontend_object_address),
            source_text_address_hex=_hex32(source_text_address),
            render_write_count=sample["render_write_count"],
            guest_flip_count=sample["guest_flip_count"],
        )

    def text_for_completed_flip(self, flip_index: int) -> str | None:
        manifest = self.manifest_for_completed_flip(flip_index)
        return str(manifest["frontend_text"]) if manifest is not None else None

    def manifest_for_completed_flip(self, flip_index: int) -> dict[str, Any] | None:
        source_flip = int(flip_index) - 1
        for guest_flip, payload, arguments, color_argb in reversed(
            self.frame_text
        ):
            if guest_flip != source_flip:
                continue
            try:
                text = payload.decode("cp1252")
            except UnicodeDecodeError:
                return None
            return {
                "frontend_text": text,
                "frontend_text_x_bits": arguments[1],
                "frontend_text_y_bits": arguments[2],
                "frontend_text_size_bits": arguments[3],
                "frontend_text_color_argb": color_argb,
            }
        return None

    def summary(self) -> dict[str, Any]:
        samples_by_invocation = {
            int(sample["invocation_count"]): sample
            for sample in [*self.sampled_strings, *self.latest_sampled_strings]
        }
        return {
            "draw_address": self.draw_address,
            "draw_address_hex": _hex32(self.draw_address),
            "stack_cleanup": self.stack_cleanup,
            "invocation_count": self.invocation_count,
            "total_character_count": self.total_character_count,
            "max_character_count": self.max_character_count,
            "last_object_address_hex": _hex32(self.last_object_address or 0)
            if self.last_object_address is not None
            else None,
            "last_string_address_hex": _hex32(self.last_string_address or 0)
            if self.last_string_address is not None
            else None,
            "last_character_count": self.last_character_count,
            "last_arguments": [_hex32(argument) for argument in self.last_arguments],
            "sampled_strings": [
                sample for _, sample in sorted(samples_by_invocation.items())
            ],
            "caller_return_counts": [
                {
                    "caller_return_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in self.caller_return_counts.most_common()
            ],
            "frontend_renderer_parent_return_counts": [
                {
                    "parent_return_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in (
                    self.frontend_renderer_parent_return_counts.most_common()
                )
            ],
            "source_text_counts": [
                {
                    "source_text_address_hex": _hex32(address),
                    "invocation_count": count,
                }
                for address, count in self.source_text_counts.most_common()
            ],
        }


class TitleDirectSoundBufferSyncFastPath:
    """Model the reached DirectSound effect-image transaction above private DSP internals."""

    def __init__(
        self,
        *,
        effect_image_address: int = TITLE_DIRECTSOUND_EFFECT_IMAGE_ADDRESS,
        sync_address: int = TITLE_DIRECTSOUND_BUFFER_SYNC_ADDRESS,
        workspace_address: int = TITLE_DIRECTSOUND_SYNTHETIC_WORKSPACE_ADDRESS,
        sample_limit: int = 16,
    ) -> None:
        self.effect_image_address = effect_image_address
        self.sync_address = sync_address
        self.workspace_address = workspace_address
        self.sample_limit = sample_limit
        self.invocation_count = 0
        self.null_object_count = 0
        self.samples: list[dict[str, Any]] = []

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {self.effect_image_address: self.effect_image_handler}

    def effect_image_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        esp = cpu.get_register("esp")
        object_address = cpu.get_register("ecx")
        image_address = memory.read_u32(_u32(esp + 4))
        image_size = memory.read_u32(_u32(esp + 8))
        workspace_output_address = memory.read_u32(_u32(esp + 12))
        if workspace_output_address:
            memory.write_u32(workspace_output_address, self.workspace_address)
        memory.write_u32(self.workspace_address, image_size)
        self.invocation_count += 1
        if object_address == 0:
            self.null_object_count += 1
        cpu.set_register("eax", 0)
        _prepare_stdcall_return(cpu, memory, 12)
        sample = {
            "invocation_count": self.invocation_count,
            "object_address_hex": _hex32(object_address),
            "image_address_hex": _hex32(image_address),
            "image_size": image_size,
            "workspace_output_address_hex": _hex32(workspace_output_address),
            "workspace_address_hex": _hex32(self.workspace_address),
            "result_hex": "0x00000000",
        }
        if len(self.samples) < self.sample_limit:
            self.samples.append(sample)
        trace.add(target, "title_directsound_effect_image_fast_path", **sample)

    def sync_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        object_address = cpu.get_register("ecx")
        sound_object = memory.read_u32(_u32(object_address + 8)) if object_address else 0
        workspace = memory.read_u32(_u32(object_address + 0x20)) if object_address else 0
        self.invocation_count += 1
        if object_address == 0:
            self.null_object_count += 1
        cpu.set_register("eax", 0)
        sample = {
            "invocation_count": self.invocation_count,
            "object_address_hex": _hex32(object_address),
            "sound_object_hex": _hex32(sound_object),
            "workspace_before_hex": _hex32(workspace),
            "result_hex": "0x00000000",
        }
        if len(self.samples) < self.sample_limit:
            self.samples.append(sample)
        trace.add(target, "title_directsound_buffer_sync_fast_path", **sample)

    def summary(self) -> dict[str, Any]:
        return {
            "effect_image_address_hex": _hex32(self.effect_image_address),
            "sync_address_hex": _hex32(self.sync_address),
            "workspace_address_hex": _hex32(self.workspace_address),
            "invocation_count": self.invocation_count,
            "null_object_count": self.null_object_count,
            "samples": self.samples,
        }


def _pack_title_vertex_color(memory: SparseMemory, color_vector_address: int) -> int:
    components = [
        _truncate_title_color_component(
            _read_guest_float32(memory, _u32(color_vector_address + offset))
        )
        for offset in (0x0C, 0x00, 0x04, 0x08)
    ]
    packed = 0
    for component in components:
        packed = _u32((packed << 8) | component)
    return packed


def _read_guest_float32(memory: SparseMemory, address: int) -> float:
    return struct.unpack("<f", memory.read(address, 4))[0]


def _truncate_title_color_component(value: float) -> int:
    if math.isnan(value):
        return 0
    return int(value) & 0xFF


class _FixedCommandRecordRing:
    """Bounded fixed-size record storage with efficient packed batch appends."""

    def __init__(self, capacity: int, *, record_size: int = 16) -> None:
        if capacity <= 0:
            raise ValueError("command record capacity must be positive")
        if record_size <= 0:
            raise ValueError("record size must be positive")
        self.capacity = capacity
        self.record_size = record_size
        self._buffer = bytearray(capacity * self.record_size)
        self._start = 0
        self._count = 0

    def __len__(self) -> int:
        return self._count

    def __iter__(self):
        payload = self.to_bytes()
        for offset in range(0, len(payload), self.record_size):
            yield payload[offset : offset + self.record_size]

    def append(self, record: bytes) -> None:
        self.extend_packed(record)

    def extend_packed(self, payload: bytes | bytearray | memoryview) -> None:
        view = memoryview(payload).cast("B")
        if len(view) % self.record_size:
            raise ValueError(
                f"packed records must be {self.record_size}-byte aligned"
            )
        incoming_count = len(view) // self.record_size
        if incoming_count == 0:
            return
        if incoming_count >= self.capacity:
            retained = view[
                (incoming_count - self.capacity) * self.record_size :
            ]
            self._buffer[:] = retained
            self._start = 0
            self._count = self.capacity
            return
        overflow = max(0, self._count + incoming_count - self.capacity)
        if overflow:
            self._start = (self._start + overflow) % self.capacity
            self._count -= overflow
        write_index = (self._start + self._count) % self.capacity
        first_count = min(incoming_count, self.capacity - write_index)
        first_size = first_count * self.record_size
        first_offset = write_index * self.record_size
        self._buffer[first_offset : first_offset + first_size] = view[:first_size]
        remaining_count = incoming_count - first_count
        if remaining_count:
            remaining_size = remaining_count * self.record_size
            self._buffer[:remaining_size] = view[first_size:]
        self._count += incoming_count

    def tail_bytes(self, record_count: int) -> bytes:
        record_count = max(0, min(int(record_count), self._count))
        if record_count == 0:
            return b""
        start = (self._start + self._count - record_count) % self.capacity
        first_count = min(record_count, self.capacity - start)
        first_offset = start * self.record_size
        first_size = first_count * self.record_size
        if first_count == record_count:
            return bytes(self._buffer[first_offset : first_offset + first_size])
        remaining_size = (record_count - first_count) * self.record_size
        return bytes(
            self._buffer[first_offset : first_offset + first_size]
            + self._buffer[:remaining_size]
        )

    def to_bytes(self) -> bytes:
        return self.tail_bytes(self._count)


class RenderWriteWatchpoint:
    """Capture D3D MMIO/push-buffer writes as memory-observer events."""

    _TRACKED_RESOURCE_METHODS = tuple(
        sorted(
            {
                0x012C,
                0x17FC,
                0x1800,
                0x1808,
                *(range(0x1720, 0x1760, 4)),
                *(range(0x1760, 0x17A0, 4)),
                *(
                    0x1B00 + stage * 0x40 + register
                    for stage in range(4)
                    for register in (0, 4, 0x1C)
                ),
            }
        )
    )
    _TRACKED_RESOURCE_METHOD_SET = frozenset(_TRACKED_RESOURCE_METHODS)

    def __init__(
        self,
        *,
        max_writes: int = DEFAULT_RENDER_STREAM_MAX_WRITES,
        stop_after: int | None = None,
        capture_after: int = 0,
        retain_diagnostic_writes: bool = True,
    ) -> None:
        self.max_writes = max_writes
        self.stop_after = stop_after
        self.capture_after = max(0, capture_after)
        self.retain_diagnostic_writes = retain_diagnostic_writes
        self.mmio_write_count = 0
        self.push_buffer_write_count = 0
        self.writes: list[dict[str, Any]] = []
        self.history_writes: deque[dict[str, Any]] = deque(maxlen=max_writes)
        self.live_command_records = _FixedCommandRecordRing(max_writes)
        self.live_command_eips = _FixedCommandRecordRing(max_writes, record_size=4)
        self.live_command_sources = _FixedCommandRecordRing(max_writes, record_size=4)
        self.live_command_steps = _FixedCommandRecordRing(max_writes, record_size=8)
        self._texture_offsets: dict[int, int] = {}
        self._texture_formats: dict[int, int] = {}
        self._texture_image_rects: dict[int, int] = {}
        self._texture_bindings: list[tuple[int, int, int, int]] = []
        self._texture_binding_seen: set[tuple[int, int, int, int]] = set()
        self.resource_binding_generation = 0
        self._texture_pending = bytearray()
        self._texture_pending_end: int | None = None
        self._vertex_array_offsets: dict[int, int] = {}
        self._vertex_array_formats: dict[int, int] = {}
        self._vertex_buffer_ranges: list[tuple[int, int]] = []
        self._active_vertex_primitive = 0
        self._active_vertex_max_index = -1
        self.flip_count = 0
        self._pending_flip_boundaries: deque[dict[str, int]] = deque()
        self._push_buffer_range_provider: (
            Callable[[], tuple[int, int] | None] | None
        ) = None
        self._dynamic_push_buffer_range: tuple[int, int] | None = None
        self.native_batch_count = 0
        self.native_batch_write_count = 0
        self.native_batch_total_us = 0
        self.native_batch_max_us = 0
        self.native_received_batch_count = 0
        self.native_received_batch_write_count = 0
        self.native_contiguous_batch_count = 0
        self.native_general_batch_count = 0
        self.native_direct_packed_general_batch_count = 0
        self.native_texture_run_count = 0
        self.native_texture_bulk_u32_run_count = 0
        self.native_texture_scalar_run_count = 0
        self.native_texture_packed_payload_run_count = 0
        self.native_observe_fallback_batch_count = 0
        self.resource_method_data_word_count = 0
        self.resource_method_tracked_word_count = 0
        self.resource_method_skipped_word_count = 0
        self.resource_method_aggregated_index_word_count = 0
        self.resource_method_native_scan_count = 0
        self.resource_method_native_compacted_method_count = 0
        self.resource_method_native_span_batch_count = 0
        self.resource_method_native_span_finish_count = 0
        self.resource_method_native_span_event_count = 0
        self.resource_method_native_binding_count = 0
        self.resource_method_native_range_count = 0
        self.resource_method_payload_rescan_bypass_byte_count = 0
        self.native_batch_phase_metrics: dict[str, dict[str, int]] = {}
        self._direct_command_sink: Callable[[memoryview, int], None] | None = None
        self._direct_command_span_sink: Callable[..., None] | None = None
        self._native_resource_method_scanner: (
            Callable[[bytearray, int], tuple[Any, Any, int, int, int, int, int]]
            | None
        ) = None
        self._native_resource_span_scanner: Callable[..., tuple[Any, ...]] | None = (
            None
        )
        self._native_resource_span_finisher: (
            Callable[[], tuple[Any, ...]] | None
        ) = None
        self._native_resource_span_state_exporter: Callable[[], bytes] | None = (
            None
        )
        self._native_resource_span_scan_active = False
        self._native_resource_binding_pending: dict[int, list[int | None]] = {}
        self._native_resource_range_start: int | None = None
        self.direct_command_batch_count = 0
        self.direct_command_write_count = 0

    @property
    def direct_command_transport_enabled(self) -> bool:
        return (
            self._direct_command_sink is not None
            or self._direct_command_span_sink is not None
        )

    def set_direct_command_sink(
        self,
        sink: Callable[[memoryview, int], None],
    ) -> None:
        if self.retain_diagnostic_writes or self.stop_after is not None:
            raise ValueError(
                "direct command transport requires non-diagnostic live capture"
            )
        self._direct_command_sink = sink

    def set_direct_command_span_sink(self, sink: Callable[..., None]) -> None:
        if self.retain_diagnostic_writes or self.stop_after is not None:
            raise ValueError(
                "direct command transport requires non-diagnostic live capture"
            )
        self._direct_command_span_sink = sink

    def _retain_or_forward_command_records(
        self,
        packed_records: Any,
        count: int,
        *,
        eips: Any | None = None,
        source_addresses: Any | None = None,
        steps: Any | None = None,
    ) -> None:
        count = max(0, int(count))
        if count == 0:
            return
        records = memoryview(packed_records).cast("B")[: count * 16]
        if len(records) != count * 16:
            raise ValueError("packed render command batch is truncated")
        if self._direct_command_sink is not None:
            self._direct_command_sink(records, count)
            self.direct_command_batch_count += 1
            self.direct_command_write_count += count
            return
        self.live_command_records.extend_packed(records)
        if eips is None or source_addresses is None or steps is None:
            raise ValueError("retained command records require provenance arrays")
        self.live_command_eips.extend_packed(
            memoryview(eips).cast("B")[: count * 4]
        )
        self.live_command_sources.extend_packed(
            memoryview(source_addresses).cast("B")[: count * 4]
        )
        self.live_command_steps.extend_packed(
            memoryview(steps).cast("B")[: count * 8]
        )

    def set_push_buffer_range_provider(
        self,
        provider: Callable[[], tuple[int, int] | None],
    ) -> None:
        self._push_buffer_range_provider = provider

    def set_native_resource_method_scanner(
        self,
        scanner: Callable[
            [bytearray, int],
            tuple[Any, Any, int, int, int, int, int],
        ],
    ) -> None:
        self._native_resource_method_scanner = scanner

    def set_native_resource_span_scanner(
        self,
        scanner: Callable[..., tuple[Any, ...]],
        finisher: Callable[[], tuple[Any, ...]],
        state_exporter: Callable[[], bytes] | None = None,
        state_importer: Callable[[bytes], None] | None = None,
    ) -> None:
        if (
            self._native_resource_span_state_exporter is not None
            and state_importer is not None
        ):
            # Parser continuation is only one part of this state. Texture,
            # vertex-array, and per-frame resource state must also survive a
            # main/cooperative executor replacement after a completed flip.
            state_importer(self._native_resource_span_state_exporter())
        elif self._native_resource_span_scan_active:
            self._finish_native_resource_span_scan(
                boundary_write_count=self.write_count
            )
        self._native_resource_span_scanner = scanner
        self._native_resource_span_finisher = finisher
        self._native_resource_span_state_exporter = state_exporter

    def _normalize_dynamic_push_buffer_address(self, address: int) -> int | None:
        canonical = XbeBackedSparseMemory._canonical_address(address)
        if not 0x20000000 <= canonical < 0x30000000:
            return None
        active_range = self._dynamic_push_buffer_range
        if active_range is None or not active_range[0] <= canonical < active_range[1]:
            if self._push_buffer_range_provider is None:
                return None
            candidate = self._push_buffer_range_provider()
            if (
                candidate is None
                or candidate[0] >= candidate[1]
                or candidate[1] - candidate[0] > RENDER_PUSH_BUFFER_APERTURE_SIZE
            ):
                return None
            active_range = candidate
            self._dynamic_push_buffer_range = candidate
        if not active_range[0] <= canonical < active_range[1]:
            return None
        # Preserve the complete title allocation in the host's stable
        # push-buffer aperture. Folding this offset to 64 KiB aliases distinct
        # command runs in Burnout 2's 2 MiB ring and yields incomplete frames.
        return TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS + (
            canonical - active_range[0]
        )

    @property
    def write_count(self) -> int:
        return self.mmio_write_count + self.push_buffer_write_count

    def observe(
        self,
        address: int,
        payload: bytes,
        *,
        instruction_address: int | None = None,
        source_address: int | None = None,
        steps: int | None = None,
    ) -> None:
        if len(payload) > 8:
            # Asset and filesystem HLE calls can copy multi-megabyte payloads
            # through this observer. Reject bytes outside the three command
            # apertures before splitting them into the decoder's 8-byte
            # records; chunking first turned ordinary frontend loads into
            # millions of Python calls.
            end = address + len(payload)
            if end > 0x1_0000_0000:
                relevant_offsets = range(0, len(payload), 8)
            else:
                ranges = [
                    (
                        TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS,
                        RENDER_PUSH_BUFFER_APERTURE_END_ADDRESS,
                    ),
                    (0xFED00000, 0xFED10000),
                ]
                dynamic_ranges: set[tuple[int, int]] = set()
                if self._dynamic_push_buffer_range is not None:
                    dynamic_ranges.add(self._dynamic_push_buffer_range)
                if self._push_buffer_range_provider is not None:
                    candidate = self._push_buffer_range_provider()
                    if (
                        candidate is not None
                        and candidate[0] < candidate[1]
                        and candidate[1] - candidate[0]
                        <= RENDER_PUSH_BUFFER_APERTURE_SIZE
                    ):
                        dynamic_ranges.add(candidate)
                for start, stop in dynamic_ranges:
                    ranges.append((start, stop))
                    ranges.append((start | 0x80000000, stop | 0x80000000))
                relevant: set[int] = set()
                for start, stop in ranges:
                    overlap_start = max(address, start)
                    overlap_end = min(end, stop)
                    if overlap_start >= overlap_end:
                        continue
                    first_offset = (
                        (overlap_start - address + 7) // 8
                    ) * 8
                    for offset in range(first_offset, overlap_end - address, 8):
                        relevant.add(offset)
                relevant_offsets = sorted(relevant)
            for offset in relevant_offsets:
                self.observe(
                    address + offset,
                    payload[offset : offset + 8],
                    instruction_address=instruction_address,
                    source_address=source_address,
                    steps=steps,
                )
            return
        kind: str | None = None
        offset: int | None = None
        guest_address = address
        normalized_address = address
        if 0xFED00000 <= address <= 0xFED0FFFF:
            kind = "d3d_mmio"
            offset = address - 0xFED00000
            self.mmio_write_count += 1
        elif (
            TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS
            <= address
            < RENDER_PUSH_BUFFER_APERTURE_END_ADDRESS
        ):
            kind = "d3d_push_buffer"
            offset = address - TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS
            self.push_buffer_write_count += 1
        else:
            normalized = self._normalize_dynamic_push_buffer_address(address)
            if normalized is not None:
                kind = "d3d_push_buffer"
                normalized_address = normalized
                offset = normalized - TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS
                self.push_buffer_write_count += 1
        if kind is None:
            return
        if kind == "d3d_push_buffer":
            self._observe_texture_write(normalized_address, payload)
        else:
            # The MMIO submission that closes the pending push-buffer run is
            # part of the audited flip and must be present in its replay.
            self._finish_native_resource_span_scan(
                boundary_write_count=self.write_count
            )
            self._flush_texture_writes(boundary_write_count=self.write_count)
        command_record = struct.pack(
            "<BBHI8s",
            0 if kind == "d3d_mmio" else 1,
            len(payload),
            0,
            normalized_address,
            payload[:8].ljust(8, b"\x00"),
        )
        if self.direct_command_transport_enabled:
            self._retain_or_forward_command_records(command_record, 1)
        else:
            self._retain_or_forward_command_records(
                command_record,
                1,
                eips=struct.pack("<I", _u32(instruction_address or 0)),
                source_addresses=struct.pack("<I", _u32(source_address or 0)),
                steps=struct.pack("<Q", max(0, int(steps or 0))),
            )
        if self.retain_diagnostic_writes:
            value = int.from_bytes(
                payload[: min(len(payload), 4)],
                "little",
                signed=False,
            )
            record = {
                "sequence": self.write_count - 1,
                "instruction_address_hex": (
                    _hex32(instruction_address)
                    if instruction_address is not None
                    else None
                ),
                "source_address_hex": (
                    _hex32(source_address) if source_address is not None else None
                ),
                "steps": steps,
                "kind": kind,
                "address": _u32(normalized_address),
                "address_hex": _hex32(normalized_address),
                "guest_address": _u32(guest_address),
                "guest_address_hex": _hex32(guest_address),
                "offset": offset,
                "offset_hex": _hex32(offset) if offset is not None else None,
                "value": value,
                "value_hex": _hex32(value),
                "size": len(payload),
                "bytes_hex": payload.hex().upper(),
            }
            self.history_writes.append(record)
            if (
                self.write_count > self.capture_after
                and len(self.writes) < self.max_writes
            ):
                self.writes.append(record)
        if self.stop_after is not None and self.write_count >= self.stop_after:
            raise RenderWatchpointStop(self.to_stream())

    def observe_native_write_batch(
        self,
        packed_records: Any | None,
        addresses: Any,
        values: Any,
        sizes: Any,
        eips: Any,
        source_addresses: Any,
        steps: Any,
        count: int,
        observed_range_start: int | None = None,
        contiguous_u32: bool = False,
        observed_range_end: int | None = None,
        packed_texture_payload: Any | None = None,
        packed_texture_runs: Any | None = None,
        packed_texture_run_count: int = 0,
    ) -> None:
        """Consume the native low-memory push-buffer log without per-write calls."""
        count = max(0, int(count))
        if count == 0:
            return
        self.native_received_batch_count += 1
        self.native_received_batch_write_count += count
        if self.retain_diagnostic_writes or self.stop_after is not None:
            self.native_observe_fallback_batch_count += 1
            for index in range(count):
                size = int(sizes[index])
                self.observe(
                    int(addresses[index]),
                    int(values[index]).to_bytes(size, "little"),
                    instruction_address=int(eips[index]),
                    source_address=int(source_addresses[index]),
                    steps=int(steps[index]),
                )
            return
        reported_range = (
            (int(observed_range_start), int(observed_range_end))
            if observed_range_start is not None
            and observed_range_end is not None
            and int(observed_range_start) < int(observed_range_end)
            and int(observed_range_end) - int(observed_range_start)
            <= RENDER_PUSH_BUFFER_APERTURE_SIZE
            else None
        )
        active_range = reported_range or self._dynamic_push_buffer_range
        if active_range is None and self._push_buffer_range_provider is not None:
            active_range = self._push_buffer_range_provider()
        if (
            active_range is None
            or active_range[0] >= active_range[1]
            or active_range[1] - active_range[0]
            > RENDER_PUSH_BUFFER_APERTURE_SIZE
        ):
            self.native_observe_fallback_batch_count += 1
            for index in range(count):
                size = int(sizes[index])
                self.observe(
                    int(addresses[index]),
                    int(values[index]).to_bytes(size, "little"),
                    instruction_address=int(eips[index]),
                    source_address=int(source_addresses[index]),
                    steps=int(steps[index]),
                )
            return

        started_ns = time.perf_counter_ns()
        self._dynamic_push_buffer_range = active_range
        if (
            packed_records is not None
            and contiguous_u32
            and observed_range_start == active_range[0]
        ):
            self.native_contiguous_batch_count += 1
            texture_started_ns = time.perf_counter_ns()
            guest_address = int(addresses[0])
            normalized_address = TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS + (
                guest_address - active_range[0]
            )
            if (
                self._texture_pending
                and normalized_address != self._texture_pending_end
            ):
                self._flush_texture_writes(
                    boundary_write_count=self.write_count
                )
            if packed_texture_payload is not None:
                texture_payload = memoryview(packed_texture_payload).cast("B")[
                    : count * 4
                ]
            else:
                # Compatibility for direct watchpoint callers. NativeExecutor
                # supplies the densely packed payload on the live hot path.
                texture_payload = b"".join(
                    struct.pack("<I", int(values[index]) & 0xFFFFFFFF)
                    for index in range(count)
                )
            self._texture_pending.extend(texture_payload)
            self._texture_pending_end = normalized_address + count * 4
            self.native_texture_run_count += 1
            self.native_texture_bulk_u32_run_count += 1
            self.push_buffer_write_count += count
            self._record_native_batch_phase("texture_update", texture_started_ns)
            command_started_ns = time.perf_counter_ns()
            self._retain_or_forward_command_records(
                packed_records,
                count,
                eips=eips,
                source_addresses=source_addresses,
                steps=steps,
            )
            self._record_native_batch_phase("command_forward", command_started_ns)
            elapsed_us = max(
                0,
                (time.perf_counter_ns() - started_ns) // 1_000,
            )
            self.native_batch_count += 1
            self.native_batch_write_count += count
            self.native_batch_total_us += elapsed_us
            self.native_batch_max_us = max(
                self.native_batch_max_us,
                elapsed_us,
            )
            return
        self.native_general_batch_count += 1
        if (
            packed_records is not None
            and observed_range_start == active_range[0]
        ):
            self.native_direct_packed_general_batch_count += 1
            texture_started_ns = time.perf_counter_ns()
            if (
                packed_texture_payload is not None
                and packed_texture_runs is not None
                and packed_texture_run_count > 0
            ):
                self._observe_packed_native_texture_write_runs(
                    packed_texture_payload,
                    packed_texture_runs,
                    packed_texture_run_count,
                )
            else:
                self._observe_native_texture_write_runs(
                    addresses,
                    values,
                    sizes,
                    count,
                    active_range,
                )
            self.push_buffer_write_count += count
            self._record_native_batch_phase("texture_update", texture_started_ns)
            command_started_ns = time.perf_counter_ns()
            self._retain_or_forward_command_records(
                packed_records,
                count,
                eips=eips,
                source_addresses=source_addresses,
                steps=steps,
            )
            self._record_native_batch_phase("command_forward", command_started_ns)
            elapsed_us = max(
                0,
                (time.perf_counter_ns() - started_ns) // 1_000,
            )
            self.native_batch_count += 1
            self.native_batch_write_count += count
            self.native_batch_total_us += elapsed_us
            self.native_batch_max_us = max(
                self.native_batch_max_us,
                elapsed_us,
            )
            return
        records = bytearray(count * 16)
        eip_records = bytearray(count * 4)
        source_records = bytearray(count * 4)
        step_records = bytearray(count * 8)
        record_count = 0
        record_struct = struct.Struct("<BBHIII")
        for index in range(count):
            guest_address = XbeBackedSparseMemory._canonical_address(
                int(addresses[index])
            )
            size = int(sizes[index])
            if (
                size not in {1, 4}
                or not active_range[0] <= guest_address < active_range[1]
                or guest_address + size > active_range[1]
            ):
                raise ValueError(
                    "native render-write batch escaped its observed push-buffer range"
                )
            value = int(values[index]) & (0xFF if size == 1 else 0xFFFFFFFF)
            normalized_address = TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS + (
                guest_address - active_range[0]
            )
            self.push_buffer_write_count += 1
            payload = value.to_bytes(size, "little")
            self._observe_texture_write(normalized_address, payload)
            record_struct.pack_into(
                records,
                record_count * 16,
                1,
                size,
                0,
                normalized_address,
                value,
                0,
            )
            struct.pack_into("<I", eip_records, record_count * 4, int(eips[index]))
            struct.pack_into(
                "<I",
                source_records,
                record_count * 4,
                int(source_addresses[index]),
            )
            struct.pack_into("<Q", step_records, record_count * 8, int(steps[index]))
            record_count += 1
        self._retain_or_forward_command_records(
            records,
            record_count,
            eips=eip_records,
            source_addresses=source_records,
            steps=step_records,
        )
        elapsed_us = max(0, (time.perf_counter_ns() - started_ns) // 1_000)
        self.native_batch_count += 1
        self.native_batch_write_count += record_count
        self.native_batch_total_us += elapsed_us
        self.native_batch_max_us = max(self.native_batch_max_us, elapsed_us)

    def observe_native_write_span_batch(
        self,
        payload: Any,
        payload_size: int,
        addresses: Any,
        payload_offsets: Any,
        payload_sizes: Any,
        write_counts: Any,
        flags: Any,
        span_count: int,
        observed_range_start: int,
        observed_range_end: int,
        _normalized_base: int,
    ) -> None:
        """Consume native push writes as contiguous payload spans."""
        span_count = max(0, int(span_count))
        payload_size = max(0, int(payload_size))
        if span_count == 0:
            return
        active_range = (int(observed_range_start), int(observed_range_end))
        if (
            active_range[0] >= active_range[1]
            or active_range[1] - active_range[0]
            > RENDER_PUSH_BUFFER_APERTURE_SIZE
        ):
            raise ValueError("native command spans have an invalid observed range")
        payload_view = memoryview(payload).cast("B")[:payload_size]
        if len(payload_view) != payload_size:
            raise ValueError("native command span payload is truncated")

        started_ns = time.perf_counter_ns()
        batch_write_start = self.write_count
        cumulative_write_count = 0
        normalized_addresses: list[int] = []
        previous_payload_end = 0
        for span_index in range(span_count):
            guest_address = int(addresses[span_index])
            payload_offset = int(payload_offsets[span_index])
            span_size = int(payload_sizes[span_index])
            span_write_count = int(write_counts[span_index])
            span_flags = int(flags[span_index])
            if (
                span_size <= 0
                or span_write_count <= 0
                or payload_offset != previous_payload_end
                or payload_offset + span_size > payload_size
                or guest_address < active_range[0]
                or guest_address + span_size > active_range[1]
                or span_flags & ~1
            ):
                raise ValueError("invalid native command span descriptor")
            normalized_address = TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS + (
                guest_address - active_range[0]
            )
            normalized_addresses.append(normalized_address)
            cumulative_write_count += span_write_count
            previous_payload_end = payload_offset + span_size
            self.native_texture_run_count += 1
            self.native_texture_packed_payload_run_count += 1
        if previous_payload_end != payload_size:
            raise ValueError("native command span payload contains trailing bytes")

        if self._native_resource_span_scanner is not None:
            if self._texture_pending:
                self._flush_texture_writes(
                    boundary_write_count=batch_write_start
                )
            (
                methods,
                values,
                positions,
                method_count,
                data_word_count,
                tracked_word_count,
                skipped_word_count,
                aggregated_index_word_count,
            ) = self._native_resource_span_scanner(
                payload,
                payload_size,
                addresses,
                payload_offsets,
                payload_sizes,
                flags,
                span_count,
            )
            method_index = 0
            write_cursor = 0
            for span_index in range(span_count):
                before_position = span_index * 2
                while (
                    method_index < method_count
                    and int(positions[method_index]) == before_position
                ):
                    self._observe_texture_method(
                        int(methods[method_index]),
                        int(values[method_index]),
                        record_flips=False,
                        boundary_write_count=batch_write_start + write_cursor,
                    )
                    method_index += 1
                if (
                    method_index < method_count
                    and int(positions[method_index]) < before_position
                ):
                    raise ValueError("native resource span events are unordered")
                write_cursor += int(write_counts[span_index])
                after_position = before_position + 1
                while (
                    method_index < method_count
                    and int(positions[method_index]) == after_position
                ):
                    self._observe_texture_method(
                        int(methods[method_index]),
                        int(values[method_index]),
                        record_flips=False,
                        boundary_write_count=batch_write_start + write_cursor,
                    )
                    method_index += 1
                if (
                    method_index < method_count
                    and int(positions[method_index]) < after_position
                ):
                    raise ValueError("native resource span events are unordered")
                if int(flags[span_index]) & 1:
                    span_size = int(payload_sizes[span_index])
                    payload_offset = int(payload_offsets[span_index])
                    if span_size < 4:
                        raise ValueError("native flip span has no complete value")
                    flip_value = int.from_bytes(
                        payload_view[
                            payload_offset + span_size - 4 : payload_offset + span_size
                        ],
                        "little",
                    )
                    self._observe_texture_method(
                        0x012C,
                        flip_value,
                        record_flips=True,
                        boundary_write_count=batch_write_start + write_cursor,
                    )
            if method_index != method_count:
                raise ValueError("native resource span event position is invalid")
            self._account_native_resource_span_scan(
                method_count=method_count,
                data_word_count=data_word_count,
                tracked_word_count=tracked_word_count,
                skipped_word_count=skipped_word_count,
                aggregated_index_word_count=aggregated_index_word_count,
                payload_size=payload_size,
                finish=False,
            )
            self._native_resource_span_scan_active = not bool(
                int(flags[span_count - 1]) & 1
            )
        else:
            legacy_write_cursor = 0
            for span_index, normalized_address in enumerate(
                normalized_addresses
            ):
                payload_offset = int(payload_offsets[span_index])
                span_size = int(payload_sizes[span_index])
                if (
                    self._texture_pending
                    and normalized_address != self._texture_pending_end
                ):
                    self._flush_texture_writes(
                        boundary_write_count=(
                            batch_write_start + legacy_write_cursor
                        )
                    )
                self._texture_pending.extend(
                    payload_view[payload_offset : payload_offset + span_size]
                )
                self._texture_pending_end = normalized_address + span_size
                legacy_write_cursor += int(write_counts[span_index])
                if int(flags[span_index]) & 1:
                    self._flush_texture_writes(
                        boundary_write_count=(
                            batch_write_start + legacy_write_cursor
                        )
                    )

        self._dynamic_push_buffer_range = active_range
        self.push_buffer_write_count += cumulative_write_count
        self.native_received_batch_count += 1
        self.native_received_batch_write_count += cumulative_write_count
        self.native_batch_count += 1
        self.native_batch_write_count += cumulative_write_count
        if self._direct_command_span_sink is None:
            raise RuntimeError("native command spans have no live transport sink")
        self._direct_command_span_sink(
            payload_view,
            normalized_addresses,
            payload_offsets,
            payload_sizes,
            write_counts,
            flags,
            span_count,
        )
        self.direct_command_batch_count += 1
        self.direct_command_write_count += cumulative_write_count
        elapsed_us = max(0, (time.perf_counter_ns() - started_ns) // 1_000)
        self.native_batch_total_us += elapsed_us
        self.native_batch_max_us = max(self.native_batch_max_us, elapsed_us)

    def _observe_native_texture_write_runs(
        self,
        addresses: Any,
        values: Any,
        sizes: Any,
        count: int,
        active_range: tuple[int, int],
    ) -> None:
        """Append general native writes as maximal contiguous texture runs."""
        batch_write_start = self.write_count
        value_bytes = memoryview(values).cast("B")
        index = 0
        while index < count:
            run_start = index
            guest_address = int(addresses[index])
            size = int(sizes[index])
            if (
                size not in {1, 4}
                or not active_range[0] <= guest_address < active_range[1]
                or guest_address + size > active_range[1]
            ):
                raise ValueError(
                    "native render-write batch escaped its observed push-buffer range"
                )
            run_end = guest_address + size
            bulk_u32 = size == 4
            index += 1
            while index < count:
                next_address = int(addresses[index])
                next_size = int(sizes[index])
                if (
                    next_size not in {1, 4}
                    or not active_range[0] <= next_address < active_range[1]
                    or next_address + next_size > active_range[1]
                ):
                    raise ValueError(
                        "native render-write batch escaped its observed push-buffer range"
                    )
                if next_address != run_end:
                    break
                run_end += next_size
                bulk_u32 = bulk_u32 and next_size == 4
                index += 1

            normalized_address = TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS + (
                guest_address - active_range[0]
            )
            if (
                self._texture_pending
                and normalized_address != self._texture_pending_end
            ):
                self._flush_texture_writes(
                    boundary_write_count=batch_write_start + run_start
                )
            if bulk_u32:
                self._texture_pending.extend(
                    value_bytes[run_start * 4 : index * 4]
                )
                self.native_texture_bulk_u32_run_count += 1
            else:
                for record_index in range(run_start, index):
                    record_size = int(sizes[record_index])
                    value = int(values[record_index])
                    self._texture_pending.extend(
                        value.to_bytes(4, "little")[:record_size]
                    )
                self.native_texture_scalar_run_count += 1
            self._texture_pending_end = normalized_address + (
                run_end - guest_address
            )
            self.native_texture_run_count += 1

    def _observe_packed_native_texture_write_runs(
        self,
        payload: Any,
        runs: Any,
        run_count: int,
    ) -> None:
        """Append native-compacted texture runs without scanning guest writes."""
        batch_write_start = self.write_count
        payload_view = memoryview(payload).cast("B")
        previous_record_index = -1
        for run_index in range(run_count):
            descriptor_index = run_index * 4
            normalized_address = int(runs[descriptor_index])
            payload_offset = int(runs[descriptor_index + 1])
            payload_size = int(runs[descriptor_index + 2])
            record_index = int(runs[descriptor_index + 3])
            if (
                record_index <= previous_record_index
                or payload_size <= 0
                or payload_offset + payload_size > len(payload_view)
                or not TITLE_D3D_PUSH_BUFFER_BASE_ADDRESS
                <= normalized_address
                < RENDER_PUSH_BUFFER_APERTURE_END_ADDRESS
                or normalized_address + payload_size
                > RENDER_PUSH_BUFFER_APERTURE_END_ADDRESS
            ):
                raise ValueError("invalid packed native texture-write run")
            if (
                self._texture_pending
                and normalized_address != self._texture_pending_end
            ):
                self._flush_texture_writes(
                    boundary_write_count=batch_write_start + record_index
                )
            self._texture_pending.extend(
                payload_view[payload_offset : payload_offset + payload_size]
            )
            self._texture_pending_end = normalized_address + payload_size
            self.native_texture_run_count += 1
            self.native_texture_packed_payload_run_count += 1
            previous_record_index = record_index

    def to_stream(self) -> dict[str, Any]:
        return {
            "write_count": self.write_count,
            "mmio_write_count": self.mmio_write_count,
            "push_buffer_write_count": self.push_buffer_write_count,
            "captured_write_count": len(self.writes),
            "capture_after_write_count": self.capture_after,
            "diagnostic_write_retention": self.retain_diagnostic_writes,
            "skipped_write_count": min(self.write_count, self.capture_after),
            "truncated": self.write_count > len(self.writes),
            "dynamic_push_buffer_range": (
                {
                    "base_hex": _hex32(self._dynamic_push_buffer_range[0]),
                    "end_hex": _hex32(self._dynamic_push_buffer_range[1]),
                }
                if self._dynamic_push_buffer_range is not None
                else None
            ),
            "native_write_batch": self._native_write_batch_summary(),
            "transform_constant_upload_provenance": (
                self._transform_constant_upload_provenance_summary()
            ),
            "writes": list(self.writes),
        }

    def history_stream(self) -> dict[str, Any]:
        self._flush_texture_writes(clear=False)
        return {
            "write_count": self.write_count,
            "mmio_write_count": self.mmio_write_count,
            "push_buffer_write_count": self.push_buffer_write_count,
            "captured_write_count": len(self.history_writes),
            "diagnostic_write_retention": self.retain_diagnostic_writes,
            "truncated": self.write_count > len(self.history_writes),
            "native_write_batch": self._native_write_batch_summary(),
            "transform_constant_upload_provenance": (
                self._transform_constant_upload_provenance_summary()
            ),
            "writes": list(self.history_writes),
            "texture_bindings": [list(binding) for binding in self._texture_bindings],
            "vertex_buffer_ranges": [
                [start, end] for start, end in self._vertex_buffer_ranges
            ],
        }

    def resource_binding_stream(self) -> dict[str, Any]:
        """Return retained GPU resource bindings without cloning diagnostic writes."""
        self._flush_texture_writes(clear=False)
        return {
            "texture_bindings": [list(binding) for binding in self._texture_bindings],
            "vertex_buffer_ranges": [
                [start, end] for start, end in self._vertex_buffer_ranges
            ],
        }

    def live_epoch_stream(self) -> dict[str, Any]:
        captured_write_count = (
            min(self.write_count, self.max_writes)
            if self.direct_command_transport_enabled
            else len(self.live_command_records)
        )
        return {
            "write_count": self.write_count,
            "mmio_write_count": self.mmio_write_count,
            "push_buffer_write_count": self.push_buffer_write_count,
            "captured_write_count": captured_write_count,
            "diagnostic_write_retention": self.retain_diagnostic_writes,
            "direct_command_transport": self.direct_command_transport_enabled,
            "truncated": self.write_count > captured_write_count,
            "native_write_batch": self._native_write_batch_summary(),
            "writes": [],
        }

    def _native_write_batch_summary(self) -> dict[str, Any]:
        return {
            "batch_count": self.native_batch_count,
            "write_count": self.native_batch_write_count,
            "received_batch_count": self.native_received_batch_count,
            "received_write_count": self.native_received_batch_write_count,
            "contiguous_batch_count": self.native_contiguous_batch_count,
            "general_batch_count": self.native_general_batch_count,
            "direct_packed_general_batch_count": (
                self.native_direct_packed_general_batch_count
            ),
            "texture_run_count": self.native_texture_run_count,
            "texture_bulk_u32_run_count": (
                self.native_texture_bulk_u32_run_count
            ),
            "texture_scalar_run_count": self.native_texture_scalar_run_count,
            "texture_packed_payload_run_count": (
                self.native_texture_packed_payload_run_count
            ),
            "resource_method_data_word_count": (
                self.resource_method_data_word_count
            ),
            "resource_method_tracked_word_count": (
                self.resource_method_tracked_word_count
            ),
            "resource_method_skipped_word_count": (
                self.resource_method_skipped_word_count
            ),
            "resource_method_aggregated_index_word_count": (
                self.resource_method_aggregated_index_word_count
            ),
            "resource_method_native_scan_count": (
                self.resource_method_native_scan_count
            ),
            "resource_method_native_compacted_method_count": (
                self.resource_method_native_compacted_method_count
            ),
            "resource_method_native_span_batch_count": (
                self.resource_method_native_span_batch_count
            ),
            "resource_method_native_span_finish_count": (
                self.resource_method_native_span_finish_count
            ),
            "resource_method_native_span_event_count": (
                self.resource_method_native_span_event_count
            ),
            "resource_method_native_binding_count": (
                self.resource_method_native_binding_count
            ),
            "resource_method_native_range_count": (
                self.resource_method_native_range_count
            ),
            "resource_method_payload_rescan_bypass_byte_count": (
                self.resource_method_payload_rescan_bypass_byte_count
            ),
            "phase_timings": {
                name: {
                    **metric,
                    "average_us": round(
                        metric["total_us"] / max(1, metric["count"]),
                        3,
                    ),
                }
                for name, metric in sorted(
                    self.native_batch_phase_metrics.items()
                )
            },
            "average_texture_runs_per_batch": round(
                self.native_texture_run_count / max(1, self.native_batch_count),
                3,
            ),
            "observe_fallback_batch_count": (
                self.native_observe_fallback_batch_count
            ),
            "direct_command_transport": self.direct_command_transport_enabled,
            "direct_command_batch_count": self.direct_command_batch_count,
            "direct_command_write_count": self.direct_command_write_count,
            "total_us": self.native_batch_total_us,
            "max_us": self.native_batch_max_us,
            "average_us": round(
                self.native_batch_total_us / max(1, self.native_batch_count),
                3,
            ),
        }

    def _record_native_batch_phase(self, name: str, started_ns: int) -> None:
        elapsed_us = max(0, (time.perf_counter_ns() - started_ns) // 1_000)
        metric = self.native_batch_phase_metrics.setdefault(
            name,
            {"count": 0, "total_us": 0, "max_us": 0},
        )
        metric["count"] += 1
        metric["total_us"] += elapsed_us
        metric["max_us"] = max(metric["max_us"], elapsed_us)

    def _transform_constant_upload_provenance_summary(self) -> dict[str, Any]:
        retained_count = min(
            len(self.live_command_records),
            len(self.live_command_eips),
            len(self.live_command_sources),
            len(self.live_command_steps),
        )
        if retained_count == 0:
            return {
                "status": (
                    "disabled_for_direct_transport"
                    if self.direct_command_transport_enabled
                    else "not_captured"
                ),
                "retained_command_count": 0,
                "matrix_upload_count": 0,
                "near_zero_basis_matrix_upload_count": 0,
                "near_zero_producer_instruction_counts": [],
                "near_zero_matrix_uploads": [],
                "latest_matrix_upload": None,
            }

        command_bytes = self.live_command_records.tail_bytes(retained_count)
        eip_bytes = self.live_command_eips.tail_bytes(retained_count)
        source_bytes = self.live_command_sources.tail_bytes(retained_count)
        step_bytes = self.live_command_steps.tail_bytes(retained_count)
        command_record = struct.Struct("<BBHI8s")
        method_records: list[dict[str, int]] = []
        run_base: int | None = None
        run_payload = bytearray()
        run_eips: list[int] = []
        run_sources: list[int] = []
        run_steps: list[int] = []

        def flush_run() -> None:
            nonlocal run_base, run_payload, run_eips, run_sources, run_steps
            if run_base is None or len(run_payload) < 4:
                run_base = None
                run_payload = bytearray()
                run_eips = []
                run_sources = []
                run_steps = []
                return
            aligned_size = len(run_payload) & ~3
            words = memoryview(run_payload)[:aligned_size].cast("I")
            index = 0
            while index < len(words):
                command = int(words[index])
                non_increasing = False
                header_words = 1
                if command & 0xE0030003 == 0:
                    count = (command >> 18) & 0x7FF
                elif command & 0xE0030003 == 0x40000000:
                    count = (command >> 18) & 0x7FF
                    non_increasing = True
                elif (
                    command & 0xFFFF0003 == 0x00030000
                    and index + 1 < len(words)
                ):
                    count = int(words[index + 1]) & 0x00FFFFFF
                    non_increasing = True
                    header_words = 2
                else:
                    index += 1
                    continue
                first_method = ((command >> 2) & 0x7FF) * 4
                data_start = index + header_words
                data_end = min(data_start + count, len(words))
                for data_index in range(data_start, data_end):
                    method_offset = 0 if non_increasing else data_index - data_start
                    byte_offset = data_index * 4
                    method_records.append(
                        {
                            "method": first_method + method_offset * 4,
                            "data": int(words[data_index]),
                            "push_buffer_address": run_base + byte_offset,
                            "instruction_address": run_eips[byte_offset],
                            "source_address": run_sources[byte_offset],
                            "steps": run_steps[byte_offset],
                        }
                    )
                index = data_end
            run_base = None
            run_payload = bytearray()
            run_eips = []
            run_sources = []
            run_steps = []

        for index in range(retained_count):
            record_offset = index * command_record.size
            kind, size, _reserved, address, payload = command_record.unpack_from(
                command_bytes,
                record_offset,
            )
            eip = struct.unpack_from("<I", eip_bytes, index * 4)[0]
            source = struct.unpack_from("<I", source_bytes, index * 4)[0]
            steps = struct.unpack_from("<Q", step_bytes, index * 8)[0]
            if kind != 1 or size == 0 or size > len(payload):
                flush_run()
                continue
            if run_base is None or address != run_base + len(run_payload):
                flush_run()
                run_base = address
            run_payload.extend(payload[:size])
            run_eips.extend([eip] * size)
            run_sources.extend([source] * size)
            run_steps.extend([steps] * size)
        flush_run()

        tail_flip_count = sum(
            1 for record in method_records if record["method"] == 0x012C
        )
        first_tail_flip = max(0, self.flip_count - tail_flip_count)
        flip_ordinal = 0
        constant_load = 0
        active_matrix: dict[int, list[dict[str, int]]] | None = None
        matrices: list[dict[str, Any]] = []
        for record in method_records:
            method = record["method"]
            data = record["data"]
            if method == 0x012C:
                flip_ordinal += 1
                continue
            if method == 0x1EA4:
                constant_load = data
                if constant_load != 96:
                    active_matrix = None
                continue
            if not (0x0B80 <= method <= 0x0BFC and (method - 0x0B80) % 4 == 0):
                continue
            lane = ((method - 0x0B80) // 4) % 4
            if lane == 0 and constant_load == 96:
                active_matrix = {}
            if active_matrix is not None and 96 <= constant_load <= 99:
                active_matrix.setdefault(constant_load, []).append(record)
            if lane != 3:
                continue
            if (
                active_matrix is not None
                and constant_load == 99
                and all(len(active_matrix.get(row, [])) == 4 for row in range(96, 100))
            ):
                ordered = [
                    active_matrix[row][component]
                    for row in range(96, 100)
                    for component in range(4)
                ]
                bits = [item["data"] for item in ordered]
                values = list(struct.unpack("<16f", struct.pack("<16I", *bits)))
                rows = [values[offset : offset + 4] for offset in range(0, 16, 4)]
                max_abs_basis = max(
                    abs(component) for row in rows for component in row[:3]
                )
                instruction_counts = Counter(
                    item["instruction_address"]
                    for item in ordered
                    if item["instruction_address"]
                )
                sources = [item["source_address"] for item in ordered if item["source_address"]]
                steps = [item["steps"] for item in ordered if item["steps"]]
                matrices.append(
                    {
                        "next_guest_flip_count": first_tail_flip + flip_ordinal + 1,
                        "position_c96_c99_max_abs_basis": round(max_abs_basis, 9),
                        "position_c96_c99_near_zero_basis": max_abs_basis < 0.01,
                        "position_c96_c99_rows": [
                            [round(component, 9) for component in row] for row in rows
                        ],
                        "position_c96_c99_bits": [
                            bits[offset : offset + 4] for offset in range(0, 16, 4)
                        ],
                        "producer_instruction_counts": [
                            {
                                "instruction_address_hex": _hex32(address),
                                "word_count": count,
                            }
                            for address, count in instruction_counts.most_common()
                        ],
                        "source_address_min_hex": _hex32(min(sources)) if sources else None,
                        "source_address_max_hex": _hex32(max(sources)) if sources else None,
                        "step_min": min(steps) if steps else None,
                        "step_max": max(steps) if steps else None,
                        "push_buffer_address_min_hex": _hex32(
                            min(item["push_buffer_address"] for item in ordered)
                        ),
                        "push_buffer_address_max_hex": _hex32(
                            max(item["push_buffer_address"] for item in ordered)
                        ),
                    }
                )
                active_matrix = None
            constant_load += 1

        near_zero_matrices = [
            matrix
            for matrix in matrices
            if matrix["position_c96_c99_near_zero_basis"]
        ]
        near_zero_producers: Counter[int] = Counter()
        for matrix in near_zero_matrices:
            for producer in matrix["producer_instruction_counts"]:
                near_zero_producers[int(producer["instruction_address_hex"], 0)] += 1
        return {
            "status": "captured" if matrices else "no_position_matrix_uploads_retained",
            "retained_command_count": retained_count,
            "tail_flip_count": tail_flip_count,
            "matrix_upload_count": len(matrices),
            "near_zero_basis_matrix_upload_count": len(near_zero_matrices),
            "near_zero_producer_instruction_counts": [
                {
                    "instruction_address_hex": _hex32(address),
                    "matrix_upload_count": count,
                }
                for address, count in near_zero_producers.most_common(16)
            ],
            "near_zero_matrix_uploads": near_zero_matrices[-16:],
            "latest_matrix_upload": matrices[-1] if matrices else None,
        }

    def has_pending_flip(self) -> bool:
        return bool(self._pending_flip_boundaries)

    def consume_pending_flip_boundaries(self) -> list[dict[str, int]]:
        boundaries = list(self._pending_flip_boundaries)
        self._pending_flip_boundaries.clear()
        return boundaries

    def _account_native_resource_span_scan(
        self,
        *,
        method_count: int,
        data_word_count: int,
        tracked_word_count: int,
        skipped_word_count: int,
        aggregated_index_word_count: int,
        payload_size: int,
        finish: bool,
    ) -> None:
        self.resource_method_data_word_count += data_word_count
        self.resource_method_tracked_word_count += tracked_word_count
        self.resource_method_skipped_word_count += skipped_word_count
        self.resource_method_aggregated_index_word_count += (
            aggregated_index_word_count
        )
        self.resource_method_native_compacted_method_count += method_count
        self.resource_method_native_span_event_count += method_count
        self.resource_method_payload_rescan_bypass_byte_count += payload_size
        if finish:
            self.resource_method_native_span_finish_count += 1
        else:
            self.resource_method_native_span_batch_count += 1

    def _finish_native_resource_span_scan(
        self,
        *,
        boundary_write_count: int,
    ) -> None:
        if not self._native_resource_span_scan_active:
            return
        if self._native_resource_span_finisher is None:
            raise RuntimeError("active native resource span scan has no finisher")
        (
            methods,
            values,
            positions,
            method_count,
            data_word_count,
            tracked_word_count,
            skipped_word_count,
            aggregated_index_word_count,
        ) = self._native_resource_span_finisher()
        for method_index in range(method_count):
            if int(positions[method_index]) != 0:
                raise ValueError("native resource span finish has invalid position")
            self._observe_texture_method(
                int(methods[method_index]),
                int(values[method_index]),
                record_flips=False,
                boundary_write_count=boundary_write_count,
            )
        self._account_native_resource_span_scan(
            method_count=method_count,
            data_word_count=data_word_count,
            tracked_word_count=tracked_word_count,
            skipped_word_count=skipped_word_count,
            aggregated_index_word_count=aggregated_index_word_count,
            payload_size=0,
            finish=True,
        )
        self._native_resource_span_scan_active = False

    def _observe_texture_write(self, address: int, payload: bytes) -> None:
        self._finish_native_resource_span_scan(
            boundary_write_count=self.write_count - 1
        )
        if self._texture_pending and address != self._texture_pending_end:
            self._flush_texture_writes(boundary_write_count=self.write_count - 1)
        self._texture_pending.extend(payload)
        self._texture_pending_end = address + len(payload)

    def _observe_texture_method(
        self,
        method: int,
        data: int,
        *,
        record_flips: bool,
        boundary_write_count: int,
    ) -> None:
        if (
            NATIVE_RESOURCE_BINDING_ADDRESS_EVENT_BASE
            <= method
            < NATIVE_RESOURCE_BINDING_ADDRESS_EVENT_BASE + 4
        ):
            stage = method - NATIVE_RESOURCE_BINDING_ADDRESS_EVENT_BASE
            pending = self._native_resource_binding_pending.setdefault(
                stage, [None, None]
            )
            pending[0] = data
            return
        if (
            NATIVE_RESOURCE_BINDING_FORMAT_EVENT_BASE
            <= method
            < NATIVE_RESOURCE_BINDING_FORMAT_EVENT_BASE + 4
        ):
            stage = method - NATIVE_RESOURCE_BINDING_FORMAT_EVENT_BASE
            pending = self._native_resource_binding_pending.setdefault(
                stage, [None, None]
            )
            pending[1] = data
            return
        if (
            NATIVE_RESOURCE_BINDING_RECT_EVENT_BASE
            <= method
            < NATIVE_RESOURCE_BINDING_RECT_EVENT_BASE + 4
        ):
            stage = method - NATIVE_RESOURCE_BINDING_RECT_EVENT_BASE
            pending = self._native_resource_binding_pending.pop(stage, None)
            if pending is None or pending[0] is None or pending[1] is None:
                raise ValueError("native resource binding event is incomplete")
            binding = (stage, int(pending[0]), int(pending[1]), data)
            if binding not in self._texture_binding_seen:
                self._texture_binding_seen.add(binding)
                self._texture_bindings.append(binding)
                self.resource_binding_generation += 1
            self.resource_method_native_binding_count += 1
            return
        if method == NATIVE_RESOURCE_RANGE_START_EVENT:
            self._native_resource_range_start = data
            return
        if method == NATIVE_RESOURCE_RANGE_END_EVENT:
            if self._native_resource_range_start is None:
                raise ValueError("native resource range event is incomplete")
            self._retain_vertex_buffer_range(
                self._native_resource_range_start,
                data,
            )
            self._native_resource_range_start = None
            self.resource_method_native_range_count += 1
            return
        if method == 0x012C:
            self._retain_active_vertex_buffer_range()
            self._active_vertex_max_index = -1
            if record_flips:
                self.flip_count += 1
                self._pending_flip_boundaries.append(
                    {
                        "flip_index": self.flip_count,
                        "write_count": max(0, boundary_write_count),
                        "flip_value": data,
                    }
                )
            return
        if method == 0x17FC:
            if data != 0:
                self._retain_active_vertex_buffer_range()
                self._active_vertex_primitive = data
                self._active_vertex_max_index = -1
                for stage in sorted(
                    self._texture_offsets.keys() & self._texture_formats.keys()
                ):
                    binding = (
                        stage,
                        self._texture_offsets[stage],
                        self._texture_formats[stage],
                        self._texture_image_rects.get(stage, 0),
                    )
                    if binding not in self._texture_binding_seen:
                        self._texture_binding_seen.add(binding)
                        self._texture_bindings.append(binding)
                        self.resource_binding_generation += 1
            else:
                self._retain_active_vertex_buffer_range()
                self._active_vertex_primitive = 0
                self._active_vertex_max_index = -1
            return
        if method == 0x1800 and self._active_vertex_primitive:
            self._active_vertex_max_index = max(
                self._active_vertex_max_index,
                data & 0xFFFF,
                (data >> 16) & 0xFFFF,
            )
            return
        if method == 0x1808 and self._active_vertex_primitive:
            self._active_vertex_max_index = max(
                self._active_vertex_max_index,
                data,
            )
            return
        if 0x1720 <= method <= 0x175C and (method - 0x1720) % 4 == 0:
            self._vertex_array_offsets[(method - 0x1720) // 4] = data
            return
        if 0x1760 <= method <= 0x179C and (method - 0x1760) % 4 == 0:
            self._vertex_array_formats[(method - 0x1760) // 4] = data
            return
        if not 0x1B00 <= method < 0x1C00:
            return
        stage = (method - 0x1B00) // 0x40
        register = (method - 0x1B00) % 0x40
        if register == 0:
            self._texture_offsets[stage] = data
        elif register == 4:
            self._texture_formats[stage] = data
        elif register == 0x1C:
            self._texture_image_rects[stage] = data

    @staticmethod
    def _vertex_array_element_size(format_raw: int) -> int:
        value_type = format_raw & 0xF
        components = (format_raw >> 4) & 0xF
        if components == 0:
            return 0
        if value_type == 2:
            return components * 4
        if value_type in {0, 4, 6}:
            return 4
        return components * 2

    def _retain_active_vertex_buffer_range(self) -> None:
        if self._active_vertex_max_index < 0:
            return
        starts: list[int] = []
        ends: list[int] = []
        for slot in sorted(
            self._vertex_array_offsets.keys() & self._vertex_array_formats.keys()
        ):
            address = self._vertex_array_offsets[slot]
            format_raw = self._vertex_array_formats[slot]
            stride = (format_raw >> 8) & 0xFFFFFF
            element_size = self._vertex_array_element_size(format_raw)
            if address == 0 or stride == 0 or element_size == 0:
                continue
            end = address + self._active_vertex_max_index * stride + element_size
            if end <= address or end - address > 16 * 1024 * 1024:
                continue
            starts.append(address)
            ends.append(end)
        if not starts:
            return
        for start, end in zip(starts, ends):
            self._retain_vertex_buffer_range(start, end)

    def _retain_vertex_buffer_range(self, start: int, end: int) -> None:
        previous = self._vertex_buffer_ranges
        merged: list[tuple[int, int]] = []
        for candidate_start, candidate_end in sorted(
            [*self._vertex_buffer_ranges, (start, end)]
        ):
            if merged and candidate_start <= merged[-1][1]:
                merged[-1] = (
                    merged[-1][0],
                    max(merged[-1][1], candidate_end),
                )
            else:
                merged.append((candidate_start, candidate_end))
        self._vertex_buffer_ranges = merged
        if merged != previous:
            self.resource_binding_generation += 1

    def _flush_texture_writes(
        self,
        *,
        clear: bool = True,
        boundary_write_count: int | None = None,
    ) -> None:
        if boundary_write_count is None:
            boundary_write_count = self.write_count
        aligned_size = len(self._texture_pending) & ~3
        if self._native_resource_method_scanner is not None and aligned_size:
            (
                methods,
                values,
                method_count,
                data_word_count,
                tracked_word_count,
                skipped_word_count,
                aggregated_index_word_count,
            ) = self._native_resource_method_scanner(
                self._texture_pending,
                aligned_size,
            )
            for method_index in range(method_count):
                self._observe_texture_method(
                    int(methods[method_index]),
                    int(values[method_index]),
                    record_flips=clear,
                    boundary_write_count=boundary_write_count,
                )
            if clear:
                self.resource_method_data_word_count += data_word_count
                self.resource_method_tracked_word_count += tracked_word_count
                self.resource_method_skipped_word_count += skipped_word_count
                self.resource_method_aggregated_index_word_count += (
                    aggregated_index_word_count
                )
                self.resource_method_native_scan_count += 1
                self.resource_method_native_compacted_method_count += method_count
                self._texture_pending = bytearray()
                self._texture_pending_end = None
            return
        words = memoryview(self._texture_pending)[:aligned_size].cast("I")
        index = 0
        while index < len(words):
            command = words[index]
            non_increasing = False
            header_words = 1
            if (command & 0xE0030003) == 0:
                count = (command >> 18) & 0x7FF
            elif (command & 0xE0030003) == 0x40000000:
                count = (command >> 18) & 0x7FF
                non_increasing = True
            elif (
                (command & 0xFFFF0003) == 0x00030000
                and index + 1 < len(words)
            ):
                count = words[index + 1] & 0x00FFFFFF
                non_increasing = True
                header_words = 2
            else:
                index += 1
                continue
            first_method = ((command >> 2) & 0x7FF) * 4
            data_start = index + header_words
            data_end = min(data_start + count, len(words))
            data_word_count = data_end - data_start
            tracked_word_count = 0
            aggregated_index_word_count = 0
            if non_increasing:
                if first_method == 0x1800:
                    tracked_word_count = data_word_count
                    aggregated_index_word_count = data_word_count
                    if self._active_vertex_primitive and data_word_count:
                        self._active_vertex_max_index = max(
                            self._active_vertex_max_index,
                            max(
                                memoryview(self._texture_pending)[
                                    data_start * 4 : data_end * 4
                                ].cast("H")
                            ),
                        )
                elif first_method == 0x1808:
                    tracked_word_count = data_word_count
                    aggregated_index_word_count = data_word_count
                    if self._active_vertex_primitive and data_word_count:
                        self._active_vertex_max_index = max(
                            self._active_vertex_max_index,
                            max(words[data_start:data_end]),
                        )
                elif first_method in self._TRACKED_RESOURCE_METHOD_SET:
                    tracked_word_count = data_word_count
                    for data_index in range(data_start, data_end):
                        self._observe_texture_method(
                            first_method,
                            words[data_index],
                            record_flips=clear,
                            boundary_write_count=boundary_write_count,
                        )
            elif data_word_count:
                last_method = first_method + (data_word_count - 1) * 4
                for method in self._TRACKED_RESOURCE_METHODS:
                    if method < first_method:
                        continue
                    if method > last_method:
                        break
                    method_offset = method - first_method
                    if method_offset % 4:
                        continue
                    data_index = data_start + method_offset // 4
                    self._observe_texture_method(
                        method,
                        words[data_index],
                        record_flips=clear,
                        boundary_write_count=boundary_write_count,
                    )
                    tracked_word_count += 1
            if clear:
                self.resource_method_data_word_count += data_word_count
                self.resource_method_tracked_word_count += tracked_word_count
                self.resource_method_skipped_word_count += (
                    data_word_count - tracked_word_count
                )
                self.resource_method_aggregated_index_word_count += (
                    aggregated_index_word_count
                )
            index = data_end
        if clear:
            self._texture_pending = bytearray()
            self._texture_pending_end = None


_WINDOWS_SHARED_FILE_KERNEL: Any | None = None
_WINDOWS_GENERIC_READ = 0x80000000
_WINDOWS_FILE_SHARE_READ = 0x00000001
_WINDOWS_FILE_SHARE_WRITE = 0x00000002
_WINDOWS_FILE_SHARE_DELETE = 0x00000004
_WINDOWS_OPEN_EXISTING = 3
_WINDOWS_FILE_ATTRIBUTE_NORMAL = 0x00000080
_WINDOWS_INVALID_HANDLE_VALUE = ctypes.c_void_p(-1).value


def _windows_shared_file_kernel() -> Any:
    global _WINDOWS_SHARED_FILE_KERNEL
    if _WINDOWS_SHARED_FILE_KERNEL is not None:
        return _WINDOWS_SHARED_FILE_KERNEL
    kernel = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel.CreateFileW.argtypes = [
        ctypes.c_wchar_p,
        ctypes.c_uint32,
        ctypes.c_uint32,
        ctypes.c_void_p,
        ctypes.c_uint32,
        ctypes.c_uint32,
        ctypes.c_void_p,
    ]
    kernel.CreateFileW.restype = ctypes.c_void_p
    kernel.GetFileSizeEx.argtypes = [
        ctypes.c_void_p,
        ctypes.POINTER(ctypes.c_longlong),
    ]
    kernel.GetFileSizeEx.restype = ctypes.c_int
    kernel.ReadFile.argtypes = [
        ctypes.c_void_p,
        ctypes.c_void_p,
        ctypes.c_uint32,
        ctypes.POINTER(ctypes.c_uint32),
        ctypes.c_void_p,
    ]
    kernel.ReadFile.restype = ctypes.c_int
    kernel.CloseHandle.argtypes = [ctypes.c_void_p]
    kernel.CloseHandle.restype = ctypes.c_int
    _WINDOWS_SHARED_FILE_KERNEL = kernel
    return kernel


def _read_text_file_shared(path: Path) -> str:
    if os.name != "nt":
        return path.read_text(encoding="utf-8")
    kernel = _windows_shared_file_kernel()
    handle = kernel.CreateFileW(
        str(path),
        _WINDOWS_GENERIC_READ,
        _WINDOWS_FILE_SHARE_READ
        | _WINDOWS_FILE_SHARE_WRITE
        | _WINDOWS_FILE_SHARE_DELETE,
        None,
        _WINDOWS_OPEN_EXISTING,
        _WINDOWS_FILE_ATTRIBUTE_NORMAL,
        None,
    )
    if handle == _WINDOWS_INVALID_HANDLE_VALUE:
        error = ctypes.get_last_error()
        if error in (2, 3):
            raise FileNotFoundError(error, os.strerror(error), str(path))
        if error in (5, 32):
            raise PermissionError(error, os.strerror(error), str(path))
        raise OSError(error, os.strerror(error), str(path))
    try:
        file_size = ctypes.c_longlong()
        if not kernel.GetFileSizeEx(handle, ctypes.byref(file_size)):
            error = ctypes.get_last_error()
            raise OSError(error, os.strerror(error), str(path))
        if file_size.value < 0 or file_size.value > 1024 * 1024:
            raise OSError(f"controller snapshot has invalid size: {file_size.value}")
        payload = ctypes.create_string_buffer(max(1, file_size.value))
        bytes_read = ctypes.c_uint32()
        if file_size.value and not kernel.ReadFile(
            handle,
            payload,
            file_size.value,
            ctypes.byref(bytes_read),
            None,
        ):
            error = ctypes.get_last_error()
            raise OSError(error, os.strerror(error), str(path))
        if bytes_read.value != file_size.value:
            raise OSError(
                f"controller snapshot read was truncated: "
                f"{bytes_read.value}/{file_size.value}"
            )
        return payload.raw[: bytes_read.value].decode("utf-8")
    finally:
        kernel.CloseHandle(handle)


class LiveHostBridge:
    """Exchange atomic render snapshots and controller state with the presenter."""

    def __init__(
        self,
        runtime: XboxRuntimeShims,
        render_watchpoint: RenderWriteWatchpoint,
        *,
        render_stream_path: Path,
        controller_state_path: Path,
        render_publish_interval_seconds: float = 1.0 / 45.0,
        render_publish_min_writes: int = 1,
        render_prefix_writes: int = 256,
        render_tail_writes: int = 256,
        controller_poll_interval_seconds: float = (
            DEFAULT_CONTROLLER_POLL_INTERVAL_SECONDS
        ),
        flip_audit_ack_path: Path | None = None,
        flip_audit_timeout_seconds: float = 120.0,
        flip_audit_health_interval: int = 30,
        flip_audit_max_flips: int = 0,
        presentation_ack_path: Path | None = None,
        live_control_transport_name: str | None = None,
        data_export_synchronizer: Callable[[SparseMemory], None] | None = None,
        frontend_text_provider: Callable[
            [int], str | dict[str, Any] | None
        ]
        | None = None,
        guest_metrics_provider: Callable[[], dict[str, int]] | None = None,
        command_epoch_record_limit: int = DEFAULT_COMMAND_EPOCH_RECORD_LIMIT,
    ) -> None:
        self.runtime = runtime
        self.render_watchpoint = render_watchpoint
        self.render_stream_path = render_stream_path
        self.render_resource_path = render_stream_path.with_name(
            render_stream_path.name + ".resources.bin"
        )
        self.current_render_resource_path = self.render_resource_path
        self.command_stream_generation = time.time_ns()
        self.render_command_path = render_stream_path.with_name(
            render_stream_path.name
            + f".{self.command_stream_generation}.commands.bin"
        )
        self.command_snapshot_base_record_count = 0
        self.command_snapshot_base_byte_count = 0
        self.command_snapshot_base_span_count = 0
        self.command_epoch = 0
        self.command_epoch_rotation_count = 0
        self.command_epoch_reuse_count = 0
        self.command_epoch_record_limit = max(1, int(command_epoch_record_limit))
        self.command_epoch_peak_resident_record_count = 0
        self.retired_snapshot_delete_count = 0
        self.retired_snapshot_delete_bytes = 0
        self._retired_command_paths: list[Path] = []
        self._retired_resource_paths: list[Path] = []
        self._render_command_file: BinaryIO | None = None
        self.controller_state_path = controller_state_path
        self.controller_consumed_path = controller_state_path.with_name(
            controller_state_path.name + ".consumed.json"
        )
        self.flip_audit_ack_path = flip_audit_ack_path
        self.presentation_ack_path = presentation_ack_path
        self.live_control_transport_name = live_control_transport_name
        self.live_control_transport = (
            LiveControlTransport.open(live_control_transport_name)
            if live_control_transport_name is not None
            else None
        )
        self.live_command_transport = (
            LiveCommandTransport.open(live_control_transport_name)
            if live_control_transport_name is not None
            and flip_audit_ack_path is None
            else None
        )
        self.live_resource_transport = (
            LiveResourceTransport.open(live_control_transport_name)
            if live_control_transport_name is not None
            and flip_audit_ack_path is None
            else None
        )
        self.live_resource_transport_slot: int | None = None
        self.live_resource_transport_size = 0
        if self.live_command_transport is not None:
            self.render_command_path = Path("shared-memory-command-spans")
        if self.live_resource_transport is not None:
            self.current_render_resource_path = Path(
                "shared-memory-resource-slot"
            )
        self.live_controller_sequence = 0
        self._presentation_ack_file: BinaryIO | None = None
        self.presentation_event_name = (
            f"b2_recomp_presented_{self.command_stream_generation:016X}"
            if presentation_ack_path is not None
            else None
        )
        self.publication_event_name = (
            f"b2_recomp_published_{self.command_stream_generation:016X}"
            if presentation_ack_path is not None
            else None
        )
        self._presentation_event_handle: int | None = None
        self._publication_event_handle: int | None = None
        self._presentation_event_kernel: Any | None = None
        if os.name == "nt" and self.presentation_event_name is not None:
            kernel = ctypes.WinDLL("kernel32", use_last_error=True)
            kernel.CreateEventW.argtypes = [
                ctypes.c_void_p,
                ctypes.c_int,
                ctypes.c_int,
                ctypes.c_wchar_p,
            ]
            kernel.CreateEventW.restype = ctypes.c_void_p
            handle = kernel.CreateEventW(
                None,
                False,
                False,
                self.presentation_event_name,
            )
            if handle:
                self._presentation_event_handle = int(handle)
                self._presentation_event_kernel = kernel
            publication_handle = kernel.CreateEventW(
                None,
                False,
                False,
                self.publication_event_name,
            )
            if publication_handle:
                self._publication_event_handle = int(publication_handle)
                self._presentation_event_kernel = kernel
        self.flip_audit_ledger_path = (
            flip_audit_ack_path.with_name("flips.jsonl")
            if flip_audit_ack_path is not None
            else None
        )
        self.flip_audit_timeout_seconds = max(1.0, float(flip_audit_timeout_seconds))
        self.flip_audit_health_interval = max(0, int(flip_audit_health_interval))
        self.flip_audit_max_flips = max(0, int(flip_audit_max_flips))
        self.data_export_synchronizer = data_export_synchronizer
        self.frontend_text_provider = frontend_text_provider
        self.guest_metrics_provider = guest_metrics_provider
        if self.flip_audit_ack_path is not None:
            self.render_command_path = (
                self.flip_audit_ack_path.parent
                / f"commands.{self.command_stream_generation}.bin"
            )
        self.render_publish_interval_seconds = max(
            0.0, float(render_publish_interval_seconds)
        )
        self.render_publish_min_writes = max(1, int(render_publish_min_writes))
        self.render_prefix_writes = max(0, int(render_prefix_writes))
        self.render_tail_writes = max(1, int(render_tail_writes))
        self.controller_poll_interval_seconds = max(
            0.0, float(controller_poll_interval_seconds)
        )
        self.published_write_count = -1
        self.published_command_record_count = 0
        self.published_command_byte_count = 0
        self.published_command_span_count = 0
        self.direct_command_transport_enabled = bool(
            self.presentation_ack_path is not None
            and self.flip_audit_ack_path is None
            and not self.render_watchpoint.retain_diagnostic_writes
            and self.render_watchpoint.stop_after is None
        )
        self._direct_pending_command_records = bytearray()
        self.direct_command_receive_batch_count = 0
        self.direct_command_receive_record_count = 0
        self.direct_command_receive_span_count = 0
        self.direct_command_receive_payload_byte_count = 0
        self._direct_received_write_count = 0
        self._direct_received_byte_count = 0
        self._direct_received_span_count = 0
        self._direct_command_boundaries: dict[int, tuple[int, int]] = {
            0: (0, 0)
        }
        self.resource_stream_generation = 0
        self.controller_mtime_ns = -1
        self.next_controller_poll_time = 0.0
        self.render_publish_count = 0
        self.slice_exchange_count = 0
        self.render_resource_publish_count = 0
        self.render_resource_reuse_count = 0
        self.render_resource_scan_count = 0
        self.render_resource_dirty_check_count = 0
        self.render_resource_dirty_count = 0
        self.last_render_resource_scan_time = 0.0
        self.last_render_resource_binding_generation = -1
        self.last_render_resource_signatures: (
            tuple[tuple[int, int, int, str, str], ...] | None
        ) = None
        self.last_render_publish_time = 0.0
        self.last_command_flush_time = 0.0
        self.last_published_manifest_flip_count = 0
        self.published_manifest_write_count = 0
        self.controller_update_count = 0
        self.controller_read_defer_count = 0
        self.controller_poll_count = 0
        self.controller_poll_skip_count = 0
        self.clock_advanced_flip_count = 0
        self.clock_wall_sync_ticks_100ns = 0
        self._clocked_flip_count = self.render_watchpoint.flip_count
        self._live_clock_wall_anchor_ns: int | None = None
        self._live_clock_virtual_anchor_100ns: int | None = None
        self.stop_requested = False
        self.audited_flip_count = 0
        self.audit_selected_flip_count = 0
        self.audit_skipped_flip_count = 0
        self.audit_ack_wait_count = 0
        self.presentation_ack_wait_count = 0
        self._last_audit_write_count = 0
        self._last_audit_write_delta = 0
        self._last_audit_flip_value: int | None = None
        self._flip_audit_ledger_buffer: list[str] = []
        self._last_published_manifest: dict[str, Any] | None = None
        self._resource_snapshot_cache: dict[
            tuple[int, int, int, int], tuple[tuple[int, ...], dict[str, Any]]
        ] = {}
        self._performance: dict[str, dict[str, int]] = {}
        self._publish_cadence_samples: deque[tuple[int, int]] = deque(maxlen=120)
        self._video_frame_interval_ns = 1_000_000_000 // 60
        self._next_video_frame_deadline_ns = 0
        self.video_pacing_sleep_count = 0
        self.video_pacing_sleep_us = 0
        self.video_pacing_max_sleep_us = 0
        if self.direct_command_transport_enabled:
            existing_record_count = self.render_watchpoint.write_count
            if existing_record_count != len(
                self.render_watchpoint.live_command_records
            ):
                raise RuntimeError(
                    "direct live command transport must start before command history truncates"
                )
            existing_records = self.render_watchpoint.live_command_records.to_bytes()
            if self.live_command_transport is None:
                self._reset_live_command_spans_atomic(self.render_command_path, b"")
            self.published_write_count = 0
            self.published_command_record_count = 0
            self._update_command_epoch_peak()
            self.render_watchpoint.set_direct_command_sink(
                self._receive_direct_command_records
            )
            self.render_watchpoint.set_direct_command_span_sink(
                self._receive_direct_command_spans
            )
            if existing_records:
                self._receive_direct_command_records(
                    memoryview(existing_records),
                    existing_record_count,
                )
                self._flush_render_commands(force=True)
        self.sample_controller(force=True)
        initial_state = self.runtime.input.poll_controller(0)
        if not initial_state.connected:
            # The Win32 presenter exposes one keyboard-backed controller as
            # connected even before its first state file is published.
            self.runtime.input.set_controller_state(
                0,
                ControllerState(
                    connected=True,
                    buttons=initial_state.buttons,
                    left_trigger=initial_state.left_trigger,
                    right_trigger=initial_state.right_trigger,
                    thumb_lx=initial_state.thumb_lx,
                    thumb_ly=initial_state.thumb_ly,
                    thumb_rx=initial_state.thumb_rx,
                    thumb_ry=initial_state.thumb_ry,
                ),
            )

    @staticmethod
    def _write_json_atomic(path: Path, payload: dict[str, Any]) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(path.name + ".tmp")
        temporary.write_text(
            json.dumps(payload, separators=(",", ":")) + "\n",
            encoding="utf-8",
            newline="\n",
        )
        deadline = time.monotonic() + 10.0
        while True:
            try:
                temporary.replace(path)
                break
            except PermissionError:
                if time.monotonic() >= deadline:
                    raise
                # The Win32 presenter briefly opens the previous snapshot
                # without delete sharing while parsing a hot reload. Wait for
                # that reader to close instead of terminating the guest loop.
                time.sleep(0.02)

    @staticmethod
    def _write_json_shared(path: Path, payload: dict[str, Any]) -> None:
        """Publish one small validated manifest without a rename/open conflict."""
        path.parent.mkdir(parents=True, exist_ok=True)
        encoded = (json.dumps(payload, separators=(",", ":")) + "\n").encode(
            "utf-8"
        )
        with path.open("wb", buffering=0) as output:
            if output.write(encoded) != len(encoded):
                raise OSError(f"short live-manifest write to {path}")

    @staticmethod
    def _encode_texture_resources_binary(
        resources: list[dict[str, Any]],
    ) -> bytes:
        payload = bytearray(b"B2TEX001")
        payload.extend(struct.pack("<I", len(resources)))
        for resource in resources:
            format_bytes = str(resource["format"]).encode("ascii")
            texture_bytes = bytes.fromhex(str(resource["bytes_hex"]))
            content_hash = bytes.fromhex(str(resource["sha256"]))
            if len(format_bytes) == 0 or len(format_bytes) > 32:
                raise ValueError("live texture format name is invalid")
            if len(content_hash) != 32:
                raise ValueError("live texture SHA-256 is invalid")
            payload.extend(
                struct.pack(
                    "<IIIIII32s",
                    int(resource["stage"]),
                    int(resource["address"]),
                    int(resource["width"]),
                    int(resource["height"]),
                    len(format_bytes),
                    len(texture_bytes),
                    content_hash,
                )
            )
            payload.extend(format_bytes)
            payload.extend(texture_bytes)
        return bytes(payload)

    @staticmethod
    def _write_texture_resources_binary(
        path: Path,
        resources: list[dict[str, Any]],
    ) -> None:
        # Normal live resource generations use unique immutable paths. Writing
        # the new file once avoids an expensive antivirus-observed rename while
        # the old manifest continues to reference a complete prior generation
        # until the new payload is fully closed.
        path.parent.mkdir(parents=True, exist_ok=True)
        encoded = LiveHostBridge._encode_texture_resources_binary(resources)
        with path.open("xb", buffering=0) as output:
            if output.write(encoded) != len(encoded):
                raise OSError(f"short live texture snapshot write to {path}")

    @staticmethod
    def _reset_live_commands_atomic(
        path: Path,
        records: bytes,
    ) -> None:
        payload = bytearray(b"B2APPND1")
        payload.extend(records)
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(path.name + ".tmp")
        temporary.write_bytes(payload)
        deadline = time.monotonic() + 10.0
        while True:
            try:
                temporary.replace(path)
                return
            except PermissionError:
                if time.monotonic() >= deadline:
                    raise
                time.sleep(0.02)

    @staticmethod
    def _reset_live_command_spans_atomic(
        path: Path,
        spans: bytes,
    ) -> None:
        payload = b"B2SPAN01" + bytes(spans)
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(path.name + ".tmp")
        temporary.write_bytes(payload)
        deadline = time.monotonic() + 10.0
        while True:
            try:
                temporary.replace(path)
                return
            except PermissionError:
                if time.monotonic() >= deadline:
                    raise
                time.sleep(0.02)

    def _append_live_commands(self, path: Path, records: bytes) -> None:
        if not records:
            return
        if self._render_command_file is None or self._render_command_file.closed:
            self._render_command_file = path.open("ab", buffering=0)
        self._render_command_file.write(records)

    def _receive_direct_command_records(
        self,
        records: memoryview,
        record_count: int,
    ) -> None:
        record_count = max(0, int(record_count))
        expected_size = record_count * 16
        if len(records) != expected_size:
            raise RuntimeError("direct live command batch has an invalid size")
        record = struct.Struct("<BBHI8s")
        for index in range(record_count):
            kind, size, _reserved, address, value = record.unpack_from(
                records,
                index * record.size,
            )
            if kind not in {0, 1} or not 0 < size <= 8:
                raise RuntimeError("direct live command record is invalid")
            self._append_direct_command_span(
                kind,
                0,
                address,
                memoryview(value)[:size],
                1,
            )
        self.direct_command_receive_batch_count += 1
        self.direct_command_receive_record_count += record_count

    def _append_direct_command_span(
        self,
        kind: int,
        flags: int,
        address: int,
        payload: memoryview,
        write_count: int,
    ) -> None:
        payload_size = len(payload)
        if (
            kind not in {0, 1}
            or flags & ~1
            or payload_size <= 0
            or write_count <= 0
        ):
            raise RuntimeError("direct live command span is invalid")
        self._direct_pending_command_records.extend(
            struct.pack(
                "<BBHIII",
                kind,
                flags,
                0,
                int(address) & 0xFFFFFFFF,
                payload_size,
                int(write_count),
            )
        )
        self._direct_pending_command_records.extend(payload)
        self._direct_received_write_count += int(write_count)
        self._direct_received_byte_count += 16 + payload_size
        self._direct_received_span_count += 1
        self._direct_command_boundaries[self._direct_received_write_count] = (
            self._direct_received_byte_count,
            self._direct_received_span_count,
        )
        self.direct_command_receive_span_count += 1
        self.direct_command_receive_payload_byte_count += payload_size

    def _receive_direct_command_spans(
        self,
        payload: memoryview,
        normalized_addresses: list[int],
        payload_offsets: Any,
        payload_sizes: Any,
        write_counts: Any,
        flags: Any,
        span_count: int,
    ) -> None:
        payload_view = memoryview(payload).cast("B")
        for span_index in range(max(0, int(span_count))):
            offset = int(payload_offsets[span_index])
            size = int(payload_sizes[span_index])
            self._append_direct_command_span(
                1,
                int(flags[span_index]),
                normalized_addresses[span_index],
                payload_view[offset : offset + size],
                int(write_counts[span_index]),
            )
        self.direct_command_receive_batch_count += 1
        self.direct_command_receive_record_count = self._direct_received_write_count

    def _close_render_command_file(self) -> None:
        if self._render_command_file is None:
            return
        self._render_command_file.close()
        self._render_command_file = None

    def _update_command_epoch_peak(self) -> None:
        resident_record_count = max(
            0,
            self.published_command_record_count
            - self.command_snapshot_base_record_count,
        )
        self.command_epoch_peak_resident_record_count = max(
            self.command_epoch_peak_resident_record_count,
            resident_record_count,
        )

    def _delete_retired_snapshot(self, path: Path) -> bool:
        try:
            byte_count = path.stat().st_size
            path.unlink()
        except FileNotFoundError:
            return True
        except OSError:
            return False
        self.retired_snapshot_delete_count += 1
        self.retired_snapshot_delete_bytes += byte_count
        return True

    def _cleanup_retired_snapshots(self) -> None:
        if self.presentation_ack_path is None or self.flip_audit_ack_path is not None:
            return
        self._retired_command_paths = [
            path
            for path in self._retired_command_paths
            if not self._delete_retired_snapshot(path)
        ]
        self._retired_resource_paths = [
            path
            for path in self._retired_resource_paths
            if not self._delete_retired_snapshot(path)
        ]

    def _rotate_live_command_epoch(
        self,
        *,
        completed_write_count: int,
        completed_flip_index: int,
    ) -> None:
        if self.presentation_ack_path is None or self.flip_audit_ack_path is not None:
            return
        completed_write_count = max(0, int(completed_write_count))
        if completed_write_count > self.published_command_record_count:
            raise RuntimeError(
                "cannot rotate live command epoch beyond its published command tail"
            )
        completed_epoch_record_count = (
            completed_write_count - self.command_snapshot_base_record_count
        )
        if completed_epoch_record_count < 0:
            raise RuntimeError("completed flip predates the live command epoch")
        if completed_epoch_record_count < self.command_epoch_record_limit:
            self.command_epoch_reuse_count += 1
            return
        carried_record_count = (
            self.published_command_record_count - completed_write_count
        )
        if (
            not self.direct_command_transport_enabled
            and carried_record_count > len(self.render_watchpoint.live_command_records)
        ):
            raise RuntimeError(
                "live render command epoch carry overflowed retained command history"
            )
        self._close_render_command_file()
        if self.direct_command_transport_enabled:
            if self._direct_pending_command_records:
                raise RuntimeError(
                    "cannot rotate a direct command epoch with unflushed spans"
                )
            boundary = self._direct_command_boundaries.get(completed_write_count)
            if boundary is None:
                raise RuntimeError(
                    "completed flip does not end at a direct command span boundary"
                )
            completed_byte_count, completed_span_count = boundary
            byte_offset = (
                completed_byte_count - self.command_snapshot_base_byte_count
            )
            carried_byte_count = (
                self.published_command_byte_count - completed_byte_count
            )
            if byte_offset < 0 or carried_byte_count < 0:
                raise RuntimeError("completed flip predates the live command epoch")
            if self.live_command_transport is not None:
                carried_records = b""
            else:
                with self.render_command_path.open("rb") as command_input:
                    if command_input.read(8) != b"B2SPAN01":
                        raise RuntimeError("live command sidecar header is invalid")
                    command_input.seek(8 + byte_offset)
                    carried_records = command_input.read(carried_byte_count)
                if len(carried_records) != carried_byte_count:
                    raise RuntimeError("live command sidecar carry is truncated")
        else:
            carried_records = self.render_watchpoint.live_command_records.tail_bytes(
                carried_record_count
            )
        if self.render_command_path.is_file():
            self._retired_command_paths.append(self.render_command_path)
        self.command_snapshot_base_record_count = completed_write_count
        if self.direct_command_transport_enabled:
            self.command_snapshot_base_byte_count = completed_byte_count
            self.command_snapshot_base_span_count = completed_span_count
        self.command_epoch += 1
        self.command_epoch_rotation_count += 1
        if self.live_command_transport is None:
            self.render_command_path = self.render_stream_path.with_name(
                self.render_stream_path.name
                + f".{self.command_stream_generation}.epoch-{completed_flip_index:08d}.commands.bin"
            )
        if self.direct_command_transport_enabled:
            if self.live_command_transport is None:
                self._reset_live_command_spans_atomic(
                    self.render_command_path,
                    carried_records,
                )
            self._direct_command_boundaries = {
                write_count: value
                for write_count, value in self._direct_command_boundaries.items()
                if write_count >= completed_write_count
            }
        else:
            self._reset_live_commands_atomic(
                self.render_command_path,
                carried_records,
            )
        self._update_command_epoch_peak()

    def _record_performance(self, name: str, started_ns: int) -> None:
        elapsed_us = max(0, (time.perf_counter_ns() - started_ns) // 1_000)
        metric = self._performance.setdefault(
            name,
            {"count": 0, "total_us": 0, "max_us": 0},
        )
        metric["count"] += 1
        metric["total_us"] += elapsed_us
        metric["max_us"] = max(metric["max_us"], elapsed_us)

    def _performance_summary(self) -> dict[str, Any]:
        metrics = {
            name: {
                **metric,
                "average_us": round(
                    metric["total_us"] / max(1, metric["count"]),
                    3,
                ),
            }
            for name, metric in sorted(self._performance.items())
        }
        return {
            "metrics": metrics,
            "hot_paths": [
                {
                    "name": name,
                    **metrics[name],
                }
                for name in sorted(
                    metrics,
                    key=lambda item: (-metrics[item]["total_us"], item),
                )
            ],
        }

    def _flush_render_commands(self, *, force: bool = False) -> bool:
        write_count = self.render_watchpoint.write_count
        if write_count == 0 or write_count == self.published_write_count:
            return False
        now = time.monotonic()
        if (
            not force
            and self.published_write_count >= 0
            and write_count - self.published_write_count
            < self.render_publish_min_writes
        ):
            return False
        if (
            not force
            and self.published_write_count >= 0
            and now - self.last_command_flush_time
            < self.render_publish_interval_seconds
        ):
            return False
        command_publish_started_ns = time.perf_counter_ns()
        if self.direct_command_transport_enabled:
            new_record_count = write_count - self.published_write_count
            if (
                new_record_count < 0
                or write_count != self._direct_received_write_count
            ):
                raise RuntimeError(
                    "direct live command transport lost synchronization with guest writes"
                )
            if self.live_command_transport is not None:
                transport_end = self.live_command_transport.write(
                    self._direct_pending_command_records
                )
                if transport_end != self._direct_received_byte_count:
                    raise RuntimeError(
                        "shared command transport cursor lost synchronization"
                    )
            else:
                if not self.render_command_path.is_file():
                    raise RuntimeError("direct live command sidecar disappeared")
                self._append_live_commands(
                    self.render_command_path,
                    self._direct_pending_command_records,
                )
            self._direct_pending_command_records.clear()
            self.published_command_record_count = self._direct_received_write_count
            self.published_command_byte_count = self._direct_received_byte_count
            self.published_command_span_count = self._direct_received_span_count
            self._update_command_epoch_peak()
            self.published_write_count = write_count
            self.last_command_flush_time = now
            self._record_performance(
                "render_command_publish",
                command_publish_started_ns,
            )
            return True
        live_records = self.render_watchpoint.live_command_records
        if self.published_write_count < 0 or not self.render_command_path.is_file():
            epoch_record_count = write_count - self.command_snapshot_base_record_count
            if epoch_record_count < 0 or epoch_record_count > len(live_records):
                raise RuntimeError(
                    "live render command epoch overflowed before sidecar publication"
                )
            self._close_render_command_file()
            self._reset_live_commands_atomic(
                self.render_command_path,
                live_records.tail_bytes(epoch_record_count),
            )
            self.published_command_record_count = write_count
        else:
            new_record_count = write_count - self.published_write_count
            if new_record_count > len(live_records):
                if self.flip_audit_ack_path is not None:
                    raise RuntimeError(
                        "lossless flip audit command history overflowed before publication"
                    )
                raise RuntimeError(
                    "live render command history overflowed before sidecar flush"
                )
            new_records = live_records.tail_bytes(new_record_count)
            self._append_live_commands(self.render_command_path, new_records)
            self.published_command_record_count += new_record_count
        self._update_command_epoch_peak()
        self.published_write_count = write_count
        self.last_command_flush_time = now
        self._record_performance("render_command_publish", command_publish_started_ns)
        return True

    def publish_render(
        self,
        memory: SparseMemory,
        *,
        force: bool = False,
        audit_flip: dict[str, Any] | None = None,
        completed_flip: dict[str, Any] | None = None,
        guest_steps: int | None = None,
    ) -> bool:
        write_count = self.render_watchpoint.write_count
        if write_count == 0:
            return False
        if (
            not force
            and audit_flip is None
            and completed_flip is None
            and self.render_publish_count > 0
            and write_count - self.published_manifest_write_count
            < self.render_publish_min_writes
        ):
            return False
        now = time.monotonic()
        if (
            not force
            and self.render_publish_count > 0
            and now - self.last_render_publish_time
            < self.render_publish_interval_seconds
        ):
            return False
        publish_started_ns = time.perf_counter_ns()
        self._flush_render_commands(force=True)
        self._close_render_command_file()
        # Live presentation needs the newest completed flip, not the bounded
        # probe's oldest retained prefix.
        stream_snapshot_started_ns = time.perf_counter_ns()
        stream = self.render_watchpoint.live_epoch_stream()
        self._record_performance("render_stream_snapshot", stream_snapshot_started_ns)
        binding_generation = self.render_watchpoint.resource_binding_generation
        binding_changed = (
            binding_generation != self.last_render_resource_binding_generation
        )
        cached_resource_changed = False
        if self.last_render_resource_signatures is not None and not binding_changed:
            self.render_resource_dirty_check_count += 1
            cached_resource_changed = self._cached_render_resource_changed(memory)
            if cached_resource_changed:
                self.render_resource_dirty_count += 1
        resource_snapshot_changed = False
        if (
            self.last_render_resource_signatures is None
            or binding_changed
            or cached_resource_changed
        ):
            resource_scan_started_ns = time.perf_counter_ns()
            history = self.render_watchpoint.resource_binding_stream()
            stream = _snapshot_render_texture_resources(
                stream,
                history,
                memory,
                cache=self._resource_snapshot_cache,
            )
            resource_signatures = tuple(
                (
                    int(resource["address"]),
                    int(resource["width"]),
                    int(resource["height"]),
                    str(resource["format"]),
                    str(resource["sha256"]),
                )
                for resource in stream["resource_snapshots"]
            )
            if resource_signatures != self.last_render_resource_signatures:
                resource_snapshot_changed = True
                self.resource_stream_generation = time.time_ns()
                if self.live_resource_transport is not None:
                    encoded_resources = self._encode_texture_resources_binary(
                        stream["resource_snapshots"]
                    )
                    self.live_resource_transport_slot = (
                        self.live_resource_transport.publish(
                            encoded_resources,
                            self.resource_stream_generation,
                        )
                    )
                    self.live_resource_transport_size = len(encoded_resources)
                    self.current_render_resource_path = Path(
                        f"shared-memory-resource-slot-"
                        f"{self.live_resource_transport_slot}"
                    )
                elif self.flip_audit_ack_path is not None:
                    self.current_render_resource_path = (
                        self.flip_audit_ack_path.parent
                        / "resources"
                        / f"resources.{self.resource_stream_generation}.json"
                    )
                    self._write_json_atomic(
                        self.current_render_resource_path,
                        {
                            "resource_snapshot_count": len(stream["resource_snapshots"]),
                            "resource_snapshots": stream["resource_snapshots"],
                        },
                    )
                else:
                    next_render_resource_path = self.render_stream_path.with_name(
                        self.render_stream_path.name
                        + f".resources.{self.resource_stream_generation}.bin"
                    )
                    if (
                        self.presentation_ack_path is not None
                        and self.current_render_resource_path.is_file()
                    ):
                        self._retired_resource_paths.append(
                            self.current_render_resource_path
                        )
                    self.current_render_resource_path = next_render_resource_path
                    self._write_texture_resources_binary(
                        self.current_render_resource_path,
                        stream["resource_snapshots"],
                    )
                self.last_render_resource_signatures = resource_signatures
                self.render_resource_publish_count += 1
            self.render_resource_scan_count += 1
            self.last_render_resource_scan_time = now
            self.last_render_resource_binding_generation = binding_generation
            self._record_performance("render_resource_scan", resource_scan_started_ns)
        else:
            stream["resource_snapshots"] = []
            stream["resource_snapshot_count"] = 0
        resource_snapshots_unchanged = bool(
            self.resource_stream_generation and not resource_snapshot_changed
        )
        if resource_snapshots_unchanged:
            self.render_resource_reuse_count += 1
        selected_flip = audit_flip if audit_flip is not None else completed_flip
        presentable_command_record_count = (
            int(selected_flip["write_count"])
            if selected_flip is not None
            else 0
        )
        manifest_guest_flip_count = (
            int(selected_flip["flip_index"])
            if selected_flip is not None
            else self.last_published_manifest_flip_count
        )
        if presentable_command_record_count > self.published_command_record_count:
            raise RuntimeError(
                "completed flip boundary exceeds flushed live command sidecar"
            )
        presentable_command_byte_count = 0
        presentable_command_span_count = 0
        if self.direct_command_transport_enabled:
            boundary = self._direct_command_boundaries.get(
                presentable_command_record_count
            )
            if boundary is None:
                raise RuntimeError(
                    "completed flip is not aligned to a direct command span"
                )
            (
                presentable_command_byte_count,
                presentable_command_span_count,
            ) = boundary
        manifest: dict[str, Any] = {
            "format": "b2-recomp-live-render-manifest",
            "write_count": stream["write_count"],
            "captured_write_count": stream["captured_write_count"],
            "published_command_record_count": self.published_command_record_count,
            "presentable_command_record_count": presentable_command_record_count,
            "command_snapshot_base_record_count": (
                self.command_snapshot_base_record_count
            ),
            "command_snapshot_base_byte_count": (
                self.command_snapshot_base_byte_count
            ),
            "command_snapshot_base_span_count": (
                self.command_snapshot_base_span_count
            ),
            "command_snapshot_record_count": (
                self.published_command_record_count
                - self.command_snapshot_base_record_count
            ),
            "command_stream_generation": self.command_stream_generation,
            "command_epoch": self.command_epoch,
            "command_epoch_record_limit": self.command_epoch_record_limit,
            "resource_stream_generation": self.resource_stream_generation,
            "resource_snapshots_unchanged": resource_snapshots_unchanged,
            "guest_flip_count": manifest_guest_flip_count,
            "guest_steps": int(guest_steps or 0),
            "command_snapshot_path": str(self.render_command_path).replace("\\", "/"),
            "resource_snapshot_path": str(self.current_render_resource_path).replace("\\", "/"),
        }
        if self.direct_command_transport_enabled:
            manifest.update(
                {
                    "command_transport_format": (
                        "shared_memory_span_v1"
                        if self.live_command_transport is not None
                        else "bulk_span_v1"
                    ),
                    "published_command_byte_count": (
                        self.published_command_byte_count
                    ),
                    "presentable_command_byte_count": (
                        presentable_command_byte_count
                    ),
                    "command_snapshot_base_byte_count": (
                        self.command_snapshot_base_byte_count
                    ),
                    "command_snapshot_byte_count": (
                        self.published_command_byte_count
                        - self.command_snapshot_base_byte_count
                    ),
                    "published_command_span_count": (
                        self.published_command_span_count
                    ),
                    "presentable_command_span_count": (
                        presentable_command_span_count
                    ),
                    "command_snapshot_base_span_count": (
                        self.command_snapshot_base_span_count
                    ),
                    "command_snapshot_span_count": (
                        self.published_command_span_count
                        - self.command_snapshot_base_span_count
                    ),
                }
            )
        if self.live_resource_transport_slot is not None:
            manifest.update(
                {
                    "resource_transport_format": "shared_memory_slot_v1",
                    "resource_transport_slot": self.live_resource_transport_slot,
                    "resource_transport_size": self.live_resource_transport_size,
                }
            )
        guest_metrics = (
            self.guest_metrics_provider()
            if self.guest_metrics_provider is not None
            else {}
        )
        manifest["guest_compiled_blocks"] = max(
            0, int(guest_metrics.get("compiled_blocks", 0))
        )
        manifest["guest_invalidations"] = max(
            0, int(guest_metrics.get("invalidations", 0))
        )
        if selected_flip is not None and self.frontend_text_provider is not None:
            frontend_text = self.frontend_text_provider(manifest_guest_flip_count)
            if isinstance(frontend_text, str) and frontend_text:
                manifest["frontend_text"] = frontend_text
            elif isinstance(frontend_text, dict) and frontend_text.get(
                "frontend_text"
            ):
                for field in (
                    "frontend_text",
                    "frontend_text_x_bits",
                    "frontend_text_y_bits",
                    "frontend_text_size_bits",
                    "frontend_text_color_argb",
                ):
                    if field in frontend_text:
                        manifest[field] = frontend_text[field]
        if self.presentation_ack_path is not None:
            manifest["presentation_ack_path"] = str(
                self.presentation_ack_path
            ).replace("\\", "/")
            manifest["presentation_event_name"] = self.presentation_event_name
            manifest["publication_event_name"] = self.publication_event_name
        if self.live_control_transport_name is not None:
            manifest["live_control_transport"] = {
                "format": "b2-recomp-live-control",
                "schema_version": LIVE_CONTROL_SCHEMA_VERSION,
                "name": self.live_control_transport_name,
            }
        if audit_flip is not None:
            manifest.update(
                {
                    "lossless_flip_audit": True,
                    "audit_flip_index": int(audit_flip["flip_index"]),
                    "audit_flip_value": int(audit_flip["flip_value"]),
                    "audit_command_record_count": int(audit_flip["write_count"]),
                    "audit_guest_steps": int(guest_steps or 0),
                    "audit_health_selected": True,
                    "audit_health_reason": str(
                        audit_flip.get("health_reason", "selected")
                    ),
                    "audit_ack_path": str(self.flip_audit_ack_path).replace("\\", "/"),
                    "audit_ledger_path": str(self.flip_audit_ledger_path).replace("\\", "/"),
                }
            )
        manifest_publish_started_ns = time.perf_counter_ns()
        if (
            self.live_control_transport is not None
            and self.flip_audit_ack_path is None
        ):
            self.live_control_transport.publish_manifest(manifest)
        elif self.flip_audit_ack_path is not None or self.render_publish_count == 0:
            self._write_json_atomic(self.render_stream_path, manifest)
        else:
            self._write_json_shared(self.render_stream_path, manifest)
        self._record_performance("render_manifest_publish", manifest_publish_started_ns)
        self._last_published_manifest = manifest
        if (
            self._publication_event_handle is not None
            and self._presentation_event_kernel is not None
        ):
            self._presentation_event_kernel.SetEvent(
                ctypes.c_void_p(self._publication_event_handle)
            )
        self.last_published_manifest_flip_count = manifest_guest_flip_count
        self.published_manifest_write_count = write_count
        self.render_publish_count += 1
        self.last_render_publish_time = now
        self._publish_cadence_samples.append(
            (manifest_guest_flip_count, time.perf_counter_ns())
        )
        self._record_performance("publish_render_total", publish_started_ns)
        return True

    def should_yield_for_completed_flip(self) -> bool:
        # Normal presentation also yields on the exact completed-flip write.
        # That prevents a large native slice from crossing multiple frame
        # boundaries before the bridge can publish them individually.
        return self.render_watchpoint.has_pending_flip()

    def should_yield_for_flip_audit(self) -> bool:
        return (
            self.flip_audit_ack_path is not None
            and self.should_yield_for_completed_flip()
        )

    def _pace_completed_flip(self) -> None:
        if self.flip_audit_ack_path is not None:
            return
        started_ns = time.perf_counter_ns()
        now_ns = started_ns
        if self._next_video_frame_deadline_ns == 0:
            self._next_video_frame_deadline_ns = now_ns + self._video_frame_interval_ns
            self._record_performance("video_frame_pacing", started_ns)
            return
        deadline_ns = self._next_video_frame_deadline_ns
        if now_ns < deadline_ns:
            requested_ns = deadline_ns - now_ns
            time.sleep(requested_ns / 1_000_000_000.0)
            after_sleep_ns = time.perf_counter_ns()
            actual_sleep_us = max(0, (after_sleep_ns - now_ns) // 1_000)
            self.video_pacing_sleep_count += 1
            self.video_pacing_sleep_us += actual_sleep_us
            self.video_pacing_max_sleep_us = max(
                self.video_pacing_max_sleep_us,
                actual_sleep_us,
            )
            now_ns = after_sleep_ns
        next_deadline_ns = deadline_ns + self._video_frame_interval_ns
        if next_deadline_ns <= now_ns:
            # When guest/resource work is already late, resume immediately and
            # schedule from the actual publication time; never issue a burst
            # of catch-up flips.
            next_deadline_ns = now_ns + self._video_frame_interval_ns
        self._next_video_frame_deadline_ns = next_deadline_ns
        self._record_performance("video_frame_pacing", started_ns)

    def _wait_for_flip_ack(self, flip_index: int) -> bool:
        if self.flip_audit_ack_path is None:
            return True
        deadline = time.monotonic() + self.flip_audit_timeout_seconds
        self.audit_ack_wait_count += 1
        while True:
            self.sample_controller()
            if self.stop_requested:
                return False
            try:
                payload = self.flip_audit_ack_path.read_bytes()
            except (
                FileNotFoundError,
                PermissionError,
            ):
                payload = b""
            if len(payload) >= 20 and payload[:8] == b"B2ACK001":
                generation, acknowledged_flip = struct.unpack_from("<QI", payload, 8)
                if (
                    generation == self.command_stream_generation
                    and acknowledged_flip >= flip_index
                ):
                    return True
            if time.monotonic() >= deadline:
                raise RuntimeError(
                    f"timed out waiting for Vulkan audit acknowledgement of flip {flip_index}"
                )
            time.sleep(0.002)

    def _wait_for_presentation_ack(self, flip_index: int) -> bool:
        if self.presentation_ack_path is None:
            return True
        deadline = time.monotonic() + self.flip_audit_timeout_seconds
        self.presentation_ack_wait_count += 1
        while True:
            self.sample_controller()
            if self.stop_requested:
                return False
            if self.live_control_transport is not None:
                acknowledgement = (
                    self.live_control_transport.read_presentation_ack()
                )
                if acknowledgement is not None:
                    generation, acknowledged_flip = acknowledgement
                    if (
                        generation == self.command_stream_generation
                        and acknowledged_flip >= flip_index
                    ):
                        return True
                payload = b""
            else:
                try:
                    if (
                        self._presentation_ack_file is None
                        or self._presentation_ack_file.closed
                    ):
                        self._presentation_ack_file = self.presentation_ack_path.open(
                            "rb", buffering=0
                        )
                    self._presentation_ack_file.seek(0)
                    payload = self._presentation_ack_file.read(24)
                except (FileNotFoundError, PermissionError, OSError):
                    if self._presentation_ack_file is not None:
                        self._presentation_ack_file.close()
                        self._presentation_ack_file = None
                    payload = b""
            if len(payload) >= 24 and payload[:8] == b"B2PRS001":
                generation, acknowledged_flip = struct.unpack_from("<QQ", payload, 8)
                if (
                    generation == self.command_stream_generation
                    and acknowledged_flip >= flip_index
                ):
                    return True
            if time.monotonic() >= deadline:
                raise RuntimeError(
                    "timed out waiting for Vulkan presentation acknowledgement "
                    f"of flip {flip_index}"
                )
            if (
                self._presentation_event_handle is not None
                and self._presentation_event_kernel is not None
            ):
                self._presentation_event_kernel.WaitForSingleObject(
                    ctypes.c_void_p(self._presentation_event_handle),
                    10,
                )
            else:
                time.sleep(0.0005)

    def _flush_flip_audit_ledger(self) -> None:
        if not self._flip_audit_ledger_buffer or self.flip_audit_ledger_path is None:
            return
        self.flip_audit_ledger_path.parent.mkdir(parents=True, exist_ok=True)
        with self.flip_audit_ledger_path.open("a", encoding="utf-8", newline="\n") as ledger:
            ledger.writelines(self._flip_audit_ledger_buffer)
        self._flip_audit_ledger_buffer.clear()

    def _queue_flip_audit_ledger_record(self, record: dict[str, Any]) -> None:
        self._flip_audit_ledger_buffer.append(
            json.dumps(record, separators=(",", ":")) + "\n"
        )
        if len(self._flip_audit_ledger_buffer) >= 120:
            self._flush_flip_audit_ledger()

    def _cached_render_resource_changed(self, memory: SparseMemory) -> bool:
        for (_stage, address, _format_raw, _image_rect), (
            generations,
            resource,
        ) in (
            self._resource_snapshot_cache.items()
        ):
            byte_count = int(resource["byte_count"])
            source_address = int(resource.get("source_address", address))
            first_page = source_address & ~memory._PAGE_MASK
            last_page = (source_address + byte_count - 1) & ~memory._PAGE_MASK
            current = tuple(
                memory.visible_page_generation(page_address)
                for page_address in range(
                    first_page,
                    last_page + 1,
                    memory._PAGE_SIZE,
                )
            )
            if current != generations:
                return True
        return False

    def _flip_audit_selection_reason(
        self,
        boundary: dict[str, int],
        memory: SparseMemory,
    ) -> str | None:
        flip_index = int(boundary["flip_index"])
        write_count = int(boundary["write_count"])
        flip_value = int(boundary["flip_value"])
        write_delta = write_count - min(write_count, self._last_audit_write_count)
        reason: str | None = None
        if self.audited_flip_count == 0:
            reason = "first_flip"
        elif write_delta != self._last_audit_write_delta:
            reason = "command_shape_changed"
        elif self._last_audit_flip_value is not None and flip_value != self._last_audit_flip_value:
            reason = "flip_value_changed"
        elif self._cached_render_resource_changed(memory):
            reason = "resource_changed"
        elif (
            self.flip_audit_health_interval > 0
            and flip_index % self.flip_audit_health_interval == 0
        ):
            reason = "periodic_sample"
        if self.flip_audit_max_flips > 0 and flip_index >= self.flip_audit_max_flips:
            reason = reason or "final_flip"
        self._last_audit_write_count = write_count
        self._last_audit_write_delta = write_delta
        self._last_audit_flip_value = flip_value
        return reason

    def sample_controller(self, *, force: bool = False) -> bool:
        now = time.monotonic()
        if not force and now < self.next_controller_poll_time:
            self.controller_poll_skip_count += 1
            return False
        self.next_controller_poll_time = now + self.controller_poll_interval_seconds
        self.controller_poll_count += 1
        if self.live_control_transport is not None:
            if self.live_control_transport.stop_requested():
                self.stop_requested = True
            snapshot = self.live_control_transport.read_controller(
                self.live_controller_sequence
            )
            if snapshot is None:
                return False
            self.runtime.input.set_controller_state(
                0,
                ControllerState(
                    connected=snapshot.connected,
                    buttons=snapshot.buttons,
                    left_trigger=snapshot.left_trigger,
                    right_trigger=snapshot.right_trigger,
                    thumb_lx=snapshot.thumb_lx,
                    thumb_ly=snapshot.thumb_ly,
                    thumb_rx=snapshot.thumb_rx,
                    thumb_ry=snapshot.thumb_ry,
                ),
            )
            self.live_controller_sequence = snapshot.sequence
            self.controller_update_count += 1
            return True
        try:
            stat = self.controller_state_path.stat()
        except FileNotFoundError:
            return False
        if stat.st_mtime_ns == self.controller_mtime_ns:
            return False
        try:
            payload = json.loads(_read_text_file_shared(self.controller_state_path))
        except (
            OSError,
            UnicodeDecodeError,
            json.JSONDecodeError,
        ):
            # Keep the last valid state and retry on the next native slice if
            # publication was interrupted or the snapshot was incomplete.
            self.controller_read_defer_count += 1
            return False
        if bool(payload.get("stop", False)):
            self.stop_requested = True
        port = payload.get("ports", {}).get("0", payload.get("port0", {}))
        state = ControllerState(
            connected=bool(port.get("connected", False)),
            buttons=int(port.get("buttons", 0)) & 0xFFFF,
            left_trigger=int(port.get("left_trigger", 0)) & 0xFF,
            right_trigger=int(port.get("right_trigger", 0)) & 0xFF,
            thumb_lx=max(-32768, min(32767, int(port.get("thumb_lx", 0)))),
            thumb_ly=max(-32768, min(32767, int(port.get("thumb_ly", 0)))),
            thumb_rx=max(-32768, min(32767, int(port.get("thumb_rx", 0)))),
            thumb_ry=max(-32768, min(32767, int(port.get("thumb_ry", 0)))),
        )
        self.runtime.input.set_controller_state(0, state)
        self.controller_mtime_ns = stat.st_mtime_ns
        self.controller_update_count += 1
        self._write_json_atomic(
            self.controller_consumed_path,
            {
                "format": "b2-recomp-controller-consumed",
                "controller_update": self.controller_update_count,
                "source_mtime_ns": stat.st_mtime_ns,
                "connected": state.connected,
                "buttons": state.buttons,
            },
        )
        return True

    def should_continue_native_recovery(self) -> bool:
        """Poll host control between synchronous native frontier builds."""
        self.sample_controller()
        return not self.stop_requested

    def _synchronize_live_clock(self, now_ns: int) -> None:
        flip_delta = max(
            0,
            self.render_watchpoint.flip_count - self._clocked_flip_count,
        )
        if self._live_clock_wall_anchor_ns is None:
            if not flip_delta:
                return
            # Give the first published frame its nominal video ticks, then use
            # elapsed host time. This preserves deterministic startup while
            # preventing guest rendering throughput from stretching timers.
            self.runtime.clock.advance_100ns(flip_delta * 166_667)
            self.clock_advanced_flip_count += flip_delta
            self._clocked_flip_count = self.render_watchpoint.flip_count
            self._live_clock_wall_anchor_ns = int(now_ns)
            self._live_clock_virtual_anchor_100ns = (
                self.runtime.clock.query_interrupt_time()
            )
            return

        if flip_delta:
            self.clock_advanced_flip_count += flip_delta
            self._clocked_flip_count = self.render_watchpoint.flip_count
        assert self._live_clock_virtual_anchor_100ns is not None
        elapsed_ticks_100ns = max(
            0,
            (int(now_ns) - self._live_clock_wall_anchor_ns) // 100,
        )
        target_100ns = (
            self._live_clock_virtual_anchor_100ns + elapsed_ticks_100ns
        )
        current_100ns = self.runtime.clock.query_interrupt_time()
        advance_100ns = max(0, target_100ns - current_100ns)
        if advance_100ns:
            self.runtime.clock.advance_100ns(advance_100ns)
            self.clock_wall_sync_ticks_100ns += advance_100ns

    def on_slice(
        self,
        _state: CpuState,
        memory: SparseMemory,
        _steps: int,
        force_publish: bool = False,
    ) -> bool:
        slice_started_ns = time.perf_counter_ns()
        self.slice_exchange_count += 1
        self._synchronize_live_clock(slice_started_ns)
        if self.data_export_synchronizer is not None:
            data_export_started_ns = time.perf_counter_ns()
            self.data_export_synchronizer(memory)
            self._record_performance("data_export_sync", data_export_started_ns)
        controller_started_ns = time.perf_counter_ns()
        self.sample_controller()
        self._record_performance("controller_sample", controller_started_ns)
        if self.flip_audit_ack_path is not None:
            self._flush_render_commands(
                force=self.render_watchpoint.has_pending_flip(),
            )
            if self.render_watchpoint.has_pending_flip():
                boundaries = self.render_watchpoint.consume_pending_flip_boundaries()
                if len(boundaries) != 1:
                    raise RuntimeError(
                        "lossless flip audit observed multiple flips before a native yield"
                    )
                boundary = boundaries[0]
                health_reason = self._flip_audit_selection_reason(boundary, memory)
                if health_reason is not None:
                    selected_boundary = {**boundary, "health_reason": health_reason}
                    publish_attempt_started_ns = time.perf_counter_ns()
                    self.publish_render(
                        memory,
                        force=True,
                        audit_flip=selected_boundary,
                        guest_steps=_steps,
                    )
                    self._record_performance(
                        "publish_render_attempt",
                        publish_attempt_started_ns,
                    )
                    audit_wait_started_ns = time.perf_counter_ns()
                    acknowledged = self._wait_for_flip_ack(boundary["flip_index"])
                    self._record_performance("audit_ack_wait", audit_wait_started_ns)
                    if not acknowledged:
                        self._record_performance("on_slice_total", slice_started_ns)
                        return False
                    if self._last_published_manifest is None:
                        raise RuntimeError("lossless flip audit manifest was not retained")
                    ledger_record = self._last_published_manifest
                    self.audit_selected_flip_count += 1
                else:
                    ledger_record = {
                        "format": "b2-recomp-flip-audit-ledger-record",
                        "command_stream_generation": self.command_stream_generation,
                        "audit_flip_index": int(boundary["flip_index"]),
                        "audit_flip_value": int(boundary["flip_value"]),
                        "audit_command_record_count": int(boundary["write_count"]),
                        "audit_guest_steps": int(_steps),
                        "audit_health_selected": False,
                        "audit_health_reason": "not_selected",
                    }
                    self.audit_skipped_flip_count += 1
                if self.flip_audit_ledger_path is not None:
                    self._queue_flip_audit_ledger_record(ledger_record)
                self.audited_flip_count += 1
                if (
                    self.flip_audit_max_flips > 0
                    and self.audited_flip_count >= self.flip_audit_max_flips
                ):
                    self.stop_requested = True
                    self._flush_flip_audit_ledger()
        else:
            boundaries = (
                self.render_watchpoint.consume_pending_flip_boundaries()
                if self.render_watchpoint.has_pending_flip()
                else []
            )
            self._flush_render_commands(
                force=bool(boundaries) or force_publish,
            )
            completed_flip = boundaries[-1] if boundaries else None
            # The validated manifest is the presenter's frame boundary. Do not
            # publish an empty readiness manifest before the first completed
            # flip: live_test waits for this file before starting the host.
            should_publish_manifest = completed_flip is not None
            if should_publish_manifest:
                self._pace_completed_flip()
                publish_attempt_started_ns = time.perf_counter_ns()
                self.publish_render(
                    memory,
                    force=True,
                    completed_flip=completed_flip,
                    guest_steps=_steps,
                )
                self._record_performance(
                    "publish_render_attempt",
                    publish_attempt_started_ns,
                )
                presentation_wait_started_ns = time.perf_counter_ns()
                acknowledged = self._wait_for_presentation_ack(
                    int(completed_flip["flip_index"])
                )
                self._record_performance(
                    "presentation_ack_wait",
                    presentation_wait_started_ns,
                )
                if not acknowledged:
                    self._record_performance("on_slice_total", slice_started_ns)
                    return False
                self._cleanup_retired_snapshots()
                self._rotate_live_command_epoch(
                    completed_write_count=int(completed_flip["write_count"]),
                    completed_flip_index=int(completed_flip["flip_index"]),
                )
        self._record_performance("on_slice_total", slice_started_ns)
        return not self.stop_requested

    def summary(self) -> dict[str, Any]:
        self._close_render_command_file()
        command_transport_cursors = (
            self.live_command_transport.cursors()
            if self.live_command_transport is not None
            else None
        )
        if self._presentation_ack_file is not None:
            self._presentation_ack_file.close()
            self._presentation_ack_file = None
        if self.live_resource_transport is not None:
            self.live_resource_transport.close()
            self.live_resource_transport = None
        if self.live_command_transport is not None:
            self.live_command_transport.close()
            self.live_command_transport = None
        if self.live_control_transport is not None:
            self.live_control_transport.close()
            self.live_control_transport = None
        if (
            self._presentation_event_handle is not None
            and self._presentation_event_kernel is not None
        ):
            self._presentation_event_kernel.CloseHandle(
                ctypes.c_void_p(self._presentation_event_handle)
            )
            self._presentation_event_handle = None
        if (
            self._publication_event_handle is not None
            and self._presentation_event_kernel is not None
        ):
            self._presentation_event_kernel.CloseHandle(
                ctypes.c_void_p(self._publication_event_handle)
            )
            self._publication_event_handle = None
        self._flush_flip_audit_ledger()
        recent_guest_flip_rate_hz = 0.0
        if len(self._publish_cadence_samples) >= 2:
            first_flip, first_time = self._publish_cadence_samples[0]
            last_flip, last_time = self._publish_cadence_samples[-1]
            elapsed_seconds = max(0.0, (last_time - first_time) / 1_000_000_000.0)
            if elapsed_seconds > 0.0:
                recent_guest_flip_rate_hz = max(0, last_flip - first_flip) / elapsed_seconds
        return {
            "render_stream_path": str(self.render_stream_path),
            "render_resource_path": str(self.render_resource_path),
            "current_render_resource_path": str(self.current_render_resource_path),
            "render_command_path": str(self.render_command_path),
            "command_snapshot_base_record_count": (
                self.command_snapshot_base_record_count
            ),
            "command_epoch": self.command_epoch,
            "command_epoch_rotation_count": self.command_epoch_rotation_count,
            "command_epoch_reuse_count": self.command_epoch_reuse_count,
            "command_epoch_record_limit": self.command_epoch_record_limit,
            "command_epoch_resident_record_count": max(
                0,
                self.published_command_record_count
                - self.command_snapshot_base_record_count,
            ),
            "command_epoch_peak_resident_record_count": (
                self.command_epoch_peak_resident_record_count
            ),
            "retired_snapshot_delete_count": self.retired_snapshot_delete_count,
            "retired_snapshot_delete_bytes": self.retired_snapshot_delete_bytes,
            "controller_state_path": str(self.controller_state_path),
            "controller_consumed_path": str(self.controller_consumed_path),
            "live_control_transport": (
                {
                    "format": "b2-recomp-live-control",
                    "schema_version": LIVE_CONTROL_SCHEMA_VERSION,
                    "name": self.live_control_transport_name,
                }
                if self.live_control_transport_name is not None
                else None
            ),
            "stop_requested": self.stop_requested,
            "render_publish_count": self.render_publish_count,
            "recent_guest_flip_sample_count": len(self._publish_cadence_samples),
            "recent_guest_flip_rate_hz": round(recent_guest_flip_rate_hz, 3),
            "published_manifest_write_count": self.published_manifest_write_count,
            "last_published_manifest_flip_count": (
                self.last_published_manifest_flip_count
            ),
            "slice_exchange_count": self.slice_exchange_count,
            "render_resource_publish_count": self.render_resource_publish_count,
            "render_resource_reuse_count": self.render_resource_reuse_count,
            "render_resource_scan_count": self.render_resource_scan_count,
            "render_resource_dirty_check_count": (
                self.render_resource_dirty_check_count
            ),
            "render_resource_dirty_count": self.render_resource_dirty_count,
            "controller_update_count": self.controller_update_count,
            "controller_read_defer_count": self.controller_read_defer_count,
            "controller_poll_interval_seconds": (
                self.controller_poll_interval_seconds
            ),
            "controller_poll_count": self.controller_poll_count,
            "controller_poll_skip_count": self.controller_poll_skip_count,
            "clock_advanced_flip_count": self.clock_advanced_flip_count,
            "clock_wall_sync_ticks_100ns": self.clock_wall_sync_ticks_100ns,
            "video_pacing_target_hz": 60,
            "video_pacing_sleep_count": self.video_pacing_sleep_count,
            "video_pacing_sleep_us": self.video_pacing_sleep_us,
            "video_pacing_max_sleep_us": self.video_pacing_max_sleep_us,
            "lossless_flip_audit": self.flip_audit_ack_path is not None,
            "flip_audit_ack_path": (
                str(self.flip_audit_ack_path)
                if self.flip_audit_ack_path is not None
                else None
            ),
            "presentation_ack_path": (
                str(self.presentation_ack_path)
                if self.presentation_ack_path is not None
                else None
            ),
            "presentation_ack_wait_count": self.presentation_ack_wait_count,
            "presentation_event_name": self.presentation_event_name,
            "publication_event_name": self.publication_event_name,
            "flip_audit_ledger_path": (
                str(self.flip_audit_ledger_path)
                if self.flip_audit_ledger_path is not None
                else None
            ),
            "audited_flip_count": self.audited_flip_count,
            "audit_selected_flip_count": self.audit_selected_flip_count,
            "audit_skipped_flip_count": self.audit_skipped_flip_count,
            "audit_ack_wait_count": self.audit_ack_wait_count,
            "published_write_count": max(0, self.published_write_count),
            "direct_command_transport": self.direct_command_transport_enabled,
            "shared_command_transport": (
                {
                    "write_cursor": command_transport_cursors[0],
                    "read_cursor": command_transport_cursors[1],
                }
                if command_transport_cursors is not None
                else None
            ),
            "shared_resource_transport": (
                {
                    "slot": self.live_resource_transport_slot,
                    "size": self.live_resource_transport_size,
                }
                if self.live_control_transport_name is not None
                and self.flip_audit_ack_path is None
                else None
            ),
            "direct_command_receive_batch_count": (
                self.direct_command_receive_batch_count
            ),
            "direct_command_receive_record_count": (
                self.direct_command_receive_record_count
            ),
            "direct_command_receive_span_count": (
                self.direct_command_receive_span_count
            ),
            "direct_command_receive_payload_byte_count": (
                self.direct_command_receive_payload_byte_count
            ),
            "published_command_byte_count": self.published_command_byte_count,
            "published_command_span_count": self.published_command_span_count,
            "performance": self._performance_summary(),
        }


def _render_resource_memory_address(
    memory: SparseMemory,
    nv2a_address: int,
) -> int:
    """Resolve an NV2A physical offset to the populated Xbox CPU direct map."""

    if not 0 < nv2a_address < TITLE_XBOX_PHYSICAL_RAM_SIZE:
        return nv2a_address
    cpu_direct_address = _u32(nv2a_address | 0x80000000)
    return (
        cpu_direct_address
        if memory.has_allocated_page(cpu_direct_address)
        else nv2a_address
    )


def _snapshot_render_texture_resources(
    stream: dict[str, Any],
    history_stream: dict[str, Any],
    memory: SparseMemory,
    *,
    cache: dict[
        tuple[int, int, int, int], tuple[tuple[int, ...], dict[str, Any]]
    ] | None = None,
) -> dict[str, Any]:
    retained_bindings = history_stream.get("texture_bindings", [])
    texture_states = (
        [tuple(int(value) for value in binding) for binding in retained_bindings]
        if retained_bindings
        else _scan_render_texture_bindings(history_stream.get("writes", []))
    )
    resources: dict[tuple[int, int, int, str], dict[str, Any]] = {}
    for binding in texture_states:
        stage, address, format_raw = binding[:3]
        image_rect = binding[3] if len(binding) >= 4 else 0
        color_format = (format_raw >> 8) & 0xFF
        format_name = {
            0x05: "R5G6B5",
            0x06: "A8R8G8B8",
            0x07: "X8R8G8B8",
            0x0C: "DXT1",
            0x0E: "DXT3",
            0x0F: "DXT5",
            0x12: "A8R8G8B8_LINEAR",
            0x1E: "X8R8G8B8_LINEAR",
        }.get(color_format, f"format_{color_format:02X}")
        if format_name in {"A8R8G8B8_LINEAR", "X8R8G8B8_LINEAR"} and image_rect:
            width = (image_rect >> 16) & 0xFFFF
            height = image_rect & 0xFFFF
        else:
            width = 1 << ((format_raw >> 20) & 0xF)
            height = 1 << ((format_raw >> 24) & 0xF)
        if address == 0 or width <= 0 or height <= 0:
            continue
        declared_mipmap_levels = max(1, (format_raw >> 16) & 0xF)
        cubemap = (format_raw & (1 << 2)) != 0
        mipmap_levels = (
            1
            if format_name.endswith("_LINEAR")
            else min(declared_mipmap_levels, max(width, height).bit_length())
        )
        face_byte_count = 0
        mip_width = width
        mip_height = height
        for _ in range(mipmap_levels):
            if format_name == "DXT1":
                face_byte_count += max(
                    8,
                    ((mip_width + 3) // 4) * ((mip_height + 3) // 4) * 8,
                )
            elif format_name in {"DXT3", "DXT5"}:
                face_byte_count += max(
                    16,
                    ((mip_width + 3) // 4) * ((mip_height + 3) // 4) * 16,
                )
            elif format_name == "R5G6B5":
                face_byte_count += mip_width * mip_height * 2
            else:
                face_byte_count += mip_width * mip_height * 4
            mip_width = max(1, mip_width // 2)
            mip_height = max(1, mip_height // 2)
        face_stride = (
            (face_byte_count + 127) & ~127
            if cubemap
            else face_byte_count
        )
        byte_count = face_stride * 6 if cubemap else face_byte_count
        if byte_count > 16 * 1024 * 1024:
            continue
        resource_key = (address, width, height, format_name)
        cache_key = (stage, address, format_raw, image_rect)
        source_address = _render_resource_memory_address(memory, address)
        first_page = source_address & ~memory._PAGE_MASK
        last_page = (source_address + byte_count - 1) & ~memory._PAGE_MASK
        page_generations = tuple(
            memory.visible_page_generation(page_address)
            for page_address in range(first_page, last_page + 1, memory._PAGE_SIZE)
        )
        cached = cache.get(cache_key) if cache is not None else None
        if cached is not None and cached[0] == page_generations:
            existing = resources.get(resource_key)
            if (
                existing is None
                or int(cached[1]["byte_count"])
                > int(existing["byte_count"])
            ):
                resources[resource_key] = cached[1]
            continue
        payload = memory.read(source_address, byte_count)
        resource = {
            "stage": stage,
            "address": address,
            "address_hex": _hex32(address),
            "source_address": source_address,
            "source_address_hex": _hex32(source_address),
            "format": format_name,
            "width": width,
            "height": height,
            "cubemap": cubemap,
            "mipmap_levels": mipmap_levels,
            "face_byte_count": face_byte_count,
            "face_stride": face_stride,
            "byte_count": byte_count,
            "nonzero_byte_count": sum(byte != 0 for byte in payload),
            "sha256": hashlib.sha256(payload).hexdigest().upper(),
            "bytes_hex": payload.hex().upper(),
        }
        existing = resources.get(resource_key)
        if existing is None or byte_count > int(existing["byte_count"]):
            resources[resource_key] = resource
        if cache is not None:
            cache[cache_key] = (page_generations, resource)
    for vertex_range in history_stream.get("vertex_buffer_ranges", []):
        if not isinstance(vertex_range, (list, tuple)) or len(vertex_range) != 2:
            continue
        address = int(vertex_range[0])
        end = int(vertex_range[1])
        byte_count = end - address
        if address == 0 or byte_count <= 0 or byte_count > 16 * 1024 * 1024:
            continue
        resource_key = (address, byte_count, 1, "VERTEX_BUFFER")
        cache_key = (-1, address, byte_count, 0)
        source_address = _render_resource_memory_address(memory, address)
        first_page = source_address & ~memory._PAGE_MASK
        last_page = (source_address + byte_count - 1) & ~memory._PAGE_MASK
        page_generations = tuple(
            memory.visible_page_generation(page_address)
            for page_address in range(first_page, last_page + 1, memory._PAGE_SIZE)
        )
        cached = cache.get(cache_key) if cache is not None else None
        if cached is not None and cached[0] == page_generations:
            resources[resource_key] = cached[1]
            continue
        payload = memory.read(source_address, byte_count)
        resource = {
            "stage": 0,
            "address": address,
            "address_hex": _hex32(address),
            "source_address": source_address,
            "source_address_hex": _hex32(source_address),
            "format": "VERTEX_BUFFER",
            "width": byte_count,
            "height": 1,
            "byte_count": byte_count,
            "nonzero_byte_count": sum(byte != 0 for byte in payload),
            "sha256": hashlib.sha256(payload).hexdigest().upper(),
            "bytes_hex": payload.hex().upper(),
        }
        resources[resource_key] = resource
        if cache is not None:
            cache[cache_key] = (page_generations, resource)
    stream["resource_snapshots"] = list(resources.values())
    stream["resource_snapshot_count"] = len(resources)
    return stream


def _scan_render_texture_bindings(
    writes: list[dict[str, Any]],
) -> list[tuple[int, int, int, int]]:
    """Find texture offset/format pairs without materializing a full frame decode."""

    bindings: list[tuple[int, int, int, int]] = []
    seen: set[tuple[int, int, int, int]] = set()
    drawn_bindings: list[tuple[int, int, int, int]] = []
    drawn_seen: set[tuple[int, int, int, int]] = set()
    offsets: dict[int, int] = {}
    formats: dict[int, int] = {}
    image_rects: dict[int, int] = {}
    pending = bytearray()
    pending_end: int | None = None

    def observe_method(method: int, data: int) -> None:
        if method == 0x17FC and data != 0:
            for stage in sorted(offsets.keys() & formats.keys()):
                binding = (
                    stage,
                    offsets[stage],
                    formats[stage],
                    image_rects.get(stage, 0),
                )
                if binding not in drawn_seen:
                    drawn_seen.add(binding)
                    drawn_bindings.append(binding)
            return
        if not 0x1B00 <= method < 0x1C00:
            return
        stage = (method - 0x1B00) // 0x40
        register = (method - 0x1B00) % 0x40
        if register == 0:
            offsets[stage] = data
        elif register == 4:
            formats[stage] = data
        elif register == 0x1C:
            image_rects[stage] = data
        if stage in offsets and stage in formats:
            binding = (
                stage,
                offsets[stage],
                formats[stage],
                image_rects.get(stage, 0),
            )
            if binding not in seen:
                seen.add(binding)
                bindings.append(binding)

    def flush() -> None:
        nonlocal pending, pending_end
        words = [
            int.from_bytes(pending[offset : offset + 4], "little")
            for offset in range(0, len(pending) - (len(pending) % 4), 4)
        ]
        index = 0
        while index < len(words):
            command = words[index]
            non_increasing = False
            header_words = 1
            if (command & 0xE0030003) == 0:
                count = (command >> 18) & 0x7FF
            elif (command & 0xE0030003) == 0x40000000:
                count = (command >> 18) & 0x7FF
                non_increasing = True
            elif (command & 0xFFFF0003) == 0x00030000 and index + 1 < len(words):
                count = words[index + 1] & 0x00FFFFFF
                non_increasing = True
                header_words = 2
            else:
                index += 1
                continue
            first_method = ((command >> 2) & 0x7FF) * 4
            data_start = index + header_words
            data_end = min(data_start + count, len(words))
            for data_index in range(data_start, data_end):
                method_offset = 0 if non_increasing else data_index - data_start
                observe_method(first_method + method_offset * 4, words[data_index])
            index = data_end
        pending = bytearray()
        pending_end = None

    for write in writes:
        if write.get("kind") != "d3d_push_buffer":
            flush()
            continue
        address = int(write.get("address", 0))
        if pending and address != pending_end:
            flush()
        bytes_hex = write.get("bytes_hex")
        try:
            payload = bytes.fromhex(bytes_hex) if isinstance(bytes_hex, str) else b""
        except ValueError:
            payload = b""
        if not payload:
            size = max(1, min(int(write.get("size", 4)), 4))
            payload = int(write.get("value", 0)).to_bytes(4, "little")[:size]
        pending.extend(payload)
        pending_end = address + len(payload)
    flush()
    # Offset and format registers are often written separately. Pairing them at
    # every individual state write creates transient combinations (for example,
    # a new DXT5 format with the previous 512x512 DXT1 background address).
    # Prefer the complete state that was active when a draw actually began.
    return drawn_bindings or bindings


@dataclass(frozen=True)
class RecoveryWorkItem:
    target: int
    depth: int
    caller: int
    kind: str


@dataclass(frozen=True)
class RuntimeAbiInvocation:
    target_address: int
    shim_name: str
    ordinal: int
    subsystem: str
    guest_stack_pointer: int
    guest_return_address: int
    arguments: tuple[int, ...]
    handler_arguments: tuple[int, ...]
    return_kind: str
    eax: int | None = None
    stack_cleanup_bytes: int = 0
    result: Any = None
    memory_writes: tuple[dict[str, Any], ...] = ()

    def to_dict(self) -> dict[str, Any]:
        return {
            "target_address": self.target_address,
            "target_address_hex": _hex32(self.target_address),
            "shim_name": self.shim_name,
            "ordinal": self.ordinal,
            "subsystem": self.subsystem,
            "guest_stack_pointer": self.guest_stack_pointer,
            "guest_stack_pointer_hex": _hex32(self.guest_stack_pointer),
            "guest_return_address": self.guest_return_address,
            "guest_return_address_hex": _hex32(self.guest_return_address),
            "arguments": [_hex32(argument) for argument in self.arguments],
            "handler_arguments": [
                _hex32(argument) for argument in self.handler_arguments
            ],
            "return_kind": self.return_kind,
            "eax": self.eax,
            "eax_hex": _hex32(self.eax) if self.eax is not None else None,
            "stack_cleanup_bytes": self.stack_cleanup_bytes,
            "result": _json_safe(self.result),
            "memory_writes": [_json_safe(write) for write in self.memory_writes],
        }


def _cooperative_wait_plan(
    invocation: RuntimeAbiInvocation,
    *,
    current_interrupt_time_100ns: int,
) -> dict[str, Any] | None:
    if invocation.shim_name == "KeDelayExecutionThread":
        interval_100ns = (
            int(invocation.handler_arguments[0])
            if invocation.handler_arguments
            else 0
        )
        return {
            "kind": "deadline",
            "shim_name": invocation.shim_name,
            "interval_100ns": interval_100ns,
            "wake_interrupt_time_100ns": (
                current_interrupt_time_100ns + abs(interval_100ns)
            ),
        }
    if (
        invocation.shim_name == "NtWaitForSingleObjectEx"
        and invocation.eax == XboxStatus.WAIT_TIMEOUT
        and len(invocation.arguments) >= 4
        and invocation.arguments[3] == 0
    ):
        return {
            "kind": "runtime_handle",
            "shim_name": invocation.shim_name,
            "handle": invocation.arguments[0],
        }
    if (
        invocation.shim_name == "NtWaitForSingleObject"
        and invocation.eax == XboxStatus.WAIT_TIMEOUT
        and len(invocation.arguments) >= 3
        and invocation.arguments[2] == 0
    ):
        return {
            "kind": "runtime_handle",
            "shim_name": invocation.shim_name,
            "handle": invocation.arguments[0],
        }
    return None


def _resume_cooperative_wait(
    session: dict[str, Any],
    runtime: XboxRuntimeShims,
) -> bool:
    wait = session.get("wait")
    if not isinstance(wait, dict):
        return True
    if wait.get("kind") == "deadline":
        current_time = runtime.clock.snapshot()["interrupt_time_100ns"]
        if current_time < int(wait.get("wake_interrupt_time_100ns", 0)):
            return False
        session["state"].set_register("eax", XboxStatus.SUCCESS)
    elif wait.get("kind") == "runtime_handle":
        status = runtime.sync.wait_for_single_object(
            int(wait.get("handle", 0)),
            timeout_100ns=0,
        )
        if status == XboxStatus.WAIT_TIMEOUT:
            return False
        session["state"].set_register("eax", status)
    else:
        return True
    session.pop("wait", None)
    return True


@dataclass(frozen=True)
class RuntimeAbiResult:
    invocation: RuntimeAbiInvocation
    returned_value: Any

    def to_dict(self) -> dict[str, Any]:
        return self.invocation.to_dict()


class RuntimeAbiBridge:
    """Adapt lifted IA-32 calls to registered Python runtime shim handlers."""

    def __init__(
        self,
        runtime: XboxRuntimeShims,
        *,
        max_guest_arguments: int = DEFAULT_MAX_GUEST_ARGUMENTS,
        max_invocation_history: int = DEFAULT_RUNTIME_ABI_HISTORY,
    ) -> None:
        self.runtime = runtime
        self.defer_guest_thread_delays = False
        self.max_guest_arguments = max_guest_arguments
        self._by_target = {
            shim.target_address: shim for shim in runtime.registered_shims
        }
        self._handler_argument_counts: dict[int, int] = {}
        for shim in self._by_target.values():
            self._handler_argument_count_for(shim)
        self._guest_argument_counts = {
            target: min(
                GUEST_ARGUMENT_COUNT_OVERRIDES.get(
                    shim.name, self._handler_argument_counts[target]
                ),
                self.max_guest_arguments,
            )
            for target, shim in self._by_target.items()
        }
        self._data_exports = tuple(
            (target, shim)
            for target, shim in self._by_target.items()
            if shim.behavior == "data"
        )
        self._volatile_data_exports = tuple(
            (target, shim)
            for target, shim in self._data_exports
            if shim.name == "KeTickCount"
        )
        self._invocations: deque[RuntimeAbiInvocation] = deque(
            maxlen=max_invocation_history
        )
        self._invocation_count = 0
        self._caller_counts: Counter[tuple[str, int]] = Counter()
        self._failed_caller_counts: Counter[tuple[str, int]] = Counter()
        self._materialized_data_exports: dict[int, tuple[str, int | bytes]] = {}
        self._data_export_update_count = 0
        self._thread_lifecycle_generation = 0

    @property
    def invocations(self) -> tuple[RuntimeAbiInvocation, ...]:
        return tuple(self._invocations)

    @property
    def invocation_count(self) -> int:
        return self._invocation_count

    @property
    def thread_lifecycle_generation(self) -> int:
        return self._thread_lifecycle_generation

    @property
    def shim_targets(self) -> frozenset[int]:
        return frozenset(self._by_target)

    def has_target(self, target: int) -> bool:
        return target in self._by_target

    def guest_stack_cleanup_bytes(self, target: int) -> int:
        shim = self._by_target.get(target)
        if shim is None:
            raise RuntimeAbiBridgeError(
                f"no registered runtime shim at {_hex32(target)}"
            )
        return self._guest_argument_count_for(shim) * 4

    def can_use_shared_memory_for_handler(self, target: int) -> bool:
        """Return whether a handler can consume the bound native memory view.

        The live memory model exposes native-resident reads, commits an
        overlapping dirty page before a host write, and includes dirty native
        pages in allocation and visible-generation queries. Runtime ABI shims
        can therefore stay on the shared view; callers still choose whether a
        particular execution mode enables that path.
        """

        return True

    def call_handlers(
        self,
    ) -> dict[int, Callable[[CpuState, SparseMemory, int, ExecutionTrace], None]]:
        return {target: self.call_handler for target in self._by_target}

    def call_handler(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> None:
        self.invoke(cpu, memory, target, trace)

    def synchronize_data_exports(
        self,
        memory: SparseMemory,
        *,
        volatile_only: bool = False,
    ) -> None:
        """Materialize imported kernel scalar and fixed-size byte exports."""
        exports = (
            self._volatile_data_exports
            if volatile_only
            else self._data_exports
        )
        for target, shim in exports:
            value = shim.handler()
            if isinstance(value, bytes):
                if len(value) > self.runtime.config.host_target_stride:
                    # Larger structures need dedicated storage rather than
                    # overlapping the next fixed host target slot.
                    continue
                previous = self._materialized_data_exports.get(target)
                if previous is not None and previous[1] == value:
                    continue
                memory.write(target, value)
                self._materialized_data_exports[target] = (shim.name, value)
                self._data_export_update_count += 1
                continue
            if not isinstance(value, (bool, int)):
                continue
            scalar = _u32(int(value))
            previous = self._materialized_data_exports.get(target)
            if previous is not None and previous[1] == scalar:
                continue
            memory.write_u32(target, scalar)
            self._materialized_data_exports[target] = (shim.name, scalar)
            self._data_export_update_count += 1

    def invoke(
        self,
        cpu: CpuState,
        memory: SparseMemory,
        target: int,
        trace: ExecutionTrace,
    ) -> RuntimeAbiResult:
        shim = self._by_target.get(target)
        if shim is None:
            raise RuntimeAbiBridgeError(f"no registered runtime shim at {_hex32(target)}")

        guest_stack_pointer = cpu.get_register("esp")
        guest_return_address = memory.read_u32(guest_stack_pointer)
        guest_argument_count = self._guest_argument_count_for(shim)
        handler_argument_count = self._handler_argument_count_for(shim)
        arguments = _read_stack_arguments(
            memory, cpu.get_register("esp"), guest_argument_count
        )
        if shim.name in {"NtCreateFile", "NtOpenFile"}:
            handler_arguments = arguments
            returned_value = self._invoke_guest_file_api(shim, arguments, memory, trace)
        elif shim.name == "NtAllocateVirtualMemory":
            handler_arguments = arguments
            returned_value = self._invoke_guest_allocate_virtual_memory_api(
                arguments, memory, trace
            )
        elif shim.name == "NtCreateSemaphore":
            handler_arguments = arguments
            returned_value = self._invoke_guest_create_semaphore_api(arguments, trace)
        elif shim.name == "NtOpenSymbolicLinkObject":
            handler_arguments = arguments
            returned_value = self._invoke_guest_open_symbolic_link_api(
                arguments, memory, trace
            )
        elif shim.name == "NtQuerySymbolicLinkObject":
            handler_arguments = arguments
            returned_value = self._invoke_guest_query_symbolic_link_api(arguments, trace)
        elif shim.name == "NtQueryInformationFile":
            handler_arguments = arguments
            returned_value = self._invoke_guest_query_information_file_api(arguments, trace)
        elif shim.name == "NtQueryDirectoryFile":
            handler_arguments = arguments
            returned_value = self._invoke_guest_query_directory_file_api(
                arguments, memory, trace
            )
        elif shim.name == "NtQueryVolumeInformationFile":
            handler_arguments = arguments
            returned_value = self._invoke_guest_query_volume_information_file_api(
                arguments, trace
            )
        elif shim.name == "NtReadFile":
            handler_arguments = arguments
            returned_value = self._invoke_guest_read_file_api(arguments, memory, trace)
        elif shim.name == "NtReleaseSemaphore":
            handler_arguments = arguments[:handler_argument_count]
            try:
                returned_value = shim.handler(*handler_arguments)
            except (TypeError, XboxRuntimeError) as exc:
                trace.add(
                    None,
                    "runtime_abi_error",
                    target=target,
                    target_hex=_hex32(target),
                    shim_name=shim.name,
                    arguments=[_hex32(argument) for argument in arguments],
                    handler_arguments=[
                        _hex32(argument) for argument in handler_arguments
                    ],
                    error=str(exc),
                )
                raise RuntimeAbiBridgeError(
                    f"runtime ABI call to {shim.name} failed: {exc}"
                ) from exc
        elif shim.name == "NtSetInformationFile":
            handler_arguments = arguments
            returned_value = self._invoke_guest_set_information_file_api(arguments, memory, trace)
        elif shim.name == "NtWriteFile":
            handler_arguments = arguments
            returned_value = self._invoke_guest_write_file_api(arguments, memory, trace)
        elif shim.name == "HalReadWritePCISpace":
            handler_arguments = arguments
            returned_value = self._invoke_guest_hal_read_write_pci_space_api(
                arguments, memory, trace
            )
        elif shim.name == "KeDelayExecutionThread":
            interval_address = arguments[2] if len(arguments) >= 3 else 0
            interval_bits = (
                int.from_bytes(memory.read(interval_address, 8), "little")
                if interval_address
                else 0
            )
            interval_100ns = (
                interval_bits - (1 << 64)
                if interval_bits & (1 << 63)
                else interval_bits
            )
            handler_arguments = (interval_100ns,)
            returned_value = (
                XboxStatus.SUCCESS
                if self.defer_guest_thread_delays
                else shim.handler(*handler_arguments)
            )
        elif shim.name == "KeQuerySystemTime":
            handler_arguments = ()
            returned_value = {
                "output_address": arguments[0],
                "system_time": shim.handler(),
            }
        elif shim.name == "RtlCompareMemoryUlong":
            handler_arguments = arguments
            returned_value = self._invoke_guest_compare_memory_ulong_api(
                arguments, memory, trace
            )
        elif shim.name == "RtlEqualString":
            handler_arguments = arguments
            returned_value = self._invoke_guest_equal_string_api(
                arguments, memory, trace
            )
        elif shim.name == "ObfDereferenceObject":
            handler_arguments = (cpu.get_register("ecx"),)
            try:
                returned_value = shim.handler(*handler_arguments)
            except (TypeError, XboxRuntimeError) as exc:
                trace.add(
                    None,
                    "runtime_abi_error",
                    target=target,
                    target_hex=_hex32(target),
                    shim_name=shim.name,
                    arguments=[_hex32(argument) for argument in arguments],
                    handler_arguments=[
                        _hex32(argument) for argument in handler_arguments
                    ],
                    error=str(exc),
                )
                raise RuntimeAbiBridgeError(
                    f"runtime ABI call to {shim.name} failed: {exc}"
                ) from exc
        else:
            handler_arguments = arguments[:handler_argument_count]
            try:
                returned_value = shim.handler(*handler_arguments)
            except (TypeError, XboxRuntimeError) as exc:
                trace.add(
                    None,
                    "runtime_abi_error",
                    target=target,
                    target_hex=_hex32(target),
                    shim_name=shim.name,
                    arguments=[_hex32(argument) for argument in arguments],
                    handler_arguments=[
                        _hex32(argument) for argument in handler_arguments
                    ],
                    error=str(exc),
                )
                raise RuntimeAbiBridgeError(
                    f"runtime ABI call to {shim.name} failed: {exc}"
                ) from exc

        memory_writes = self._apply_guest_side_effects(
            shim, arguments, returned_value, memory, trace
        )
        if shim.name in {
            "PsCreateSystemThreadEx",
            "PsTerminateSystemThread",
            "NtSuspendThread",
            "NtResumeThread",
        }:
            self._thread_lifecycle_generation += 1
        # Waits and other runtime services can advance the deterministic clock.
        # Keep volatile kernel data coherent before returning to guest code.
        self.synchronize_data_exports(memory, volatile_only=True)
        return_kind, eax = _apply_return_value(cpu, returned_value)
        stack_cleanup_bytes = guest_argument_count * 4
        if stack_cleanup_bytes:
            _prepare_stdcall_return(cpu, memory, stack_cleanup_bytes)
        invocation = RuntimeAbiInvocation(
            target_address=target,
            shim_name=shim.name,
            ordinal=shim.ordinal,
            subsystem=shim.subsystem,
            guest_stack_pointer=guest_stack_pointer,
            guest_return_address=guest_return_address,
            arguments=arguments,
            handler_arguments=handler_arguments,
            return_kind=return_kind,
            eax=eax,
            stack_cleanup_bytes=stack_cleanup_bytes,
            result=_runtime_abi_result_for_summary(returned_value),
            memory_writes=tuple(memory_writes),
        )
        self._invocations.append(invocation)
        self._invocation_count += 1
        caller_key = (shim.name, guest_return_address)
        self._caller_counts[caller_key] += 1
        status = (
            returned_value.get("status")
            if isinstance(returned_value, dict)
            else returned_value
            if shim.name.startswith(("Nt", "Io", "Ob"))
            else None
        )
        if isinstance(status, int) and status & 0x80000000:
            self._failed_caller_counts[caller_key] += 1
        if trace.enabled:
            trace.add(None, "runtime_abi_call", **invocation.to_dict())
        return RuntimeAbiResult(invocation, returned_value)

    def summary(self) -> dict[str, Any]:
        subsystem_counts = Counter(shim.subsystem for shim in self._by_target.values())
        return {
            "registered_target_count": len(self._by_target),
            "registered_subsystem_counts": dict(sorted(subsystem_counts.items())),
            "invocation_count": self._invocation_count,
            "retained_invocation_count": len(self._invocations),
            "invocation_history_truncated": self._invocation_count > len(self._invocations),
            "data_export_update_count": self._data_export_update_count,
            "caller_counts": self._caller_count_summary(self._caller_counts),
            "failed_caller_counts": self._caller_count_summary(
                self._failed_caller_counts
            ),
            "materialized_data_exports": [
                self._materialized_data_export_summary(target, name, value)
                for target, (name, value) in sorted(
                    self._materialized_data_exports.items()
                )
            ],
            "invocations": [invocation.to_dict() for invocation in self._invocations],
        }

    @staticmethod
    def _materialized_data_export_summary(
        target: int, name: str, value: int | bytes
    ) -> dict[str, Any]:
        summary = {
            "name": name,
            "target_address": target,
            "target_address_hex": _hex32(target),
        }
        if isinstance(value, bytes):
            summary.update({"value_kind": "bytes", "byte_count": len(value)})
        else:
            summary.update({"value": value, "value_hex": _hex32(value)})
        return summary

    @staticmethod
    def _caller_count_summary(
        counts: Counter[tuple[str, int]],
        *,
        limit: int = 256,
    ) -> list[dict[str, Any]]:
        return [
            {
                "shim_name": shim_name,
                "guest_return_address": return_address,
                "guest_return_address_hex": _hex32(return_address),
                "invocation_count": count,
            }
            for (shim_name, return_address), count in counts.most_common(limit)
        ]

    def _guest_argument_count_for(self, shim: RuntimeShim) -> int:
        return self._guest_argument_counts[shim.target_address]

    def _handler_argument_count_for(self, shim: RuntimeShim) -> int:
        cached = self._handler_argument_counts.get(shim.target_address)
        if cached is not None:
            return cached
        signature = inspect.signature(shim.handler)
        count = 0
        for parameter in signature.parameters.values():
            if parameter.kind in {
                inspect.Parameter.POSITIONAL_ONLY,
                inspect.Parameter.POSITIONAL_OR_KEYWORD,
            }:
                count += 1
            elif parameter.kind == inspect.Parameter.VAR_POSITIONAL:
                break
        count = min(count, self.max_guest_arguments)
        self._handler_argument_counts[shim.target_address] = count
        return count

    def _invoke_guest_file_api(
        self,
        shim: RuntimeShim,
        arguments: tuple[int, ...],
        memory: SparseMemory,
        trace: ExecutionTrace,
    ) -> dict[str, Any]:
        if shim.name == "NtOpenFile":
            (
                file_handle_address,
                desired_access,
                object_attributes_address,
                io_status_block_address,
                share_access,
                open_options,
            ) = arguments[:6]
            create_disposition = None
            create_options = open_options
        else:
            (
                file_handle_address,
                desired_access,
                object_attributes_address,
                io_status_block_address,
                _allocation_size,
                _file_attributes,
                share_access,
                create_disposition,
                create_options,
            ) = arguments[:9]
        decoded = _decode_guest_object_path(memory, object_attributes_address)
        mode = _guest_file_mode(desired_access, create_disposition)
        if decoded is None:
            result: dict[str, Any] = {
                "status": XboxStatus.INVALID_PARAMETER,
                "handle": None,
                "guest_path": None,
                "decode_error": "object name not decoded",
            }
        else:
            directory_requested = (
                shim.name == "NtCreateFile"
                and bool(create_options & FILE_DIRECTORY_FILE)
            )
            if directory_requested:
                result = self.runtime.filesystem.open_directory(
                    decoded["guest_path"],
                    create_disposition=create_disposition,
                )
            else:
                result = self.runtime.filesystem.open_file(
                    decoded["guest_path"],
                    mode,
                    create_disposition=create_disposition,
                )
            result.update(decoded)
        result.update(
            {
                "file_handle_address": file_handle_address,
                "desired_access": desired_access,
                "object_attributes_address": object_attributes_address,
                "io_status_block_address": io_status_block_address,
                "share_access": share_access,
                "create_disposition": create_disposition,
                "create_options": create_options,
                "mode": mode,
            }
        )
        trace.add(
            None,
            "runtime_file_api",
            shim_name=shim.name,
            guest_path=result.get("guest_path"),
            status=result.get("status"),
            status_hex=_hex32(result.get("status", 0)),
            file_handle_address=file_handle_address,
            file_handle_address_hex=_hex32(file_handle_address),
            object_attributes_address=object_attributes_address,
            object_attributes_address_hex=_hex32(object_attributes_address),
        )
        return result

    def _invoke_guest_allocate_virtual_memory_api(
        self,
        arguments: tuple[int, ...],
        memory: SparseMemory,
        trace: ExecutionTrace,
    ) -> dict[str, Any]:
        (
            base_address_address,
            zero_bits,
            region_size_address,
            allocation_type,
            protection,
        ) = arguments[:5]
        requested_base = (
            memory.read_u32(base_address_address) if base_address_address else 0
        )
        requested_size = (
            memory.read_u32(region_size_address) if region_size_address else 0
        )
        if requested_size <= 0:
            result: dict[str, Any] = {
                "status": XboxStatus.INVALID_PARAMETER,
                "allocated_address": None,
                "allocated_size": 0,
            }
        else:
            allocation_policy = "fresh_allocation"
            allocated_address = None
            if requested_base and allocation_type & MEM_COMMIT:
                existing = self.runtime.memory.query(requested_base)
                if existing.get("status") == XboxStatus.SUCCESS:
                    allocated_address = requested_base
                    allocation_policy = "commit_existing_reservation"
            if allocated_address is None:
                allocated_address = self.runtime.memory.allocate_system_memory(
                    requested_size,
                    _guest_page_protection(protection),
                )
            result = {
                "status": XboxStatus.SUCCESS,
                "allocated_address": allocated_address,
                "allocated_size": requested_size,
                "allocation_policy": allocation_policy,
            }
        result.update(
            {
                "base_address_address": base_address_address,
                "zero_bits": zero_bits,
                "region_size_address": region_size_address,
                "allocation_type": allocation_type,
                "protection": protection,
                "protection_model": _guest_page_protection(protection),
                "requested_base": requested_base,
                "requested_size": requested_size,
            }
        )
        trace.add(
            None,
            "runtime_virtual_memory_api",
            shim_name="NtAllocateVirtualMemory",
            status=result["status"],
            status_hex=_hex32(result["status"]),
            base_address_address=base_address_address,
            base_address_address_hex=_hex32(base_address_address),
            region_size_address=region_size_address,
            region_size_address_hex=_hex32(region_size_address),
            requested_base=requested_base,
            requested_base_hex=_hex32(requested_base),
            requested_size=requested_size,
            allocated_address=result.get("allocated_address"),
            allocated_address_hex=_hex32(result["allocated_address"])
            if isinstance(result.get("allocated_address"), int)
            else None,
            allocation_type=allocation_type,
            protection=protection,
        )
        return result

    def _invoke_guest_create_semaphore_api(
        self,
        arguments: tuple[int, ...],
        trace: ExecutionTrace,
    ) -> dict[str, int]:
        if len(arguments) < 4:
            raise RuntimeAbiBridgeError(
                "NtCreateSemaphore expected handle pointer, object attributes, "
                "initial count, and limit"
            )
        handle_address, object_attributes, initial_count, limit = arguments[:4]
        try:
            handle = self.runtime.nt_create_semaphore(initial_count, limit)
        except XboxRuntimeError as exc:
            trace.add(
                None,
                "runtime_semaphore_api_error",
                shim_name="NtCreateSemaphore",
                handle_address=handle_address,
                handle_address_hex=_hex32(handle_address),
                object_attributes=object_attributes,
                object_attributes_hex=_hex32(object_attributes),
                initial_count=initial_count,
                limit=limit,
                error=str(exc),
            )
            raise RuntimeAbiBridgeError(
                f"runtime ABI call to NtCreateSemaphore failed: {exc}"
            ) from exc
        result = {
            "status": XboxStatus.SUCCESS,
            "handle": handle,
            "handle_address": handle_address,
            "object_attributes": object_attributes,
            "initial_count": initial_count,
            "limit": limit,
        }
        trace.add(
            None,
            "runtime_semaphore_api",
            shim_name="NtCreateSemaphore",
            handle=handle,
            handle_hex=_hex32(handle),
            handle_address=handle_address,
            handle_address_hex=_hex32(handle_address),
            object_attributes=object_attributes,
            object_attributes_hex=_hex32(object_attributes),
            initial_count=initial_count,
            limit=limit,
        )
        return result

